INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海面上；海洋之上。", "primary_collocate": null, "pronunciation": "hǎi shàng", "ipa": "xaɪ˨˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "海上漂着一个红色的球。", "target_word": "海上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮升起来，海上很亮。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一艘大船慢慢开到海上。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在海上钓了一整天鱼。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的风吹得人很冷。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海上来了几只小船。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在海上飞了两个小时。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上起雾了，什么也看不见。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时常在海上打鱼。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的浪一个比一个高。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "海面之上、海洋之上的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海上", "is_correct": true, "explanation": "正确：海上指海面之上，球可以漂在水面上，符合句意。"}, {"text": "地面", "is_correct": false, "explanation": "语义：地面是坚硬的固体，球不能漂在上面，句子说不通。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“漂”多用于水面或空中，“书桌”不能与“漂着”搭配。"}, {"text": "石板路", "is_correct": false, "explanation": "语义：石板路是坚硬的路面，球不能漂在上面，句子说不通。"}], "explanations": {"海上": "正确：海上指海面之上，球可以漂在水面上，符合句意。", "地面": "语义：地面是坚硬的固体，球不能漂在上面，句子说不通。", "书桌": "搭配：“漂”多用于水面或空中，“书桌”不能与“漂着”搭配。", "石板路": "语义：石板路是坚硬的路面，球不能漂在上面，句子说不通。"}, "sentence_index": 0, "correct_answer": "海上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海上长着很多椰子树。", "explanation": "这里应该用〈岛上〉。椰子树生长在陆地上，海上指水面，不能说长着椰子树。"}, {"text": "海上跑着很多汽车。", "explanation": "这里应该用〈陆上〉。汽车在陆地上行驶，海上指水面，不能说汽车跑在海上。"}, {"text": "海上跑着很多马。", "explanation": "这里应该用〈草原上〉。马在草原上奔跑，海上指水面，不能这样表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海上", "is_correct": true, "explanation": "正确：飞机可以在海面上空飞行，符合句意。"}, {"text": "地下", "is_correct": false, "explanation": "语义：地下没有空间让飞机飞行，句子说不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间太小，飞机无法在里面飞行，句子说不通。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：“飞”的地点不说地铁站，与“飞机”搭配不当。"}], "explanations": {"海上": "正确：飞机可以在海面上空飞行，符合句意。", "地下": "语义：地下没有空间让飞机飞行，句子说不通。", "房间": "语义：房间太小，飞机无法在里面飞行，句子说不通。", "地铁站": "搭配：“飞”的地点不说地铁站，与“飞机”搭配不当。"}, "sentence_index": 6, "correct_answer": "海上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海上的树一棵比一棵高。", "explanation": "这里应该用〈山上〉。树生长在陆地上，海上指水面，不能说海上的树。"}, {"text": "海上的沙丘一座比一座高。", "explanation": "这里应该用〈沙漠里〉。沙丘是陆地上的沙堆，海上没有沙丘。"}, {"text": "海上的麦子一片比一片黄。", "explanation": "这里应该用〈农田里〉。麦子种在陆地的农田里，海上不能长麦子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔民在海上里捕鱼。", "corrected_sentence": "渔民在海上捕鱼。", "error_description": "“海上”后面不能加“里”，应说“在海上捕鱼”。“海上里”不是地点词语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一艘货船在海上的航行了一天。", "corrected_sentence": "一艘货船在海上航行了一天。", "error_description": "“海上”后面不能直接加“的”，应说“在海上航行”。加上“的”后“航行”变成名词性成分，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
