INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打新是花钱去买新出来的股票，希望它以后值钱。", "primary_collocate": null, "pronunciation": "dǎ xīn", "ipa": "ta˨˩ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "哥哥花了一万块钱去打新。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想打新，希望新股以后涨价。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不懂股票，不敢打新。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打新中了签，今天很高兴。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打新的时候，我只花了很少的钱。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事们下班后都在讨论怎么打新。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去年打新赚了钱，今年还想再碰碰运气。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想打新，可是账户里没有钱。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李每次打新都先看公司的消息。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把一部分钱拿去打新。", "target_word": "打新", "complexity_tier": "T3", "furigana": "tā bǎ yí bù fèn qián ná qù dǎ xīn", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "花钱买新股，期望以后升值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打新", "is_correct": true, "explanation": "正确：打新指花钱申购新股，符合“花了一万块钱”的语境。"}, {"text": "喝水", "is_correct": false, "explanation": "语义：花一万块钱去喝水不符合常理，句子说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是花钱能去做的事，句子说不通。"}, {"text": "退休", "is_correct": false, "explanation": "配价：“退休”不能与“去”加动词结构表示花钱的目的，搭配不成立。"}], "explanations": {"打新": "正确：打新指花钱申购新股，符合“花了一万块钱”的语境。", "喝水": "语义：花一万块钱去喝水不符合常理，句子说不通。", "咳嗽": "语义：咳嗽不是花钱能去做的事，句子说不通。", "退休": "配价：“退休”不能与“去”加动词结构表示花钱的目的，搭配不成立。"}, "sentence_index": 0, "correct_answer": "打新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸把积蓄打新在房子上，我们都觉得很划算。", "explanation": "这里应该用〈投资〉。打新只是申购新股，把积蓄用在买房子上应说“投资”。"}, {"text": "他用积蓄打新，开了一家小吃店，生意很好。", "explanation": "这里应该用〈创办〉。打新只指申购新发行的股票，开店做生意要说“创办”。"}, {"text": "他去超市打新，买了很多大米，等待涨价。", "explanation": "这里应该用〈囤积〉。打新只指申购新股，囤积大米等待涨价要说“囤积”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打新", "is_correct": true, "explanation": "正确：他去年申购新股赚了钱，与句意吻合。"}, {"text": "高考", "is_correct": false, "explanation": "语义：高考是考试，与“赚钱”无关，句子说不通。"}, {"text": "发福", "is_correct": false, "explanation": "体貌：“发福”描述身体变胖，不能说“发福赚了钱”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不能带来收入，与“赚了钱”矛盾，句子说不通。"}], "explanations": {"打新": "正确：他去年申购新股赚了钱，与句意吻合。", "高考": "语义：高考是考试，与“赚钱”无关，句子说不通。", "发福": "体貌：“发福”描述身体变胖，不能说“发福赚了钱”。", "生病": "语义：生病不能带来收入，与“赚了钱”矛盾，句子说不通。"}, "sentence_index": 6, "correct_answer": "打新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去商场打新，付完钱拿着东西走了。", "explanation": "这里应该用〈结账〉。打新只用于申购新发行的股票，在商场付款要说“结账”。"}, {"text": "她去银行打新，存了一笔定期。", "explanation": "这里应该用〈存钱〉。打新只指申购新发行的股票，存定期要说“存钱”。"}, {"text": "很多人在网上打新限量球鞋。", "explanation": "这里应该用〈抢购〉。打新是申购新股，抢购球鞋要说“抢购”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打新过赚了不少钱。", "corrected_sentence": "他打过新赚了不少钱。", "error_description": "错误：“打新过赚了不少钱”。正确：“打过新赚了不少钱”。“过”表示曾经的经历，应紧跟动词“打”，不能放在“打新”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她去年开始打新过，赚了一些钱。", "corrected_sentence": "她去年开始打新，赚了一些钱。", "error_description": "错误：“开始打新过”。正确：“开始打新”。“过”表示曾经有过的经历，不能用在表示开始的动作之后，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
