INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指投资者申购新发行的股票。", "primary_collocate": null, "pronunciation": "dǎ xīn", "ipa": "ta˨˩ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "他每个月都用手机打新。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打新要先在证券账户里放一些钱。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友靠打新赚了一点钱。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天有三只新股，我想去打新。", "target_word": "打新", "complexity_tier": "T3", "furigana": "jīn tiān yǒu sān zhī xīn gǔ wǒ xiǎng qù dǎ xīn", "sentence_source": "generated"}, {"text": "她刚开了证券账户，准备打新。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打新不一定每次都能中签。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸退休后喜欢打新，也喜欢看股票新闻。", "target_word": "打新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周打新的人比上周多。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天晚上忘了打新，很后悔。", "target_word": "打新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，打新也有风险，不要借钱。", "target_word": "打新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "投资者申购新发行的股票", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打新", "is_correct": true, "explanation": "正确：打新指用手机申购新股，符合句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡不能借助手机完成，句子说不通。"}, {"text": "退休", "is_correct": false, "explanation": "配价：“退休”是不及物动词，不能用“用手机”引出工具。"}, {"text": "剪发", "is_correct": false, "explanation": "语义：用手机剪发不符合常识，句子说不通。"}], "explanations": {"打新": "正确：打新指用手机申购新股，符合句意。", "洗澡": "语义：洗澡不能借助手机完成，句子说不通。", "退休": "配价：“退休”是不及物动词，不能用“用手机”引出工具。", "剪发": "语义：用手机剪发不符合常识，句子说不通。"}, "sentence_index": 0, "correct_answer": "打新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在市场上打新买了一只已经上市的股票。", "explanation": "这里应该用〈交易〉。打新只指申购尚未上市的新股，买卖已经上市的股票要说“交易”。"}, {"text": "我在银行打新，选中了一款理财产品。", "explanation": "这里应该用〈认购〉。打新只用于申购新发行的股票，购买理财产品要说“认购”。"}, {"text": "很多人在网上打新那款限量手机。", "explanation": "这里应该用〈抢购〉。打新只用于申购新股，抢购手机要说“抢购”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打新", "is_correct": true, "explanation": "正确：打新指申购新股，爸爸退休后喜欢做这件事，与句意吻合。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：退休后的人不再工作，与“退休后”矛盾，句子说不通。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针是治病的事，不是退休后的爱好，句子说不通。"}, {"text": "高考", "is_correct": false, "explanation": "语义：高考只针对考生，与退休的人无关，句子说不通。"}], "explanations": {"打新": "正确：打新指申购新股，爸爸退休后喜欢做这件事，与句意吻合。", "辞职": "语义：退休后的人不再工作，与“退休后”矛盾，句子说不通。", "打针": "语义：打针是治病的事，不是退休后的爱好，句子说不通。", "高考": "语义：高考只针对考生，与退休的人无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "打新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去超市打新，挑了一些水果。", "explanation": "这里应该用〈选购〉。打新只用于申购新股，在超市挑选水果要说“选购”。"}, {"text": "我在网上打新，买到了一套新书。", "explanation": "这里应该用〈订购〉。打新不指购买图书，网上买书要说“订购”。"}, {"text": "爷爷每天早上都去公园打新，练太极。", "explanation": "这里应该用〈晨练〉。打新只指申购新股，早上在公园锻炼身体要说“晨练”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打新过，知道要先开户。", "corrected_sentence": "我打过新，知道要先开户。", "error_description": "“过”应紧跟动词，说“打过新”。错误形式把“过”放在了“打新”之后，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去打新过，中了签。", "corrected_sentence": "我去打新，中了签。", "error_description": "错误：“打新过”。正确：“打新”。“过”表示曾经有过的经历，应紧跟动词（如“打过新”）。这里叙述的是去申购这一次，不需要“过”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
