INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预防和扑灭火灾。", "primary_collocate": null, "pronunciation": "xiāo fáng", "ipa": "ɕjɑʊ˥ fɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校很重视消防。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼的消防做得很好。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责学校的消防。", "target_word": "消防", "complexity_tier": "T3", "furigana": "tā fù zé xué xiào de xiāo fáng。", "sentence_source": "generated"}, {"text": "商场的消防不合格。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习消防。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年都检查消防。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给孩子们讲消防。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的消防还不太好。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就对消防感兴趣。", "target_word": "消防", "complexity_tier": "T3", "furigana": "tā cóng xiǎo jiù duì xiāo fáng gǎn xìng qù。", "sentence_source": "generated"}, {"text": "为了安全，公司加强了消防。", "target_word": "消防", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消防队", "label": "复合"}, {"form": "消防车", "label": "复合"}], "register": "中性", "sense_fingerprint": "预防和扑灭火灾的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '086a2607-6390-45a4-bc25-eb84138f39a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消防", "is_correct": true, "explanation": "消防（xiāo fáng）：预防和扑灭火灾的工作。"}, {"text": "效仿", "is_correct": false, "explanation": "效仿（xiào fǎng）两个音节的声调都与 xiāo fáng 不同，意思是模仿。"}, {"text": "校方", "is_correct": false, "explanation": "校方（xiào fāng）两个音节的声调都与 xiāo fáng 不同，意思是学校一方。"}, {"text": "小房", "is_correct": false, "explanation": "小房（xiǎo fáng）第一音节声调与 xiāo 不同（第三声），意思是小屋。"}], "explanations": {"消防": "消防（xiāo fáng）：预防和扑灭火灾的工作。", "效仿": "效仿（xiào fǎng）两个音节的声调都与 xiāo fáng 不同，意思是模仿。", "校方": "校方（xiào fāng）两个音节的声调都与 xiāo fáng 不同，意思是学校一方。", "小房": "小房（xiǎo fáng）第一音节声调与 xiāo 不同（第三声），意思是小屋。"}, "sentence_index": null, "correct_answer": "消防"}, "level_3": {"options": [{"text": "消防", "is_correct": true, "explanation": "“学校很重视消防”，消防指防火、灭火的工作，符合句意。"}, {"text": "盐", "is_correct": false, "explanation": "语义：“学校很重视盐”不通，盐不是学校会特别重视的事项，与句意不合。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：学校不会以“很重视”来形容校外的饭馆，与句意不合。"}, {"text": "酒吧", "is_correct": false, "explanation": "语义：酒吧与学校的语境不符，“学校很重视酒吧”说不通。"}], "explanations": {"消防": "“学校很重视消防”，消防指防火、灭火的工作，符合句意。", "盐": "语义：“学校很重视盐”不通，盐不是学校会特别重视的事项，与句意不合。", "饭馆": "语义：学校不会以“很重视”来形容校外的饭馆，与句意不合。", "酒吧": "语义：酒吧与学校的语境不符，“学校很重视酒吧”说不通。"}, "sentence_index": 0, "correct_answer": "消防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们冲进火场，吃了一口消防。", "explanation": "这里应该用〈救火〉。“吃”的对象应是食物，“消防”指工作，不能吃。"}, {"text": "这座商场的一只消防不合格。", "explanation": "量词错误：“消防”指工作，不用〈只〉（〈只〉用于某些动物），这里应直接说“消防不合格”。"}, {"text": "他拿起消防，对着火苗喷了一阵。", "explanation": "这里应该用〈灭火器〉。“消防”指工作，不指器具，拿着对准火苗喷的是灭火器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消防", "is_correct": true, "explanation": "“老师给孩子们讲消防”，消防作为讲授的内容，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讲”接的是知识、道理或故事，不能说“讲窗户”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是讲授的内容，“老师给孩子们讲厨房”说不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“讲饭菜”不符合“老师给孩子们讲”的语境，句子不通。"}], "explanations": {"消防": "“老师给孩子们讲消防”，消防作为讲授的内容，符合句意。", "窗户": "搭配：“讲”接的是知识、道理或故事，不能说“讲窗户”。", "厨房": "语义：厨房是场所，不是讲授的内容，“老师给孩子们讲厨房”说不通。", "饭菜": "语义：“讲饭菜”不符合“老师给孩子们讲”的语境，句子不通。"}, "sentence_index": 6, "correct_answer": "消防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了网络安全，我们给电脑装了消防。", "explanation": "这里应该用〈防火墙〉。“消防”指预防和扑灭火灾的工作，不能用于网络安全；网络防护要说防火墙。"}, {"text": "一楼的消防很甜。", "explanation": "这里应该用〈完善〉。“甜”形容味道，“消防”是工作，不能说“很甜”。"}, {"text": "为了安全，公司加强了一块消防。", "explanation": "量词错误：“消防”不用〈块〉，这里应直接说“加强了消防”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼的一个消防很完善。", "corrected_sentence": "这栋楼的消防很完善。", "error_description": "多加了量词：“消防”指工作，修饰时不用“一个”，应说“这栋楼的消防很完善”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他消防很感兴趣。", "corrected_sentence": "他对消防很感兴趣。", "error_description": "漏掉介词“对”：“感兴趣”的对象要用“对……”引出，应说“对消防很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa050c04-13bc-44c8-9221-03f1c0957b04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
