INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "县名是一个县的名字。", "primary_collocate": null, "pronunciation": "xiàn míng", "ipa": "ɕjɛn⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这个县名很好记。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个县名怎么读吗？", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个县名。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡是个小县，县名很少有人知道。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名是从一条河来的。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的县名太小，我看不清。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名里有一个“安”字。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把县名写在这张纸上。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了那个县名，只记得在山东。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个县名听起来很像。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个县的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08cebff2-181f-4f57-a972-8a5dfd43b209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指一个县的名字，读作 xiàn míng。"}, {"text": "县民", "is_correct": false, "explanation": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。"}, {"text": "巷名", "is_correct": false, "explanation": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。"}, {"text": "鲜明", "is_correct": false, "explanation": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是鲜明、清楚。"}, {"text": "贤明", "is_correct": false, "explanation": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}], "explanations": {"县名": "正确。县名指一个县的名字，读作 xiàn míng。", "县民": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。", "巷名": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。", "鲜明": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是鲜明、清楚。", "贤明": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名是县的名称，放在“这个……很好记”中，说的是这个县的名字容易记住。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很好记”多用于名字、号码等，空气不能这样说。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”可以说好或不好，但不能说“很好记”，“记”不搭配“心情”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是随时变化的自然状况，不是可以“记”的对象。"}], "explanations": {"县名": "正确。县名是县的名称，放在“这个……很好记”中，说的是这个县的名字容易记住。", "空气": "搭配：“很好记”多用于名字、号码等，空气不能这样说。", "心情": "搭配：“心情”可以说好或不好，但不能说“很好记”，“记”不搭配“心情”。", "天气": "语义：天气是随时变化的自然状况，不是可以“记”的对象。"}, "sentence_index": 0, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去过县名，那里的路很宽。", "explanation": "这里应该用〈县城〉。“去过”后面要接可以到达的地方，县名只是县的名称，不能当作地点。"}, {"text": "这只猫的县名很好听。", "explanation": "这里应该用〈名字〉。县名只指县的名称，猫的名字要说“名字”。"}, {"text": "我们在县名里买东西。", "explanation": "这里应该用〈城市〉。县名是名称，不是可以“在……里”的地点，买东西要说城市或商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93673, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指一个县的名字，读作 xiàn míng。"}, {"text": "线民", "is_correct": false, "explanation": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。"}, {"text": "显明", "is_correct": false, "explanation": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。"}, {"text": "贤名", "is_correct": false, "explanation": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}], "explanations": {"县名": "正确。县名指一个县的名字，读作 xiàn míng。", "线民": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。", "显明": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。", "贤名": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。“这个……里有一个“安”字”需要一个名称，县名正好可以含有字。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，里面不会有一个写出来的“安”字。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听得见的，不能像文字那样“有一个字”。"}, {"text": "雨水", "is_correct": false, "explanation": "配价：“里有一个……字”要求前面是能写字的载体，“雨水”不能充当这样的地点。"}], "explanations": {"县名": "正确。“这个……里有一个“安”字”需要一个名称，县名正好可以含有字。", "空气": "语义：空气看不见，里面不会有一个写出来的“安”字。", "声音": "语义：声音是听得见的，不能像文字那样“有一个字”。", "雨水": "配价：“里有一个……字”要求前面是能写字的载体，“雨水”不能充当这样的地点。"}, "sentence_index": 6, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是县名的干部。", "explanation": "这里应该用〈县〉。“县的干部”指属于县的工作人员，县名只是名称，不能这样说。"}, {"text": "这个县名很安静。", "explanation": "这里应该用〈地方〉。县名是名称，不能用“安静”来形容，描述地方的情况才用这种说法。"}, {"text": "他把这个县名存进了银行。", "explanation": "这里应该用〈钱〉。“存”的对象是钱，县名只是名称，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条县名是从古代流传下来的。", "corrected_sentence": "这个县名是从古代流传下来的。", "error_description": "量词错误：“县名”应搭配“个”，“条”用于细长的东西，应把“这条县名”改为“这个县名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这个县名写地图上。", "corrected_sentence": "请你把这个县名写在地图上。", "error_description": "配价错误：“写”后面表示地点要用介词“在”，应说“写在地图上”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
