INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "县的名称。", "primary_collocate": null, "pronunciation": "xiàn míng", "ipa": "ɕjɛn⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "县名要写在表格第一行。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名以前不叫这个。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背出了全省所有的县名。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个县名里有“水”字？", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县名改了以后，路牌也换了。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上每个县名都用小字写。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名我第一次听说。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名表上要填县名和地址。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们比赛看谁记的县名多。", "target_word": "县名", "complexity_tier": "T3", "furigana": "xiàn míng", "sentence_source": "generated"}, {"text": "这个县名是用人名起的。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "县的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08cebff2-181f-4f57-a972-8a5dfd43b209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指县的名称，读作 xiàn míng。"}, {"text": "县民", "is_correct": false, "explanation": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。"}, {"text": "巷名", "is_correct": false, "explanation": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。"}, {"text": "鲜明", "is_correct": false, "explanation": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是鲜明、清楚。"}, {"text": "贤明", "is_correct": false, "explanation": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}], "explanations": {"县名": "正确。县名指县的名称，读作 xiàn míng。", "县民": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。", "巷名": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。", "鲜明": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是鲜明、清楚。", "贤明": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名是县的名称，可以写在表格的第一行。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是一种声音，不是需要登记的名称，与“写在表格第一行”不合。"}, {"text": "肉汤", "is_correct": false, "explanation": "语义：肉汤是食物，不是需要登记的名称，与“写在表格第一行”不合。"}, {"text": "名讳", "is_correct": false, "explanation": "语域：“名讳”是敬辞，只用于称呼他人的名字，不能出现在表格上。"}], "explanations": {"县名": "正确。县名是县的名称，可以写在表格的第一行。", "雷声": "语义：雷声是一种声音，不是需要登记的名称，与“写在表格第一行”不合。", "肉汤": "语义：肉汤是食物，不是需要登记的名称，与“写在表格第一行”不合。", "名讳": "语域：“名讳”是敬辞，只用于称呼他人的名字，不能出现在表格上。"}, "sentence_index": 0, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的县名是李明。", "explanation": "这里应该用〈名字〉。县名只指县的名称，人的名字要说“名字”。"}, {"text": "这个县名很大，人口很多。", "explanation": "这里应该用〈城市〉。县名是名称，不能用“很大”来形容，说城市的规模才用这种说法。"}, {"text": "这个湖的县名很有意思。", "explanation": "这里应该用〈地名〉。湖是地理事物，县名只指县的名称，说湖的名称要用“地名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指县的名称，读作 xiàn míng。"}, {"text": "线民", "is_correct": false, "explanation": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。"}, {"text": "显明", "is_correct": false, "explanation": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。"}, {"text": "贤名", "is_correct": false, "explanation": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}], "explanations": {"县名": "正确。县名指县的名称，读作 xiàn míng。", "线民": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。", "显明": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。", "贤名": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。“这个……我第一次听说”说的是一个县的名字。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是人人都接触的东西，不会“第一次听说”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是眼睛看到的景象，不是可以“听说”的对象。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，用于称呼他人的名字，不能指地名。"}], "explanations": {"县名": "正确。“这个……我第一次听说”说的是一个县的名字。", "空气": "语义：空气是人人都接触的东西，不会“第一次听说”。", "天空": "语义：天空是眼睛看到的景象，不是可以“听说”的对象。", "芳名": "语域：“芳名”是敬辞，用于称呼他人的名字，不能指地名。"}, "sentence_index": 6, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这个县名教书。", "explanation": "这里应该用〈县〉。“在……教书”要接地点，县名只是名称，不能表示地点。"}, {"text": "我把这个县名借给了同学。", "explanation": "这里应该用〈书〉。“借”的对象是书或物品，县名只是名称，不能借给别人。"}, {"text": "我喜欢吃这个县名。", "explanation": "这里应该用〈菜〉。“吃”的对象是食物，县名只是名称，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下子记住了两只县名。", "corrected_sentence": "他一下子记住了两个县名。", "error_description": "量词错误：“县名”应搭配“个”，“只”用于动物，应把“两只县名”改为“两个县名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把县名抄本子上。", "corrected_sentence": "请把县名抄在本子上。", "error_description": "配价错误：“抄”后面表示地点要用介词“在”，应说“抄在本子上”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd53ef67-7a4e-4670-925a-4fa791d8afc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赏", "is_correct": true, "explanation": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。"}, {"text": "送", "is_correct": false, "explanation": "“送”指把东西交给别人，与“处罚”这一义项没有对应关系。"}, {"text": "请", "is_correct": false, "explanation": "“请”指邀请或礼貌地要求，与“处罚”这一义项没有对应关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指用笔记录文字，与“处罚”这一义项没有对应关系。"}], "correct_answer": "赏", "explanations": {"赏": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。", "送": "“送”指把东西交给别人，与“处罚”这一义项没有对应关系。", "请": "“请”指邀请或礼貌地要求，与“处罚”这一义项没有对应关系。", "写": "“写”指用笔记录文字，与“处罚”这一义项没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赏", "is_correct": true, "explanation": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。"}, {"text": "教", "is_correct": false, "explanation": "“教”指传授知识或技能，与“处罚”这一义项没有对应关系。"}, {"text": "买", "is_correct": false, "explanation": "“买”指花钱取得东西，与“处罚”这一义项没有对应关系。"}, {"text": "讲", "is_correct": false, "explanation": "“讲”指陈述或解释，与“处罚”这一义项没有对应关系。"}], "correct_answer": "赏", "explanations": {"赏": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。", "教": "“教”指传授知识或技能，与“处罚”这一义项没有对应关系。", "买": "“买”指花钱取得东西，与“处罚”这一义项没有对应关系。", "讲": "“讲”指陈述或解释，与“处罚”这一义项没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对违反规定或犯错的人给予处分。", "primary_collocate": null, "pronunciation": "fá", "ipa": "fa˧˥", "syllable_count": 1, "sentences": [{"text": "他犯了错，老师罚他站在门外。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车闯红灯，警察会罚钱。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班迟到，老板罚了他五十块钱。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明没写作业，老师罚他抄课文。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员严重犯规，裁判罚他下场。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这里乱扔垃圾，要罚二百元。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说了谎，爸爸罚过他一次。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁把杯子打破了，我就罚谁洗碗。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机停车超时，交警罚了他一百元。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时他违反规则，裁判罚了他两分钟。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罚了", "label": "体标"}, {"form": "罚过", "label": "体标"}, {"form": "罚款", "label": "复合"}, {"form": "处罚", "label": "复合"}, {"form": "罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：对犯错或违规的人给予处分，如罚钱、罚站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罚", "is_correct": true, "explanation": "罚 fá：对犯错或违规的人给予处分，正是本义。"}, {"text": "发", "is_correct": false, "explanation": "发 fā（第一声）与 fá（第二声）声调不同，意思是发出、发送。"}, {"text": "法", "is_correct": false, "explanation": "法 fǎ（第三声）与 fá（第二声）声调不同，意思是法律、方法。"}, {"text": "华", "is_correct": false, "explanation": "华 huá 与 fá 声母不同（h 与 f），意思是中华、华丽。"}, {"text": "烦", "is_correct": false, "explanation": "烦 fán 比 fá 多一个鼻音韵尾 n，意思是烦恼、麻烦。"}], "explanations": {"罚": "罚 fá：对犯错或违规的人给予处分，正是本义。", "发": "发 fā（第一声）与 fá（第二声）声调不同，意思是发出、发送。", "法": "法 fǎ（第三声）与 fá（第二声）声调不同，意思是法律、方法。", "华": "华 huá 与 fá 声母不同（h 与 f），意思是中华、华丽。", "烦": "烦 fán 比 fá 多一个鼻音韵尾 n，意思是烦恼、麻烦。"}, "sentence_index": null, "correct_answer": "罚"}, "level_3": {"options": [{"text": "罚", "is_correct": true, "explanation": "“罚”指对犯错的人给予处分，与“他犯了错”“站在门外”的语境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与“他犯了错”的语境相反。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给好处，不能用来让人“站在门外”。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带受事和接受者（送他东西），不能直接接“站在门外”这样的动词短语。"}], "explanations": {"罚": "“罚”指对犯错的人给予处分，与“他犯了错”“站在门外”的语境相符。", "表扬": "语义：“表扬”是褒奖，与“他犯了错”的语境相反。", "奖励": "语义：“奖励”是给好处，不能用来让人“站在门外”。", "送": "配价：“送”要带受事和接受者（送他东西），不能直接接“站在门外”这样的动词短语。"}, "sentence_index": 0, "correct_answer": "罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他罚了一个好主意，大家都夸他聪明。", "explanation": "这里应该用〈想出〉。罚是给予处分，不能与“主意”搭配；想出主意要说“想出”。"}, {"text": "他把电视机罚坏了，修了三天才好。", "explanation": "这里应该用〈弄〉。罚是给予处分，不表示损坏；把东西弄坏要说“弄坏”。"}, {"text": "她把答案罚错了，老师没有看出来。", "explanation": "这里应该用〈算〉。罚是给予处分，不表示计算；算错答案要说“算错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罚", "is_correct": true, "explanation": "罚 fá：对犯错或违规的人给予处分，正是本义。"}, {"text": "房", "is_correct": false, "explanation": "房 fáng 比 fá 多一个韵尾 ng，意思是房子。"}, {"text": "凡", "is_correct": false, "explanation": "凡 fán 比 fá 多一个鼻音韵尾 n，意思是凡是、所有。"}, {"text": "拔", "is_correct": false, "explanation": "拔 bá 与 fá 声母不同（b 与 f），意思是拔出。"}, {"text": "滑", "is_correct": false, "explanation": "滑 huá 与 fá 声母不同（h 与 f），意思是光滑。"}], "explanations": {"罚": "罚 fá：对犯错或违规的人给予处分，正是本义。", "房": "房 fáng 比 fá 多一个韵尾 ng，意思是房子。", "凡": "凡 fán 比 fá 多一个鼻音韵尾 n，意思是凡是、所有。", "拔": "拔 bá 与 fá 声母不同（b 与 f），意思是拔出。", "滑": "滑 huá 与 fá 声母不同（h 与 f），意思是光滑。"}, "sentence_index": null, "correct_answer": "罚"}, "level_3": {"options": [{"text": "罚", "is_correct": true, "explanation": "“罚”指对犯错的人给予处分，与“弟弟说了谎”的语境相符。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”是肯定和褒奖，与“说了谎”的语境矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”针对好的行为，不能用来回应“说了谎”。"}, {"text": "包", "is_correct": false, "explanation": "配价：“包”要接事物宾语，不能组成“包过他一次”这样的人与次数结构。"}], "explanations": {"罚": "“罚”指对犯错的人给予处分，与“弟弟说了谎”的语境相符。", "赞扬": "语义：“赞扬”是肯定和褒奖，与“说了谎”的语境矛盾。", "夸奖": "语义：“夸奖”针对好的行为，不能用来回应“说了谎”。", "包": "配价：“包”要接事物宾语，不能组成“包过他一次”这样的人与次数结构。"}, "sentence_index": 6, "correct_answer": "罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弄坏了邻居的自行车，要罚给邻居两百块。", "explanation": "这里应该用〈赔〉。罚是给予处分，不指赔偿他人的损失；赔偿要说“赔”。"}, {"text": "老师罚他一朵小红花，因为他帮助了同学。", "explanation": "“罚”只表示处分，不能用来表示奖励；这里是奖励，罚的方向正好相反。"}, {"text": "他借了我的钱还没还，我要他罚还给我。", "explanation": "这里应该用〈偿还〉。罚指处分，不指归还欠款；还钱要说偿还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没交作业，老师罚他了抄三遍。", "corrected_sentence": "他没交作业，老师罚了他抄三遍。", "error_description": "错误：“罚他了抄三遍”；正确：“罚了他抄三遍”。“了”应紧跟动词“罚”，不能放在宾语“他”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把玩具弄坏了，妈妈罚他过一次。", "corrected_sentence": "他把玩具弄坏了，妈妈罚过他一次。", "error_description": "错误：“罚他过一次”；正确：“罚过他一次”。“过”是动词的体标，应紧跟动词“罚”，不能放在宾语“他”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守信", "is_correct": true, "explanation": "反义：守信指遵守信用，与不讲信用、转而替对手做事正相反。"}, {"text": "购买", "is_correct": false, "explanation": "无关：购买指付钱取得物品，与背叛没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：参加指加入某项活动，与背叛不构成反义。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：陪伴指伴随在旁，与背叛不构成反义。"}], "correct_answer": "守信", "explanations": {"守信": "反义：守信指遵守信用，与不讲信用、转而替对手做事正相反。", "购买": "无关：购买指付钱取得物品，与背叛没有反义关系。", "参加": "无关：参加指加入某项活动，与背叛不构成反义。", "陪伴": "无关：陪伴指伴随在旁，与背叛不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守信", "is_correct": true, "explanation": "反义：守信指遵守信用，与背叛对方、不讲信用正相反。"}, {"text": "推荐", "is_correct": false, "explanation": "无关：推荐指介绍人或物，与背叛没有反义关系。"}, {"text": "邀请", "is_correct": false, "explanation": "无关：邀请指请人来做客，不是背叛的反义。"}, {"text": "参观", "is_correct": false, "explanation": "无关：参观指到某处察看，与背叛无关。"}], "correct_answer": "守信", "explanations": {"守信": "反义：守信指遵守信用，与背叛对方、不讲信用正相反。", "推荐": "无关：推荐指介绍人或物，与背叛没有反义关系。", "邀请": "无关：邀请指请人来做客，不是背叛的反义。", "参观": "无关：参观指到某处察看，与背叛无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "背叛是不守信用，转过头帮对手做事。", "primary_collocate": null, "pronunciation": "bèi pàn", "ipa": "pei˥˩ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他背叛了朋友，去帮我们的对手做事。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司老板发现员工背叛了他，把秘密卖给了对手。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说好一起做生意，他却背叛了我。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王背叛了球队，加入了对手的队伍。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你答应过我，怎么能背叛我呢？", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最好的朋友背叛了她，她很难过。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他背叛了合作伙伴，和对手签了合同。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没想到他会背叛我们，帮对手做事。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的师傅背叛了老板，去了对面的店。", "target_word": "背叛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要讲信用，不能背叛对方。", "target_word": "背叛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "背叛了", "label": "完成体"}, {"form": "背叛过", "label": "经历体"}, {"form": "背叛者", "label": "复合"}], "register": "中性", "sense_fingerprint": "不讲信用，反过来替对手做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：保护指照护、护卫，与“去帮我们的对手做事”矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指不守信用、转而替对手做事，与后半句一致。"}, {"text": "照料", "is_correct": false, "explanation": "语义：照料指照顾，与“去帮我们的对手做事”矛盾。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：背诵的对象是课文、诗词，不说“背诵朋友”。"}], "explanations": {"保护": "语义：保护指照护、护卫，与“去帮我们的对手做事”矛盾。", "背叛": "正确：背叛指不守信用、转而替对手做事，与后半句一致。", "照料": "语义：照料指照顾，与“去帮我们的对手做事”矛盾。", "背诵": "搭配：背诵的对象是课文、诗词，不说“背诵朋友”。"}, "sentence_index": 0, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他背叛了比赛，中途回家了。", "explanation": "这里应该用〈放弃〉。放弃用于比赛、计划，背叛的对象是人或誓言。"}, {"text": "他背叛了这本书的内容，删掉了一半。", "explanation": "这里应该用〈删改〉。删改用于文字、内容，背叛的对象是人、誓言或信念。"}, {"text": "这位选手背叛了比赛规则，被取消了资格。", "explanation": "这里应该用〈违反〉。违反用于规则、纪律，背叛不说背叛规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持", "is_correct": false, "explanation": "语义：支持指站在一方、帮助一方，与“和对手签了合同”的转向相矛盾。"}, {"text": "背叛", "is_correct": true, "explanation": "正确：背叛指不守信用、转向对手，与“和对手签了合同”一致。"}, {"text": "签署", "is_correct": false, "explanation": "搭配：签署的对象是合同、协议，不说“签署合作伙伴”。"}, {"text": "维护", "is_correct": false, "explanation": "语义：维护指保护、护卫，与“和对手签了合同”的背弃矛盾。"}], "explanations": {"支持": "语义：支持指站在一方、帮助一方，与“和对手签了合同”的转向相矛盾。", "背叛": "正确：背叛指不守信用、转向对手，与“和对手签了合同”一致。", "签署": "搭配：签署的对象是合同、协议，不说“签署合作伙伴”。", "维护": "语义：维护指保护、护卫，与“和对手签了合同”的背弃矛盾。"}, "sentence_index": 6, "correct_answer": "背叛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了钱，背叛了公司的电脑。", "explanation": "这里应该用〈卖掉〉。背叛的对象是人、誓言或信念，电脑要说卖掉。"}, {"text": "他酒后闹事，背叛了球队的名声。", "explanation": "这里应该用〈损害〉。背叛的对象是人、誓言或信念，名声要说损害、毁坏，不说背叛。"}, {"text": "他背叛了这个谣言。", "explanation": "这里应该用〈驳斥〉。驳斥用于谣言、说法，背叛的对象是人或誓言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他背叛给了公司，跑去给对手工作了。", "corrected_sentence": "他背叛了公司，跑去给对手工作了。", "error_description": "“给”用错了：背叛是及物动词，直接带宾语，不说“背叛给”，应说“背叛了公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很背叛了我们，把客户都带走了。", "corrected_sentence": "他背叛了我们，把客户都带走了。", "error_description": "“很”不能修饰动词：应说“他背叛了我们”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
