INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93687, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "表示数目很多的概数，常用于“几百”“上百”“好几百”，不指确切的一百。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "广场上有几百个人，非常热闹。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有上百家饭馆。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来了好几百个客人，我们忙坏了。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过几百本书，知道得很多。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有四五百只鸟在天上飞。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂有上百个工人，每天都很忙。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要写的字有几百个，今天写不完。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的车有好几百辆，一点儿也走不动。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有上百本书，房间里放不下了。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛来了几百个学生，真多啊。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "几百", "label": "复合"}, {"form": "上百", "label": "复合"}, {"form": "好几百", "label": "复合"}], "register": "中性", "sense_fingerprint": "百：几百、上百，表示数目很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93687, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。“几百”中的百（bǎi）表示数目很多。"}, {"text": "白", "is_correct": false, "explanation": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。"}, {"text": "拜", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。"}], "explanations": {"百": "正确答案。“几百”中的百（bǎi）表示数目很多。", "白": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。", "拜": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。", "宝": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。“几百”表示几百个，与“广场上很热闹”相符。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”是容量单位，不能用来计数人。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来计数人。"}, {"text": "米", "is_correct": false, "explanation": "搭配：“米”是长度单位，不能用来计数人。"}], "explanations": {"百": "正确答案。“几百”表示几百个，与“广场上很热闹”相符。", "升": "搭配：“升”是容量单位，不能用来计数人。", "斤": "搭配：“斤”是重量单位，不能用来计数人。", "米": "搭配：“米”是长度单位，不能用来计数人。"}, "sentence_index": 0, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有一百个学生，每人都来了。", "explanation": "这里的“一百”是确切的数目，与“几百”表示很多的意思不同。"}, {"text": "这件事我百分之百有把握。", "explanation": "这里的“百”用于“百分之百”，表示完全，不表示数量很多。"}, {"text": "他读过一套百科全书，知道得很多。", "explanation": "这里的“百”用于“百科”，指各个方面，不表示“很多很多的数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93687, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。“几百”中的百（bǎi）表示数目很多。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, {"text": "败", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}], "explanations": {"百": "正确答案。“几百”中的百（bǎi）表示数目很多。", "板": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。", "败": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。“几百”表示数量多，与“写不完”相符。"}, {"text": "吨", "is_correct": false, "explanation": "搭配：“吨”是重量单位，不能用来计数字。"}, {"text": "亩", "is_correct": false, "explanation": "搭配：“亩”是土地面积单位，不能用来计数字。"}, {"text": "斗", "is_correct": false, "explanation": "搭配：“斗”是容量单位，不能用来计数字。"}], "explanations": {"百": "正确答案。“几百”表示数量多，与“写不完”相符。", "吨": "搭配：“吨”是重量单位，不能用来计数字。", "亩": "搭配：“亩”是土地面积单位，不能用来计数字。", "斗": "搭配：“斗”是容量单位，不能用来计数字。"}, "sentence_index": 6, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛有一百多名学生参加。", "explanation": "这里的“一百多”是确切的数目，与“几百”表示很多的意思不同。"}, {"text": "我们队百战百胜，从没输过。", "explanation": "这里的“百”是“百战百胜”的“每次”的意思，不表示“很多很多的数”。"}, {"text": "这次比赛有一百零二人参加。", "explanation": "这里的“一百零二”是确切的数目，与“几百”表示很多的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDE