INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "数目，十个十。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "十个十是一百，我们先学会这个数。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从一数到一百，用了两分钟。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一张一百块的钱。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明考试得了一百分，妈妈很高兴。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九十九再加一，就是一百。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路长一百米，我走了两分钟。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百减去五十，还剩五十。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有三百六十五天，不是一百天。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校三百米，走路很近。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了三本书，一共花了一百块。", "target_word": "百", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一百", "label": "复合"}, {"form": "百分之百", "label": "复合"}], "register": "中性", "sense_fingerprint": "百：确切的数目一百，十个十", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。百（bǎi）表示一百。"}, {"text": "白", "is_correct": false, "explanation": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。"}, {"text": "拜", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。"}], "explanations": {"百": "正确答案。百（bǎi）表示一百。", "白": "bái（第二声）与 bǎi（第三声）声调不同，意思是白色。", "拜": "bài（第四声）与 bǎi（第三声）声调不同，意思是拜访。", "板": "bǎn 与 bǎi 韵母不同（-n 与 -i），意思是木板。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。十个十就是一百。"}, {"text": "十", "is_correct": false, "explanation": "语义：十个十是一百，不是一十。"}, {"text": "千", "is_correct": false, "explanation": "语义：十个十是一百，不是一千。"}, {"text": "拾", "is_correct": false, "explanation": "语域：“拾”是票据上用的大写数字，口语中不用于此；而且十个十也不等于一拾。"}], "explanations": {"百": "正确答案。十个十就是一百。", "十": "语义：十个十是一百，不是一十。", "千": "语义：十个十是一百，不是一千。", "拾": "语域：“拾”是票据上用的大写数字，口语中不用于此；而且十个十也不等于一拾。"}, "sentence_index": 0, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家百货商店的东西很多，大家都爱来。", "explanation": "这里的“百”是“百货”的语素，指各种商品，不表示数目一百。"}, {"text": "这次会议来了上百个代表，很热闹。", "explanation": "这里的“上百”是概数，表示很多，与本词确切的数目“一百”不同。"}, {"text": "这次会议来了数百个代表，很热闹。", "explanation": "这里的“数百”是概数，表示几百，与本词确切的数目“一百”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。百（bǎi）表示一百。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, {"text": "败", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}], "explanations": {"百": "正确答案。百（bǎi）表示一百。", "宝": "bǎo 与 bǎi 韵母不同（-o 与 -i），意思是宝贝。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。", "败": "bài（第四声）与 bǎi（第三声）声调不同，意思是失败。"}, "sentence_index": null, "correct_answer": "百"}, "level_3": {"options": [{"text": "百", "is_correct": true, "explanation": "正确答案。一百减五十等于五十。"}, {"text": "万", "is_correct": false, "explanation": "语义：一万减去五十不等于五十，数目不对。"}, {"text": "亿", "is_correct": false, "explanation": "语义：一亿减去五十仍然很大，不能还剩五十。"}, {"text": "仟", "is_correct": false, "explanation": "语域：“仟”是票据用的大写数字，口语不用；而且“一仟”指一千，减五十不剩五十。"}], "explanations": {"百": "正确答案。一百减五十等于五十。", "万": "语义：一万减去五十不等于五十，数目不对。", "亿": "语义：一亿减去五十仍然很大，不能还剩五十。", "仟": "语域：“仟”是票据用的大写数字，口语不用；而且“一仟”指一千，减五十不剩五十。"}, "sentence_index": 6, "correct_answer": "百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了三本书，一共花了几百块。", "explanation": "这里的“几百”是概数，表示几个百，与本词确切的“一百”不同。"}, {"text": "他买了三本书，一共花了好几百块。", "explanation": "这里的“好几百”是概数，表示较多，与本词确切的“一百”不同。"}, {"text": "他买了三本书，一共只花了原价的百分之六十。", "explanation": "这里的“百分之”表示比例，“百”不表示数目一百。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班有一百一个学生，都很认真。", "corrected_sentence": "这个班有一百零一个学生，都很认真。", "error_description": "数词错误：“一百零一”中的“零”不能省，说“一百一个”会被理解为错误的数目，应说“一百零一个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二班有一个百人参加了比赛。", "corrected_sentence": "二班有一百个人参加了比赛。", "error_description": "数词语序错误：“一百个”不能说成“一个百”，应说“一百个人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跟团游", "is_correct": true, "explanation": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。"}, {"text": "导游", "is_correct": false, "explanation": "导游是带团讲解的人，不是旅游方式，与“自由行”不构成反义。"}, {"text": "游客", "is_correct": false, "explanation": "游客指旅行的人，与“自由行”这种旅行方式不构成反义。"}, {"text": "机票", "is_correct": false, "explanation": "机票是乘机凭证，与“自由行”不构成反义。"}], "correct_answer": "跟团游", "explanations": {"跟团游": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。", "导游": "导游是带团讲解的人，不是旅游方式，与“自由行”不构成反义。", "游客": "游客指旅行的人，与“自由行”这种旅行方式不构成反义。", "机票": "机票是乘机凭证，与“自由行”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跟团游", "is_correct": true, "explanation": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。"}, {"text": "旅行社", "is_correct": false, "explanation": "旅行社是提供旅游服务的机构，不是旅游方式，与“自由行”不构成反义。"}, {"text": "地图", "is_correct": false, "explanation": "地图是出行时使用的工具，与“自由行”不构成反义。"}, {"text": "酒店", "is_correct": false, "explanation": "酒店是住宿场所，与“自由行”不构成反义。"}], "correct_answer": "跟团游", "explanations": {"跟团游": "反义：“跟团游”由旅行社统一安排行程，与“自由行”自己安排行程相反。", "旅行社": "旅行社是提供旅游服务的机构，不是旅游方式，与“自由行”不构成反义。", "地图": "地图是出行时使用的工具，与“自由行”不构成反义。", "酒店": "酒店是住宿场所，与“自由行”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不随团、由游客自行安排行程的旅游方式。", "primary_collocate": null, "pronunciation": "zì yóu xíng", "ipa": "tsɨ˥˩ joʊ˧˥ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "今年我不想跟团，想去日本自由行。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行的好处是可以自己决定每天去哪里。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次去泰国是自由行，不是跟团。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行没有导游，所以要自己看地图。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢自由行，因为不用跟着团队赶路。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加自由行的游客要自己订酒店和机票。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起跟团，爸爸更喜欢自由行。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由行的行程由游客自己安排，时间很灵活。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一家人去台湾自由行，玩了七天。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次自由行时，我在车站迷了路。", "target_word": "自由行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "自由行游客", "label": "复合"}], "register": "中性", "sense_fingerprint": "旅游方式：不跟团，游客自己安排行程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自由行", "is_correct": true, "explanation": "正确：“自由行”指自己安排行程的旅行，与前句“不想跟团”形成对照。"}, {"text": "跟团游", "is_correct": false, "explanation": "语义：“跟团游”就是跟着旅行团走，与前句“不想跟团”直接矛盾。"}, {"text": "团购", "is_correct": false, "explanation": "语义：“团购”指多人一起买东西，去日本不能说团购。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“去”后接地点或活动，“游客”指人，不能作“去日本”的宾语。"}], "explanations": {"自由行": "正确：“自由行”指自己安排行程的旅行，与前句“不想跟团”形成对照。", "跟团游": "语义：“跟团游”就是跟着旅行团走，与前句“不想跟团”直接矛盾。", "团购": "语义：“团购”指多人一起买东西，去日本不能说团购。", "游客": "搭配：“去”后接地点或活动，“游客”指人，不能作“去日本”的宾语。"}, "sentence_index": 0, "correct_answer": "自由行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们这次去泰国是一只自由行，玩了三个城市。", "explanation": "这里量词用错了。“只”用于动物，不能修饰“自由行”；说“自由行”应该用量词“次”，如“一次自由行”。"}, {"text": "妈妈想报名参加一座自由行，去看看那边的山。", "explanation": "这里量词用错了。“座”用于山、房屋等大型固定物，不能修饰“自由行”，应说“一次自由行”。"}, {"text": "机器人能在房间里自由行，不用人遥控。", "explanation": "这里“自由行”是“自由地行走、移动”的意思，指机器人在房间内移动，不是旅游方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自由行", "is_correct": true, "explanation": "正确：“自由行”与“比起跟团”形成对比，表示爸爸更喜欢自己安排的旅行。"}, {"text": "旅行团", "is_correct": false, "explanation": "语义：“旅行团”就是跟团，与前句“比起跟团”矛盾。"}, {"text": "跟团游", "is_correct": false, "explanation": "语义：“跟团游”就是跟团，与“比起跟团”的比较对象重复，句意矛盾。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是工具，与“跟团”的比较无关，不能说比起跟团更喜欢地图。"}], "explanations": {"自由行": "正确：“自由行”与“比起跟团”形成对比，表示爸爸更喜欢自己安排的旅行。", "旅行团": "语义：“旅行团”就是跟团，与前句“比起跟团”矛盾。", "跟团游": "语义：“跟团游”就是跟团，与“比起跟团”的比较对象重复，句意矛盾。", "地图": "语义：“地图”是工具，与“跟团”的比较无关，不能说比起跟团更喜欢地图。"}, "sentence_index": 6, "correct_answer": "自由行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这次去台湾是一把自由行，玩了七天。", "explanation": "这里量词用错了。“把”用于有柄的器具，不能修饰“自由行”；应说“一次自由行”。"}, {"text": "我们这次去云南是一本自由行，买了很多东西。", "explanation": "这里量词用错了。“本”用于书籍，不能修饰“自由行”；应说“一次自由行”。"}, {"text": "小宝宝刚学会走路，在屋子里自由行了几步。", "explanation": "这里“自由行”是“自由行走”的意思，指小孩在屋里走动，不是旅游方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年去了一只自由行。", "corrected_sentence": "我们去年去了一次自由行。", "error_description": "量词错误：“自由行”应使用量词“次”（一次自由行）；“只”用于动物，不能用于旅行方式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年去了过自由行，很开心。", "corrected_sentence": "我们去年去过自由行，很开心。", "error_description": "体标错误：“了”和“过”不能同时用在动词后，“去了过”应改为“去过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
