INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记者会是很多记者来提问，有人回答的会。", "primary_collocate": null, "pronunciation": "jì zhě huì", "ipa": "tɕi˥˩ ʈʂɤ˨˩˦ xuei˥˩", "syllable_count": 3, "sentences": [{"text": "今天有记者会，很多人来提问。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会上，记者一个一个提问。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星开了记者会，说了自己的想法。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看那个记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们参加了一场记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察开记者会，告诉大家发生了什么。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会开了一个小时。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在记者会上很紧张。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场记者会在电视上直播。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会的地点在大楼三层。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "记者招待会", "label": "复合"}, {"form": "記者會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：记者来提问、有人回答的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”指记者来提问、有人回答的会，与“很多人来提问”相符。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：“比赛”是竞技活动，不是提问回答的会，与“很多人来提问”不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有天气”不是常见搭配，且天气不能与“来提问”相连。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”是放映的作品，不是可以提问的会，与语境不符。"}], "explanations": {"记者会": "“记者会”指记者来提问、有人回答的会，与“很多人来提问”相符。", "比赛": "语义：“比赛”是竞技活动，不是提问回答的会，与“很多人来提问”不符。", "天气": "搭配：“有天气”不是常见搭配，且天气不能与“来提问”相连。", "电影": "语义：“电影”是放映的作品，不是可以提问的会，与语境不符。"}, "sentence_index": 0, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者会上，同学们轮流读诗。", "explanation": "这里应该用〈朗诵会〉。记者会是记者提问、有人回答的会，不是同学们轮流朗读作品。"}, {"text": "记者会上，买家们竞相举牌。", "explanation": "这里应该用〈拍卖会〉。记者会没有竞价举牌的环节，买家竞价要说拍卖会。"}, {"text": "记者会上，同学们认真答题。", "explanation": "这里应该用〈考试〉。记者会是记者提问、有人回答，不是学生答题的场合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”是会议，可以“开”，开了一个小时，句子通顺。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”不能作为会议一样“开”起来，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不会“开”，与“开了一个小时”的语境矛盾。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“开”不与“雨”搭配，不能说“雨开了一个小时”。"}], "explanations": {"记者会": "“记者会”是会议，可以“开”，开了一个小时，句子通顺。", "太阳": "语义：“太阳”不能作为会议一样“开”起来，句子不通。", "月亮": "语义：“月亮”不会“开”，与“开了一个小时”的语境矛盾。", "雨": "搭配：“开”不与“雨”搭配，不能说“雨开了一个小时”。"}, "sentence_index": 6, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者会上，大家排队抽血。", "explanation": "这里应该用〈体检〉。记者会是记者提问、有人回答的会，排队抽血要说体检。"}, {"text": "记者会上，大家在跑步机上跑步。", "explanation": "这里应该用〈健身房〉。记者会不是锻炼身体的场所，在跑步机上跑步要说健身房。"}, {"text": "记者会上，师傅给顾客剪头发。", "explanation": "这里应该用〈理发店〉。记者会不是理发的场合，给顾客剪头发要说理发店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天参加了一位记者会。", "corrected_sentence": "我昨天参加了一场记者会。", "error_description": "错误：量词“位”；正确：“场”。“位”用于人，“记者会”作为活动要用“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场记者会开得两个小时。", "corrected_sentence": "那场记者会开了两个小时。", "error_description": "错误：“开得”；正确：“开了”。表示时间长度的补语前应用“了”表示动作完成，“得”只用于程度补语，不能接时量词语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
