INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构邀请记者发布消息并回答提问的会议。", "primary_collocate": null, "pronunciation": "jì zhě huì", "ipa": "tɕi˥˩ ʈʂɤ˨˩˦ xuei˥˩", "syllable_count": 3, "sentences": [{"text": "明天上午公司要开记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在记者会上回答了问题。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场记者会来了很多记者。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会八点开始，请大家准时到。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队今天下午召开记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看过那场记者会。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会上，经理介绍了新产品。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在记者会上说了对不起。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为什么突然开记者会？", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者会结束后，大家都回家了。", "target_word": "记者会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "记者招待会", "label": "复合"}, {"form": "記者會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：机构邀请记者发布消息并回答提问的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”指机构邀请记者发布消息并回答提问的会议，与“公司要开”搭配，句子通顺。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“开玩笑”是固定短语，“公司要开玩笑”不成立。"}, {"text": "陷阱", "is_correct": false, "explanation": "语义：“陷阱”是设来害人的圈套，与公司安排的会议完全不符。"}, {"text": "笑话", "is_correct": false, "explanation": "语域：“笑话”是口语说法，不适用于正式的公司通知。"}], "explanations": {"记者会": "“记者会”指机构邀请记者发布消息并回答提问的会议，与“公司要开”搭配，句子通顺。", "玩笑": "搭配：“开玩笑”是固定短语，“公司要开玩笑”不成立。", "陷阱": "语义：“陷阱”是设来害人的圈套，与公司安排的会议完全不符。", "笑话": "语域：“笑话”是口语说法，不适用于正式的公司通知。"}, "sentence_index": 0, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们下午在记者会上吃了火锅。", "explanation": "这里应该用〈聚餐〉。记者会是机构邀请记者发布消息、回答提问的场合，吃火锅要说聚餐。"}, {"text": "老师在记者会上给我们讲了课。", "explanation": "这里应该用〈讲座〉。记者会没有授课的功能，讲课要说讲座。"}, {"text": "我们班的记者会，每个家长都要签到。", "explanation": "这里应该用〈家长会〉。记者会是面向记者的，家长到校聚会要说家长会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记者会", "is_correct": true, "explanation": "“记者会”与“上”组成场所，指发布消息的会，与“经理介绍新产品”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是进行产品介绍的场所，句子不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“病房”不适合进行产品介绍，与语境冲突。"}, {"text": "洗手间", "is_correct": false, "explanation": "语域：“洗手间”是日常口语或委婉说法，不适合正式的产品发布语境。"}], "explanations": {"记者会": "“记者会”与“上”组成场所，指发布消息的会，与“经理介绍新产品”的语境相符。", "厨房": "语义：“厨房”不是进行产品介绍的场所，句子不通。", "病房": "语义：“病房”不适合进行产品介绍，与语境冲突。", "洗手间": "语域：“洗手间”是日常口语或委婉说法，不适合正式的产品发布语境。"}, "sentence_index": 6, "correct_answer": "记者会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者会上，新人交换了戒指。", "explanation": "这里应该用〈婚礼〉。记者会是机构邀请记者发布消息、回答提问的场合，新人交换戒指要说婚礼。"}, {"text": "记者会上，同学们跑了一百米。", "explanation": "这里应该用〈运动会〉。记者会是发布消息、回答提问的场合，比赛跑步要说运动会。"}, {"text": "记者会上，孩子们吹灭了蜡烛。", "explanation": "这里应该用〈生日派对〉。记者会不是庆祝生日的场合，吹灭蜡烛要说生日派对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府明天开一本记者会。", "corrected_sentence": "市政府明天开一场记者会。", "error_description": "错误：量词“本”；正确：“场”。“记者会”作为活动，量词要用“场”，“本”只用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "发言人记者会上宣布了消息。", "corrected_sentence": "发言人在记者会上宣布了消息。", "error_description": "错误：漏掉介词“在”，“记者会上”前面缺少“在”；正确：“在记者会上”。表示场所要用“在……上”结构，省略“在”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与评选同属评议过程，不构成反义。"}, {"text": "公布", "is_correct": false, "explanation": "公布是宣布结果，与评选相关但不构成反义。"}, {"text": "参赛", "is_correct": false, "explanation": "参赛指参加比赛，与评选不构成反义。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。", "讨论": "讨论与评选同属评议过程，不构成反义。", "公布": "公布是宣布结果，与评选相关但不构成反义。", "参赛": "参赛指参加比赛，与评选不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淘汰", "is_correct": true, "explanation": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。"}, {"text": "报名", "is_correct": false, "explanation": "报名指登记参加，与评选不构成反义。"}, {"text": "投票", "is_correct": false, "explanation": "投票是表达选择的方式之一，与评选不构成反义。"}, {"text": "宣传", "is_correct": false, "explanation": "宣传是推广活动或事物，与评选不构成反义。"}], "correct_answer": "淘汰", "explanations": {"淘汰": "反义：“评选”是选出优秀者，“淘汰”是剔除落后者，二者方向相反。", "报名": "报名指登记参加，与评选不构成反义。", "投票": "投票是表达选择的方式之一，与评选不构成反义。", "宣传": "宣传是推广活动或事物，与评选不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过评议比较，选出优秀者。", "primary_collocate": null, "pronunciation": "píng xuǎn", "ipa": "pʰiŋ˧˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校每年都评选最佳教师。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛由专家评选，大家都很服气。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在评选今年的优秀员工。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选结果明天公布。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们评选出了三篇好作文。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家评选他当学习代表。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选要公平，不能只看名气。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社评选了今年的十大新闻。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起评选最好看的照片。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评选活动从上个月开始，有很多人参加。", "target_word": "评选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评选了", "label": "体标"}, {"form": "评选过", "label": "体标"}, {"form": "评选活动", "label": "复合"}, {"form": "評選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经过评议比较后选出优秀的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评选", "is_correct": true, "explanation": "正确：“评选”指经过评议比较选出优秀者，与“最佳教师”搭配自然。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，学校不能种植教师。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说翻译教师。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮教师。"}], "explanations": {"评选": "正确：“评选”指经过评议比较选出优秀者，与“最佳教师”搭配自然。", "种植": "语义：“种植”指栽培植物，学校不能种植教师。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说翻译教师。", "煮": "搭配：“煮”的对象是食物，不能说煮教师。"}, "sentence_index": 0, "correct_answer": "评选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从一堆水果里评选出最甜的一个。", "explanation": "这里应该用〈挑选〉。“评选”指经过评议比较选出优秀的人或事物，个人挑水果要用〈挑选〉。"}, {"text": "妈妈去市场评选了一条鱼。", "explanation": "这里应该用〈选购〉。“评选”用于经过评议选出优秀者，买东西要用〈选购〉。"}, {"text": "他评选了学医，以后想当医生。", "explanation": "这里应该用〈选择〉。“评选”需要经过评议比较，个人决定做什么要用〈选择〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评选", "is_correct": true, "explanation": "正确：“评选”指经过评议比较选出，与“要公平、不能只看名气”的评价语境相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与“看名气”的评价标准无关，不存在公平与否的评议。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清洁动作，不能说“打扫要公平”。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：“放牧”指照看牲畜，与“看名气”的判断无关。"}], "explanations": {"评选": "正确：“评选”指经过评议比较选出，与“要公平、不能只看名气”的评价语境相符。", "烹饪": "语义：“烹饪”指做菜，与“看名气”的评价标准无关，不存在公平与否的评议。", "打扫": "搭配：“打扫”是清洁动作，不能说“打扫要公平”。", "放牧": "语义：“放牧”指照看牲畜，与“看名气”的判断无关。"}, "sentence_index": 6, "correct_answer": "评选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在抽屉里评选出了一把能开门的钥匙。", "explanation": "这里应该用〈找到〉。“评选”指经过评议比较选出优秀者，在抽屉里找钥匙要用〈找到〉。"}, {"text": "工厂用机器评选出了有问题的零件。", "explanation": "这里应该用〈筛选〉。“评选”指选出优秀者，把有问题的零件挑出来要用〈筛选〉。"}, {"text": "我在沙滩上评选贝壳，挑了好几个。", "explanation": "这里应该用〈挑拣〉。“评选”指经过评议比较选出优秀者，在沙滩上挑贝壳要用〈挑拣〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校评选了出三个优秀学生。", "corrected_sentence": "学校评选出了三个优秀学生。", "error_description": "补语位置错误：结果补语“出”应紧跟动词，应说“评选出”，不能说“评选了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前评选了过最佳员工。", "corrected_sentence": "我们以前评选过最佳员工。", "error_description": "体标错误：“评选过”表示曾经评选过，“了”和“过”不能同时出现在动词后，应说“评选过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反驳", "is_correct": true, "explanation": "反义：反驳指用理由驳倒对方的论断，与论证自己的观点相对。"}, {"text": "购买", "is_correct": false, "explanation": "无关：购买指付钱取得物品，与论证没有反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "无关：保护指照护、护卫，与论证不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "无关：参加指加入某项活动，与论证无关。"}], "correct_answer": "反驳", "explanations": {"反驳": "反义：反驳指用理由驳倒对方的论断，与论证自己的观点相对。", "购买": "无关：购买指付钱取得物品，与论证没有反义关系。", "保护": "无关：保护指照护、护卫，与论证不构成反义。", "参加": "无关：参加指加入某项活动，与论证无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反驳", "is_correct": true, "explanation": "反义：反驳指用理由驳倒对方的论断，与论证相对。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：陪伴指伴随在旁，与论证无关。"}, {"text": "参观", "is_correct": false, "explanation": "无关：参观指到某处察看，与论证无关。"}, {"text": "邀请", "is_correct": false, "explanation": "无关：邀请指请人来做客，与论证无关。"}], "correct_answer": "反驳", "explanations": {"反驳": "反义：反驳指用理由驳倒对方的论断，与论证相对。", "陪伴": "无关：陪伴指伴随在旁，与论证无关。", "参观": "无关：参观指到某处察看，与论证无关。", "邀请": "无关：邀请指请人来做客，与论证无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "论证是用道理和证据，说明一件事是对的。", "primary_collocate": null, "pronunciation": "lùn zhèng", "ipa": "lwən˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他用很多数据论证自己的想法是对的。", "target_word": "论证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们论证这个办法可行。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家用实验论证了新理论。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要用事实来论证你的看法。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一步一步论证，大家都听懂了。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她论证了这个计划为什么能成功。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师用证据论证他的朋友没有说谎。", "target_word": "论证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请论证一下这样做的正当性。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试图论证这项政策的合理性。", "target_word": "论证", "complexity_tier": "T3", "furigana": "tā shìtú lùnzhèng zhè xiàng zhèngcè de hélǐxìng。", "sentence_source": "generated"}, {"text": "他先说道理，再用例子论证。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "论证了", "label": "完成体"}, {"form": "论证过", "label": "经历体"}, {"form": "论证一下", "label": "短时"}], "register": "书面", "sense_fingerprint": "用道理和证据说明某事正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质疑", "is_correct": false, "explanation": "语义：质疑指提出疑问，与“想法是对的”的肯定结论矛盾。"}, {"text": "否定", "is_correct": false, "explanation": "语义：否定指认为不对，与“想法是对的”矛盾。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指用道理和证据说明某事正确，与“想法是对的”一致。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“用很多数据”限定的动作是论证或说明，不说“用数据赞美”。"}], "explanations": {"质疑": "语义：质疑指提出疑问，与“想法是对的”的肯定结论矛盾。", "否定": "语义：否定指认为不对，与“想法是对的”矛盾。", "论证": "正确：论证指用道理和证据说明某事正确，与“想法是对的”一致。", "赞美": "搭配：“用很多数据”限定的动作是论证或说明，不说“用数据赞美”。"}, "sentence_index": 0, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他论证了那辆汽车。", "explanation": "这里应该用〈检查〉。论证的对象是论点、观点，具体的汽车要用检查，不说论证。"}, {"text": "他在门口论证了很久。", "explanation": "这里应该用〈等待〉。论证是用道理和证据证明观点，站着等人不是论证，要说等待。"}, {"text": "他用歌声论证了自己的感情。", "explanation": "这里应该用〈表达〉。论证用于观点、论点，感情要用表达，不说论证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揭露", "is_correct": false, "explanation": "语义：揭露指暴露隐藏的事实，与“他的朋友没有说谎”的结论矛盾。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：怀疑指不相信，与“他的朋友没有说谎”的结论矛盾。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指用证据说明某事正确，与“没有说谎”一致。"}, {"text": "夸奖", "is_correct": false, "explanation": "搭配：夸奖的对象是人或行为，“没有说谎”是事实判断，不说“夸奖没有说谎”。"}], "explanations": {"揭露": "语义：揭露指暴露隐藏的事实，与“他的朋友没有说谎”的结论矛盾。", "怀疑": "语义：怀疑指不相信，与“他的朋友没有说谎”的结论矛盾。", "论证": "正确：论证指用证据说明某事正确，与“没有说谎”一致。", "夸奖": "搭配：夸奖的对象是人或行为，“没有说谎”是事实判断，不说“夸奖没有说谎”。"}, "sentence_index": 6, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用道理论证了大家。", "explanation": "这里应该用〈说服〉。论证的对象是论点，不能直接用于人。"}, {"text": "这位学生论证了自己的经历。", "explanation": "这里应该用〈讲述〉。论证是说明道理的论述，讲述经历要用讲述。"}, {"text": "警察论证了那扇门的颜色。", "explanation": "这里应该用〈辨认〉。论证是用道理证明观点，颜色要用辨认。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她被认真论证了自己的观点。", "corrected_sentence": "她认真论证了自己的观点。", "error_description": "“被”用错了：这里“她”是论证的人，不能用“被”，应说“她认真论证了自己的观点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要很论证这个方法是否可行。", "corrected_sentence": "我们要论证这个方法是否可行。", "error_description": "“很”不能修饰动词：论证是动词，应说“我们要论证这个方法是否可行”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
