INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用论据证明论点的过程；论述并证明。", "primary_collocate": null, "pronunciation": "lùn zhèng", "ipa": "lwən˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这篇文章的论证很清楚。", "target_word": "论证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的论证里有很多好例子。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的论证还不够充分。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个论证过程很长，但是很有道理。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的论证需要真实的证据。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认真地看完了整个论证。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次论证让大家相信了他的看法。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文的论证部分写得最好。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的论证简单，但是有力。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了他的论证，我们都同意了。", "target_word": "论证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "论证过程", "label": "复合"}, {"form": "论证方法", "label": "复合"}], "register": "书面", "sense_fingerprint": "以论据证明论点的论述过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：文章是书面材料，没有声音，不能说“声音很清楚”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性情，形容人，不用来说文章。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌形容人或物的样子，不用来说文章的说理是否清楚。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指论述证明的过程，“论证很清楚”指说理清晰。"}], "explanations": {"声音": "语义：文章是书面材料，没有声音，不能说“声音很清楚”。", "脾气": "语义：脾气指性情，形容人，不用来说文章。", "外貌": "体貌：外貌形容人或物的样子，不用来说文章的说理是否清楚。", "论证": "正确：论证指论述证明的过程，“论证很清楚”指说理清晰。"}, "sentence_index": 0, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章里有一只论证，很有道理。", "explanation": "这里应该用〈个〉。论证是抽象的论述，应说“一个论证”；“只”多用于动物。"}, {"text": "我们从实验中得出了一个论证。", "explanation": "这里应该用〈结论〉。得出的是结论，论证指论述证明的过程。"}, {"text": "他的论证长得很好看，大家都喜欢。", "explanation": "这里应该用〈严密〉。长得描述人或物的外形，论证的好坏应说严密、清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能说服人，“这次天气让大家相信”与语境不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材形容人的体形，不用来说明内容能否让人信服。"}, {"text": "论证", "is_correct": true, "explanation": "正确：论证指用道理和证据说服他人，与“让大家相信了他的看法”一致。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人的重量，与“让大家相信”无关。"}], "explanations": {"天气": "语义：天气不能说服人，“这次天气让大家相信”与语境不符。", "身材": "体貌：身材形容人的体形，不用来说明内容能否让人信服。", "论证": "正确：论证指用道理和证据说服他人，与“让大家相信了他的看法”一致。", "体重": "语义：体重指人的重量，与“让大家相信”无关。"}, "sentence_index": 6, "correct_answer": "论证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的论证是三，你算对了吗？", "explanation": "这里应该用〈答案〉。论证是论述过程，不是数字结果。"}, {"text": "他的论证打破了全校的纪录。", "explanation": "这里应该用〈成绩〉。打破用于纪录，论证是论述，不能被打破。"}, {"text": "他拿出了论证，证明自己是这里的学生。", "explanation": "这里应该用〈证件〉。论证是论述的过程，不能用来当证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了一只新的论证。", "corrected_sentence": "他提出了一个新的论证。", "error_description": "量词用错了：论证是抽象的论述，应用“个”，“只”多用于动物，应说“一个新的论证”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个论证地过程很有道理。", "corrected_sentence": "这个论证的过程很有道理。", "error_description": "“地”用错了：名词前的修饰语用“的”，应说“这个论证的过程很有道理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
