INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防是对人或事保持警惕，小心提防，不让其得逞。", "primary_collocate": null, "pronunciation": "fáng", "ipa": "fɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他爱说谎，你要防着点儿。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门在外，要防着小偷。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人不太可靠，我一直防着他。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没防过他，没想到他骗了我。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的招数太多，我防不住。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借钱不还，大家都防着他。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是防着邻居，不让他们进家门。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，我们得防着点儿路边的陌生人。", "target_word": "防", "complexity_tier": "T3", "furigana": "Tiān hēi yǐhòu, wǒmen děi fángzhe diǎnr lù biān de mò shēng rén.", "sentence_source": "generated"}, {"text": "老板很精明，跟他打交道要防着点儿。", "target_word": "防", "complexity_tier": "T3", "furigana": "Lǎobǎn hěn jīngmíng, gēn tā dǎ jiāo dao yào fángzhe diǎnr.", "sentence_source": "generated"}, {"text": "我早就防着他了，所以没上当。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防着", "label": "体标"}, {"form": "防过", "label": "体标"}, {"form": "防了", "label": "体标"}], "register": "中性", "sense_fingerprint": "对人或事保持警惕，小心提防", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：对人或事保持警惕，小心提防。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置、放下。"}, {"text": "方", "is_correct": false, "explanation": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。"}, {"text": "旁", "is_correct": false, "explanation": "páng 与 fáng 声母不同（p 与 f），意思是旁边。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是米饭。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。"}], "explanations": {"防": "防（fáng）：对人或事保持警惕，小心提防。", "放": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置、放下。", "方": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。", "旁": "páng 与 fáng 声母不同（p 与 f），意思是旁边。", "饭": "fàn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是米饭。", "访": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防着点儿”表示对说谎的人保持戒备，符合句意。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与“他爱说谎”的语境相反，不能用于提醒对方戒备。"}, {"text": "赞", "is_correct": false, "explanation": "语义：“赞”表示赞扬，“你要赞着点儿”与提醒对方小心的语境不符。"}, {"text": "喊", "is_correct": false, "explanation": "搭配：“喊”不与“着点儿”组成表示戒备的说法，“你要喊着点儿”不成词组。"}], "explanations": {"防": "正确：“防着点儿”表示对说谎的人保持戒备，符合句意。", "夸": "语义：“夸”是称赞，与“他爱说谎”的语境相反，不能用于提醒对方戒备。", "赞": "语义：“赞”表示赞扬，“你要赞着点儿”与提醒对方小心的语境不符。", "喊": "搭配：“喊”不与“着点儿”组成表示戒备的说法，“你要喊着点儿”不成词组。"}, "sentence_index": 0, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人正在防那台机器。", "explanation": "这里应该用〈修理〉。防表示提防人或事，不能用于物品。"}, {"text": "我们的后卫防得很稳，对方没能突破。", "explanation": "这里的“防”是“防守”，指阻挡对方进攻，与“对人或事保持警惕、小心提防”的意思不同。"}, {"text": "我很防我的老朋友，什么事都跟他说。", "explanation": "这里应该用〈信任〉。防是提防某人，表示戒备，与“什么事都跟他说”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93727, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：对人或事保持警惕，小心提防。"}, {"text": "忙", "is_correct": false, "explanation": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。"}, {"text": "烦", "is_correct": false, "explanation": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。"}, {"text": "反", "is_correct": false, "explanation": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。"}], "explanations": {"防": "防（fáng）：对人或事保持警惕，小心提防。", "忙": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。", "烦": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。", "反": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。", "仿": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。", "翻": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防着邻居”表示提防，与“不让他们进家门”一致。"}, {"text": "迎", "is_correct": false, "explanation": "语义：“迎”是迎接、欢迎，与“不让他们进家门”矛盾。"}, {"text": "请", "is_correct": false, "explanation": "语义：“请”表示邀请，与“不让他们进家门”矛盾。"}, {"text": "招", "is_correct": false, "explanation": "搭配：“招”带“着”多用于招手、招呼，“招着邻居”不成搭配。"}], "explanations": {"防": "正确：“防着邻居”表示提防，与“不让他们进家门”一致。", "迎": "语义：“迎”是迎接、欢迎，与“不让他们进家门”矛盾。", "请": "语义：“请”表示邀请，与“不让他们进家门”矛盾。", "招": "搭配：“招”带“着”多用于招手、招呼，“招着邻居”不成搭配。"}, "sentence_index": 6, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门将防得很稳，对方一脚都没射进。", "explanation": "这里的“防”是“防守”，指阻挡对方射门，与“对人或事保持警惕、小心提防”的意思不同。"}, {"text": "城墙上的士兵防了一整夜，敌人没能攻进城。", "explanation": "这里的“防”是“防守”，指抵挡敌人进攻，与“提防人或事”的意思不同。"}, {"text": "他伸手防住了快要掉下来的杯子。", "explanation": "这里的“防”是“拦住、挡住”，指伸手拦下杯子，与“对人或事保持警惕、小心提防”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出门在外，要防过扒手。", "corrected_sentence": "出门在外，要防着扒手。", "error_description": "错误：“要防过扒手”。正确：“要防着扒手”。表示持续地提防，要用“着”；“过”表示经历，与“要防”的持续提醒不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不防过那个老同学，没想到他借钱不还。", "corrected_sentence": "我从来没防过那个老同学，没想到他借钱不还。", "error_description": "错误：“不防过”。正确：“没防过”。表示过去从未有过这种经历，要用“没”否定，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
