INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先做好准备，不让坏事发生。", "primary_collocate": null, "pronunciation": "fáng", "ipa": "fɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "天气冷了，要提前防感冒。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天蚊子多，晚上得防蚊子。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防雨水灌进屋，村民在门口堆沙袋。", "target_word": "防", "complexity_tier": "T3", "furigana": "Wèile fáng yǔshuǐ guàn jìn wū, cūnmín zài ménkǒu duī shādài.", "sentence_source": "generated"}, {"text": "老人走路慢，要防摔。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前带上伞，防下雨。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手机里存了备份，防丢。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩水，家长在旁边防着出事。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，农民提前防虫。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带了两个充电宝，防手机没电。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风大，出门要戴帽子防冷。", "target_word": "防", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防着", "label": "体标"}, {"form": "防过", "label": "体标"}, {"form": "防了", "label": "体标"}], "register": "中性", "sense_fingerprint": "提前做准备，避免不好的事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：事先做好准备，避免坏事发生。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。"}, {"text": "方", "is_correct": false, "explanation": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。"}, {"text": "忙", "is_correct": false, "explanation": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。"}, {"text": "烦", "is_correct": false, "explanation": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。"}], "explanations": {"防": "防（fáng）：事先做好准备，避免坏事发生。", "访": "fǎng（第三声）与 fáng（第二声）声调不同，意思是拜访。", "方": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向、方形。", "忙": "máng 与 fáng 声母不同（m 与 f），声调相同，意思是忙碌。", "烦": "fán 与 fáng 韵母不同（an 与 ang），声调相同，意思是烦恼。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防感冒”表示提前做好准备，避免生病，符合句意。"}, {"text": "治", "is_correct": false, "explanation": "语义：“治”是治疗已经得了的病，与“提前”矛盾。"}, {"text": "退", "is_correct": false, "explanation": "搭配：“退”常与“烧”搭配（退烧），不能说“退感冒”。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不与“感冒”搭配，“要提前打感冒”不成说法。"}], "explanations": {"防": "正确：“防感冒”表示提前做好准备，避免生病，符合句意。", "治": "语义：“治”是治疗已经得了的病，与“提前”矛盾。", "退": "搭配：“退”常与“烧”搭配（退烧），不能说“退感冒”。", "打": "搭配：“打”不与“感冒”搭配，“要提前打感冒”不成说法。"}, "sentence_index": 0, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "噪音会防学习。", "explanation": "这里应该用〈妨碍〉。防表示事先避免坏事，不能用于阻碍正在进行的学习。"}, {"text": "士兵们防了一夜，城门终于没有被攻破。", "explanation": "这里的“防”是“防守”，指抵挡敌人进攻，与“事先做好准备、避免坏事”的意思不同。"}, {"text": "学校防了很多人才。", "explanation": "这里应该用〈培养〉。防表示事先避免坏事，不能用来说培育人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防", "is_correct": true, "explanation": "防（fáng）：事先做好准备，避免坏事发生。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置。"}, {"text": "旁", "is_correct": false, "explanation": "páng 与 fáng 声母不同（p 与 f），意思是旁边。"}, {"text": "反", "is_correct": false, "explanation": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。"}], "explanations": {"防": "防（fáng）：事先做好准备，避免坏事发生。", "放": "fàng（第四声）与 fáng（第二声）声调不同，意思是放置。", "旁": "páng 与 fáng 声母不同（p 与 f），意思是旁边。", "反": "fǎn 与 fáng 韵母不同（an 与 ang），声调也不同，意思是相反。", "翻": "fān（第一声）与 fáng 韵母与声调都不同，意思是翻动、翻转。", "仿": "fǎng（第三声）与 fáng（第二声）声调不同，意思是模仿。"}, "sentence_index": null, "correct_answer": "防"}, "level_3": {"options": [{"text": "防", "is_correct": true, "explanation": "正确：“防着出事”表示提前戒备、避免事故，符合句意。"}, {"text": "盼", "is_correct": false, "explanation": "语义：“盼”是希望，“盼着出事”与家长的意图相反。"}, {"text": "图", "is_correct": false, "explanation": "语义：“图”是谋求，“图着出事”与家长的意图相反。"}, {"text": "吓", "is_correct": false, "explanation": "配价：“吓”要带受事（吓着某人），不能只接“出事”这一小句。"}], "explanations": {"防": "正确：“防着出事”表示提前戒备、避免事故，符合句意。", "盼": "语义：“盼”是希望，“盼着出事”与家长的意图相反。", "图": "语义：“图”是谋求，“图着出事”与家长的意图相反。", "吓": "配价：“吓”要带受事（吓着某人），不能只接“出事”这一小句。"}, "sentence_index": 6, "correct_answer": "防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他防开了迎面而来的车。", "explanation": "这里应该用〈躲开〉。防表示事先做好准备、避免坏事，不能用于躲避已经迎面而来的车。"}, {"text": "门将防住了对方的射门，球队赢了比赛。", "explanation": "这里的“防”是“防守”，指阻挡对方射门，与“事先做好准备、避免坏事”的意思不同。"}, {"text": "农民防了很多鸡。", "explanation": "这里应该用〈饲养〉。防表示避免坏事，不能用于养殖动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年雨季提前，我们要把水灾防。", "corrected_sentence": "今年雨季提前，我们要把水灾防住。", "error_description": "错误：“把水灾防”。正确：“把水灾防住”。用“把”字句时，动词后面要有补语，单独的“防”不能完整表达意思。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年不防过洪水，结果房子进了水。", "corrected_sentence": "我们去年没防过洪水，结果房子进了水。", "error_description": "错误：“不防过”。正确：“没防过”。表示过去没有过这种经历，要用“没”否定，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
