INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93733, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "惊人是让人看了吓一跳，觉得太厉害了。", "primary_collocate": null, "pronunciation": "jīng rén", "ipa": "tɕiŋ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他有一个惊人的计划。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛里，她跳出了惊人的高度。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人有惊人的力气。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到了一个惊人的数字。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小男孩的画画水平惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片太惊人了，我看了吓了一跳。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的风景美得惊人，我们都看呆了。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的跑步速度惊人，我追不上。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗聪明得惊人，会自己开门。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个城市的夜景漂亮得惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让人看了吓一跳，觉得非常厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惊人", "is_correct": true, "explanation": "惊人：形容计划非同寻常，让人吃惊，符合句中的语境。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容性情或语气，不能修饰“计划”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容声音粗而不清亮，不能修饰“计划”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水多，不能修饰“计划”。"}], "explanations": {"惊人": "惊人：形容计划非同寻常，让人吃惊，符合句中的语境。", "温柔": "搭配：“温柔”形容性情或语气，不能修饰“计划”。", "沙哑": "语义：“沙哑”形容声音粗而不清亮，不能修饰“计划”。", "潮湿": "语义：“潮湿”形容空气或物体含水多，不能修饰“计划”。"}, "sentence_index": 0, "correct_answer": "惊人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们听完之后都很惊人。", "explanation": "这里应该用〈惊奇〉。惊人形容事物令人吃惊的程度，不用来形容人的感受。"}, {"text": "这只是一件惊人的小事。", "explanation": "这里应该用〈平常〉。惊人表示让人吓一跳的厉害程度，只能修饰特别突出的事物；“只是一件小事”是平常的事，要用〈平常〉。"}, {"text": "这件事让所有人很惊人。", "explanation": "这里应该用〈震惊〉。惊人形容事物的程度，“让所有人”指向人的感受，要用〈震惊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惊人", "is_correct": true, "explanation": "惊人：形容风景美到超出一般，令人吃惊，与“我们都看呆了”相符。"}, {"text": "寒酸", "is_correct": false, "explanation": "语义：“寒酸”形容穷困、不体面，与“美”的意思矛盾。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容反应或感觉慢，不能修饰“风景”。"}, {"text": "憔悴", "is_correct": false, "explanation": "体貌：“憔悴”形容人因劳累或病痛而面容消瘦，不能用来形容风景。"}], "explanations": {"惊人": "惊人：形容风景美到超出一般，令人吃惊，与“我们都看呆了”相符。", "寒酸": "语义：“寒酸”形容穷困、不体面，与“美”的意思矛盾。", "迟钝": "搭配：“迟钝”形容反应或感觉慢，不能修饰“风景”。", "憔悴": "体貌：“憔悴”形容人因劳累或病痛而面容消瘦，不能用来形容风景。"}, "sentence_index": 6, "correct_answer": "惊人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我站在山顶，心里很惊人。", "explanation": "这里应该用〈惊叹〉。“心里”是人的感受，要用〈惊叹〉；惊人只用来形容事物。"}, {"text": "这次旅行只是一次惊人的散步。", "explanation": "这里应该用〈普通〉。惊人表示让人吓一跳的厉害程度，只能修饰特别突出的事物；“只是一次散步”是平常的事，要用〈普通〉。"}, {"text": "这个消息让大家都很惊人。", "explanation": "这里应该用〈惊愕〉。惊人形容事物的程度，“让大家”指向人的感受，要用〈惊愕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人的力气惊人的，年轻人都比不上。", "corrected_sentence": "这位老人的力气惊人，年轻人都比不上。", "error_description": "错误：“惊人”作谓语时后面不能加“的”。正确的说法是“力气惊人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的菜做惊人，很多人都来排队。", "corrected_sentence": "这家餐厅的菜做得惊人，很多人都来排队。", "error_description": "错误：“做”后漏掉补语标记“得”。正确的说法是“做得惊人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
