INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93734, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "使人吃惊；超出一般的。", "primary_collocate": null, "pronunciation": "jīng rén", "ipa": "tɕiŋ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这座城市发展的速度很惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆力惊人，看一遍就记住了。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天的气温高得惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城的变化真是惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑步的成绩惊人，比去年快了很多。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的利润增长得惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭的量惊人，一个人吃了五碗饭。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的物价贵得惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机卖得很快，销量惊人。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子学习的进步惊人，大家都夸他。", "target_word": "惊人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度或数量超出一般，让人吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惊人", "is_correct": true, "explanation": "惊人：形容程度超出一般，让人吃惊，符合“发展速度很快”的语境。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”形容人或动物的样子讨人喜欢，不能修饰“速度”。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容性情或动作的柔和，不能修饰“速度”。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指东西过时，与“发展速度很快”的意思相反。"}], "explanations": {"惊人": "惊人：形容程度超出一般，让人吃惊，符合“发展速度很快”的语境。", "可爱": "搭配：“可爱”形容人或动物的样子讨人喜欢，不能修饰“速度”。", "温柔": "搭配：“温柔”形容性情或动作的柔和，不能修饰“速度”。", "陈旧": "语义：“陈旧”指东西过时，与“发展速度很快”的意思相反。"}, "sentence_index": 0, "correct_answer": "惊人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们听到响声，都很惊人。", "explanation": "这里应该用〈惊讶〉。惊人形容事物令人吃惊的程度，不用来形容人的心情。"}, {"text": "妈妈看到成绩单，心里很惊人。", "explanation": "这里应该用〈惊讶〉。惊人形容事物的程度，“心里”是人的感受，要用〈惊讶〉。"}, {"text": "这个消息让我们很惊人。", "explanation": "这里应该用〈吃惊〉。惊人形容事物的程度，“让我们……”说的是人的感受，要用〈吃惊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惊人", "is_correct": true, "explanation": "惊人：形容吃饭的量超出一般，与“一个人吃了五碗饭”相符。"}, {"text": "文静", "is_correct": false, "explanation": "搭配：“文静”形容人的性情举止安静，不能修饰“吃饭的量”。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：“清淡”多指口味或颜色，不能用来形容吃饭的量。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”表示数量很少，与“一个人吃了五碗饭”矛盾。"}], "explanations": {"惊人": "惊人：形容吃饭的量超出一般，与“一个人吃了五碗饭”相符。", "文静": "搭配：“文静”形容人的性情举止安静，不能修饰“吃饭的量”。", "清淡": "搭配：“清淡”多指口味或颜色，不能用来形容吃饭的量。", "稀少": "语义：“稀少”表示数量很少，与“一个人吃了五碗饭”矛盾。"}, "sentence_index": 6, "correct_answer": "惊人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看着这幅画，心里很惊人。", "explanation": "这里应该用〈惊叹〉。“心里”是人的感受，要用〈惊叹〉；惊人只用来形容事物。"}, {"text": "这件事对大家来说很惊人。", "explanation": "这里应该用〈震惊〉。惊人形容事物的程度，“对大家来说”指向人的感受，要用〈震惊〉。"}, {"text": "他们听完故事，都很惊人。", "explanation": "这里应该用〈惊奇〉。惊人形容事物令人吃惊的程度，不用来形容人的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的房价涨惊人。", "corrected_sentence": "这个城市的房价涨得惊人。", "error_description": "错误：动词“涨”后漏掉补语标记“得”。正确的说法是“涨得惊人”，“得”连接动词和表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的员工数量增长地惊人，每年都要招新人。", "corrected_sentence": "这家公司的员工数量增长得惊人，每年都要招新人。", "error_description": "错误：补语前的“地”应为“得”。“增长”后接表示程度的补语要用“得”，“地”只用在状语前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
