INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再见是分开的时候说的话，意思是以后还想见面。", "primary_collocate": null, "pronunciation": "zài jiàn", "ipa": "tsai˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们在车站说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她挥着手对我说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟老师说了再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走时，他没有说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在机场互相说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我说再见，就上班去了。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说完再见，他慢慢走远了。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想跟你说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗摇着尾巴，像在跟我们说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下车以前，他笑着向司机说再见。", "target_word": "再见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "分别时说再见，作说的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a469138-6fb8-45ff-8b3c-19ee085e4330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。再见 zài jiàn 是分别时说的告别语，意思是以后还想见面。"}, {"text": "在线", "is_correct": false, "explanation": "zài xiàn（第四声）与 zài jiàn（第四声）只有声母不同（x 与 j），意思是通过网络连接，不是告别。"}, {"text": "再现", "is_correct": false, "explanation": "xiàn 与 jiàn 只有声母不同（x 与 j），意思是再次出现或重新呈现。"}, {"text": "在家", "is_correct": false, "explanation": "jiā（第一声）与 jiàn（第四声）只差韵尾 n 和声调，意思是待在家里。"}, {"text": "拜见", "is_correct": false, "explanation": "bài（第四声）与 zài 声母不同（b 与 z），意思是郑重地拜访见面，属于书面用语。"}], "explanations": {"再见": "正确。再见 zài jiàn 是分别时说的告别语，意思是以后还想见面。", "在线": "zài xiàn（第四声）与 zài jiàn（第四声）只有声母不同（x 与 j），意思是通过网络连接，不是告别。", "再现": "xiàn 与 jiàn 只有声母不同（x 与 j），意思是再次出现或重新呈现。", "在家": "jiā（第一声）与 jiàn（第四声）只差韵尾 n 和声调，意思是待在家里。", "拜见": "bài（第四声）与 zài 声母不同（b 与 z），意思是郑重地拜访见面，属于书面用语。"}, "sentence_index": null, "correct_answer": "再见"}, "level_3": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。“说再见”是分别时的告别，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎表示迎接，与句子描写的离开场景相反。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：感谢需要带宾语（感谢你），句末没有宾语，不能直接作“说”的宾语。"}, {"text": "挥手", "is_correct": false, "explanation": "搭配：“说”后面接的是话语，“挥手”是动作，不能说“说挥手”。"}], "explanations": {"再见": "正确。“说再见”是分别时的告别，符合句意。", "欢迎": "语义：欢迎表示迎接，与句子描写的离开场景相反。", "感谢": "配价：感谢需要带宾语（感谢你），句末没有宾语，不能直接作“说”的宾语。", "挥手": "搭配：“说”后面接的是话语，“挥手”是动作，不能说“说挥手”。"}, "sentence_index": 0, "correct_answer": "再见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早上在楼道里遇见邻居，我笑着说：“再见！”", "explanation": "这里应该用〈你好〉。早上见面打招呼要说“你好”或“早上好”，“再见”只用于分别时，不能用来问候。"}, {"text": "电话响了，我接起来就说：“再见，你是谁？”", "explanation": "这里应该用〈喂〉。接电话的开场语是“喂”，“再见”是分别时说的，不能用作接电话的招呼。"}, {"text": "我迟到了很久，走进教室时只说了一句：“再见。”", "explanation": "这里应该用〈对不起〉。迟到后进门要先向老师道歉，“再见”是分别时说的，不能代替道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93747, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。再见 zài jiàn 是分别时说的告别语，意思是以后还想见面。"}, {"text": "再加", "is_correct": false, "explanation": "jiā（第一声）与 jiàn（第四声）只差韵尾 n 和声调，意思是再增添。"}, {"text": "再讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàn 韵母不同（ang 与 an），意思是再说一遍。"}, {"text": "再降", "is_correct": false, "explanation": "jiàng（第四声）与 jiàn 韵母不同（ang 与 an），意思是再次下降。"}], "explanations": {"再见": "正确。再见 zài jiàn 是分别时说的告别语，意思是以后还想见面。", "再加": "jiā（第一声）与 jiàn（第四声）只差韵尾 n 和声调，意思是再增添。", "再讲": "jiǎng（第三声）与 jiàn 韵母不同（ang 与 an），意思是再说一遍。", "再降": "jiàng（第四声）与 jiàn 韵母不同（ang 与 an），意思是再次下降。"}, "sentence_index": null, "correct_answer": "再见"}, "level_3": {"options": [{"text": "再见", "is_correct": true, "explanation": "正确。“说完再见”指说完告别的话，符合句意。"}, {"text": "停下", "is_correct": false, "explanation": "语义：“停下”与后面的“慢慢走远”矛盾，说完话又停下，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理的动作，与告别无关，“说完打扫”句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与告别和离开无关，“说完吃饭，他慢慢走远了”句意不通。"}], "explanations": {"再见": "正确。“说完再见”指说完告别的话，符合句意。", "停下": "语义：“停下”与后面的“慢慢走远”矛盾，说完话又停下，句意不通。", "打扫": "语义：打扫是清理的动作，与告别无关，“说完打扫”句意不通。", "吃饭": "语义：吃饭与告别和离开无关，“说完吃饭，他慢慢走远了”句意不通。"}, "sentence_index": 6, "correct_answer": "再见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他收到礼物后，笑着对朋友说：“再见！”", "explanation": "这里应该用〈谢谢〉。收到礼物要表示感谢，“再见”是分别时说的，不能用来道谢。"}, {"text": "朋友告诉我他考上了研究生，我笑着说：“再见！”", "explanation": "这里应该用〈恭喜〉。听到别人的好消息要表示祝贺，“再见”是分别时说的，不能用来祝贺。"}, {"text": "我把钥匙忘在家里了，只好对邻居说：“再见，能借我手机吗？”", "explanation": "这里应该用〈劳驾〉。向别人开口请求帮忙前要先说“劳驾”，“再见”是分别时说的，不能用来开口请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下车以后，对司机再见了。", "corrected_sentence": "他下车以后，对司机说再见了。", "error_description": "错误：“再见”作告别语前漏掉了动词“说”。正确形式是“说再见”，不能说“对司机再见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他转身说了完再见，慢慢走远了。", "corrected_sentence": "他转身说完再见，慢慢走远了。", "error_description": "了的位置错误：“完”作结果补语时，“了”不能插在“说”和“完”之间。应说“说完再见”，不说“说了完再见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7361c5d-28c2-4382-b2f6-1bafeba06391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
