INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "凌晨是晚上过去、天还没亮的时候。", "primary_collocate": null, "pronunciation": "líng chén", "ipa": "liŋ˧˥ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "凌晨四点，街上还没有人。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凌晨才睡觉，早上起不来。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨的城市很安静。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们凌晨出发，中午就到了。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨天还黑着，他就起床了。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车凌晨三点就离开了车站。", "target_word": "凌晨", "complexity_tier": "T3", "furigana": "líng chén", "sentence_source": "generated"}, {"text": "飞机凌晨到北京，我去机场接他。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨很冷，出门要多穿衣服。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天凌晨下了一场大雨。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天凌晨起来跑步。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，夜晚已过、天还黑着的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凌晨", "is_correct": true, "explanation": "正确：凌晨指夜晚已过、天还没亮的时段，与“四点、街上还没有人”相合。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午指十二点前后，与“四点、天还没亮”的情境相矛盾。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是天快黑的傍晚，与天还没亮的时间不符。"}, {"text": "下午", "is_correct": false, "explanation": "语义：下午是白天，与“四点、天还没亮”的情境相矛盾。"}], "explanations": {"凌晨": "正确：凌晨指夜晚已过、天还没亮的时段，与“四点、街上还没有人”相合。", "中午": "语义：中午指十二点前后，与“四点、天还没亮”的情境相矛盾。", "黄昏": "语义：黄昏是天快黑的傍晚，与天还没亮的时间不符。", "下午": "语义：下午是白天，与“四点、天还没亮”的情境相矛盾。"}, "sentence_index": 0, "correct_answer": "凌晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凌晨八点，学校里已经很热闹了。", "explanation": "这里应该用〈早上〉。凌晨指天还没亮的时段，八点时天已大亮，不能用“凌晨”。"}, {"text": "凌晨十点，我们坐在院子里乘凉。", "explanation": "这里应该用〈晚上〉。凌晨指天还没亮的时段，十点已是白天，乘凉应说“晚上”。"}, {"text": "凌晨十一点，我们在饭馆里吃午饭。", "explanation": "这里应该用〈中午〉。凌晨指天还没亮的时段，十一点已是白天，吃午饭的时间应说“中午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凌晨", "is_correct": true, "explanation": "正确：飞机在凌晨到达，与“我去机场接他”相合。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是地点，不表示到达的时间，“飞机车站到北京”不通。"}, {"text": "大雨", "is_correct": false, "explanation": "搭配：“大雨”是天气，不能作“飞机到达”的时间，“飞机大雨到北京”不通。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车是另一种交通工具，不能表示飞机到达的时间，“飞机火车到北京”不通。"}], "explanations": {"凌晨": "正确：飞机在凌晨到达，与“我去机场接他”相合。", "车站": "语义：车站是地点，不表示到达的时间，“飞机车站到北京”不通。", "大雨": "搭配：“大雨”是天气，不能作“飞机到达”的时间，“飞机大雨到北京”不通。", "火车": "语义：火车是另一种交通工具，不能表示飞机到达的时间，“飞机火车到北京”不通。"}, "sentence_index": 6, "correct_answer": "凌晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凌晨两点，我们在饭馆里吃晚饭。", "explanation": "这里应该用〈晚上〉。凌晨指天还没亮的时段，吃晚饭的时间应说“晚上”。"}, {"text": "凌晨十点，我们开会。", "explanation": "这里应该用〈上午〉。凌晨指午夜后到天亮前，十点已是上午。"}, {"text": "凌晨三点，我们去学校听下午的课。", "explanation": "这里应该用〈下午〉。凌晨指天还没亮的时段，三点不是下午，下午的课不能说“凌晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凌晨街道很安静，没有人说话。", "corrected_sentence": "凌晨的街道很安静，没有人说话。", "error_description": "错误形式：“凌晨街道”。正确形式：“凌晨的街道”。“凌晨”修饰具体名词时，通常要加“的”，直接连说则生硬。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凌晨雨声很大，把我吵醒了。", "corrected_sentence": "凌晨的雨声很大，把我吵醒了。", "error_description": "错误形式：“凌晨雨声”。正确形式：“凌晨的雨声”。“凌晨”修饰具体名词时，通常要加“的”，直接连说则生硬。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
