INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天快亮或刚亮的时候，一般指午夜以后到天亮前。", "primary_collocate": null, "pronunciation": "líng chén", "ipa": "liŋ˧˥ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "凌晨五点，天边慢慢亮了。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨三点多，医院里还有很多人。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们凌晨赶到车站，等第一班车。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨的街道上一个人也没有。", "target_word": "凌晨", "complexity_tier": "T3", "furigana": "líng chén", "sentence_source": "generated"}, {"text": "渔民凌晨就上船出海了。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了午夜，到了凌晨，雨才停。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球赛在凌晨结束，我一夜没睡。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨两点，他还在写作业。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们凌晨开始扫街。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凌晨的风吹在脸上很凉。", "target_word": "凌晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，午夜之后到天亮之前、天快亮的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凌晨", "is_correct": true, "explanation": "正确：凌晨指午夜后到天亮前，天边慢慢亮起来的时候，与“五点、天边慢慢亮了”相合。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是天慢慢暗下来的时候，与“天边慢慢亮了”相反。"}, {"text": "午后", "is_correct": false, "explanation": "语义：午后是白天的下午，不是天边慢慢亮起来的时候。"}, {"text": "日暮", "is_correct": false, "explanation": "语域：日暮是书面语，指日落时分，与“天边慢慢亮了”相反。"}], "explanations": {"凌晨": "正确：凌晨指午夜后到天亮前，天边慢慢亮起来的时候，与“五点、天边慢慢亮了”相合。", "黄昏": "语义：黄昏是天慢慢暗下来的时候，与“天边慢慢亮了”相反。", "午后": "语义：午后是白天的下午，不是天边慢慢亮起来的时候。", "日暮": "语域：日暮是书面语，指日落时分，与“天边慢慢亮了”相反。"}, "sentence_index": 0, "correct_answer": "凌晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凌晨八点，街道上的人多了起来。", "explanation": "这里应该用〈上午〉。凌晨指午夜后到天亮前，八点已是上午。"}, {"text": "凌晨十点，街道上的路灯一盏盏亮了。", "explanation": "这里应该用〈晚上〉。凌晨指天快亮的时候，十点已是白天，路灯亮起是晚上的景象。"}, {"text": "凌晨四点，大家在河边喝下午茶。", "explanation": "这里应该用〈下午〉。凌晨指午夜后到天亮前的时段，四点不是下午，喝下午茶应说“下午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凌晨", "is_correct": true, "explanation": "正确：球赛在凌晨结束，与“我一夜没睡”相合。"}, {"text": "中场", "is_correct": false, "explanation": "语义：中场是比赛的中途，不是比赛结束的时刻。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭”是进餐的时间，不能用来指比赛结束的时刻。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“晚饭”是进餐的时间，不能用来指比赛结束的时刻。"}], "explanations": {"凌晨": "正确：球赛在凌晨结束，与“我一夜没睡”相合。", "中场": "语义：中场是比赛的中途，不是比赛结束的时刻。", "午饭": "搭配：“午饭”是进餐的时间，不能用来指比赛结束的时刻。", "晚饭": "搭配：“晚饭”是进餐的时间，不能用来指比赛结束的时刻。"}, "sentence_index": 6, "correct_answer": "凌晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凌晨九点，我们在湖边吃晚饭。", "explanation": "这里应该用〈晚上〉。凌晨指天快亮或刚亮的时候，吃晚饭应说“晚上”。"}, {"text": "凌晨十一点，饭馆里坐满了人。", "explanation": "这里应该用〈中午〉。凌晨指天亮前的时段，十一点已是白天。"}, {"text": "凌晨两点，学校里的学生都在上课。", "explanation": "这里应该用〈白天〉。凌晨指天快亮或刚亮的时候，学生上课的时段应说“白天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很凌晨出发，去爬山。", "corrected_sentence": "我们凌晨出发，去爬山。", "error_description": "错误形式：“很凌晨”。正确形式：“凌晨”。程度副词“很”不能修饰时间词“凌晨”，应直接说“凌晨出发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很凌晨两点就出门了。", "corrected_sentence": "他凌晨两点就出门了。", "error_description": "错误形式：“很凌晨两点”。正确形式：“凌晨两点”。程度副词“很”不能修饰时间词“凌晨”，应直接说“凌晨两点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
