INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93752, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用于分数中，表示把整体分成若干等份后所占的份数。", "primary_collocate": null, "pronunciation": "fēn zhī", "ipa": "fən˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "这块蛋糕我吃了四分之一。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有三分之二的同学是女生。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水杯里只有三分之一的水了。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经走了全程的二分之一。", "target_word": "分之", "complexity_tier": "T3", "furigana": "wǒ men yǐ jīng zǒu le quán chéng de èr fēn zhī yī。", "sentence_source": "generated"}, {"text": "这本书我看了五分之四。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个季节是一年的四分之一。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把苹果分成四份，吃了其中四分之三。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全校三分之一的学生坐车上学。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里八分之五的灯都开着。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一天睡觉的时间是二十四小时的三分之一。", "target_word": "分之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二分之一", "label": "复合"}, {"form": "四分之三", "label": "复合"}], "register": "中性", "sense_fingerprint": "分数中表示整体分成几份后占几份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确答案。分之读 fēn zhī，是分数中的助词，表示整体分成若干份后所占的份数。"}, {"text": "分吃", "is_correct": false, "explanation": "chī（第一声）与 zhī（第一声）声调相同，只有声母不同（ch 与 zh），意思是“分开吃”。"}, {"text": "坟址", "is_correct": false, "explanation": "fén（第二声）与 fēn（第一声）声调不同，zhǐ（第三声）与 zhī（第一声）声调也不同，意思是坟墓的位置。"}, {"text": "分值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数或得分的价值。"}, {"text": "分制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是学分或分数的制度。"}], "explanations": {"分之": "正确答案。分之读 fēn zhī，是分数中的助词，表示整体分成若干份后所占的份数。", "分吃": "chī（第一声）与 zhī（第一声）声调相同，只有声母不同（ch 与 zh），意思是“分开吃”。", "坟址": "fén（第二声）与 fēn（第一声）声调不同，zhǐ（第三声）与 zhī（第一声）声调也不同，意思是坟墓的位置。", "分值": "zhí（第二声）与 zhī（第一声）声调不同，意思是分数或得分的价值。", "分制": "zhì（第四声）与 zhī（第一声）声调不同，意思是学分或分数的制度。"}, "sentence_index": null, "correct_answer": "分之"}, "level_3": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确。“四分之一”是分数的固定结构，分之表示分成若干份后所占的份数。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“四的一”不是分数的说法，两个数字之间不能直接用“的”连接。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”用于修饰动词或形容词，不能放在两个数字之间。"}, {"text": "所", "is_correct": false, "explanation": "语域：“所”属书面结构，要接动词构成名词性词组，不能用在表示份数的数字之间。"}], "explanations": {"分之": "正确。“四分之一”是分数的固定结构，分之表示分成若干份后所占的份数。", "的": "搭配：“四的一”不是分数的说法，两个数字之间不能直接用“的”连接。", "地": "搭配：“地”用于修饰动词或形容词，不能放在两个数字之间。", "所": "语域：“所”属书面结构，要接动词构成名词性词组，不能用在表示份数的数字之间。"}, "sentence_index": 0, "correct_answer": "分之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把一块蛋糕分成三分之一。", "explanation": "这里应该用〈三份〉。“分成”后面要接份数，不能接表示占比的分数；“三分之一”表示份额，要说“分成三份”。"}, {"text": "我们班有很多分之一的同学是女生。", "explanation": "这里应该用〈三〉。“分之一”前缺分子，“很多”不是数字；把“很多”改为“三”，即“三分之一的同学”。"}, {"text": "这次数学考了三分之一。", "explanation": "这里应该用〈三十分〉。考试成绩要说得了几分，“三分之一”表示份额，不能当作考试得分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93752, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确答案。分之读 fēn zhī，是分数中的助词，表示整体分成若干份后所占的份数。"}, {"text": "分子", "is_correct": false, "explanation": "zǐ（第三声）与 zhī（第一声）声母和声调都不同，意思是分数里的“分子”。"}, {"text": "粉质", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，zhì（第四声）与 zhī（第一声）声调也不同，意思是粉末的性质。"}, {"text": "分置", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是分开设置。"}], "explanations": {"分之": "正确答案。分之读 fēn zhī，是分数中的助词，表示整体分成若干份后所占的份数。", "分子": "zǐ（第三声）与 zhī（第一声）声母和声调都不同，意思是分数里的“分子”。", "粉质": "fěn（第三声）与 fēn（第一声）声调不同，zhì（第四声）与 zhī（第一声）声调也不同，意思是粉末的性质。", "分置": "zhì（第四声）与 zhī（第一声）声调不同，意思是分开设置。"}, "sentence_index": null, "correct_answer": "分之"}, "level_3": {"options": [{"text": "分之", "is_correct": true, "explanation": "正确。“其中四分之三”表示占整体的份额，分之是固定的分数结构。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”用来引出补语，不能接在两个数字之间，“其中四得三”不通顺。"}, {"text": "似的", "is_correct": false, "explanation": "语义：“似的”表示相似，与整体中所占的份额无关，“其中四似的三”说不通。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示限定语气，不能表示整体中所占的份数。"}], "explanations": {"分之": "正确。“其中四分之三”表示占整体的份额，分之是固定的分数结构。", "得": "搭配：“得”用来引出补语，不能接在两个数字之间，“其中四得三”不通顺。", "似的": "语义：“似的”表示相似，与整体中所占的份额无关，“其中四似的三”说不通。", "而已": "语义：“而已”表示限定语气，不能表示整体中所占的份数。"}, "sentence_index": 6, "correct_answer": "分之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一天睡觉的时间是二十四小时的分之一。", "explanation": "这里应该用〈三〉。“分之一”前缺分子，应说“三分之一”。"}, {"text": "他在班里的排名是三分之一。", "explanation": "这里应该用〈第几名〉。“三分之一”表示占总数的份额，不能用来说排名；排名要说“第几名”或“前几名”。"}, {"text": "这次比赛他拿了三分之一的冠军。", "explanation": "这里应该用〈第一名〉。冠军是唯一的名次，不能按份额计算；“三分之一”只用于可以平分的整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯果汁我只喝了三个分之一。", "corrected_sentence": "这杯果汁我只喝了三分之一。", "error_description": "多加了量词。“三个分之一”在数字和“分之”之间加了“个”，分数结构要连续说“三分之一”，量词会打断分数结构，应为“三分之一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张纸我用了五的分之二。", "corrected_sentence": "这张纸我用了五分之二。", "error_description": "错误：“五”与“分之”之间多加了“的”。分数结构要连续说“五分之二”，不能在数字和“分之”之间加“的”，应为“五分之二”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
