INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "运行在铁路上的成列的客车或货车。", "primary_collocate": null, "pronunciation": "liè chē", "ipa": "liɛ˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "这趟列车开往上海。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车十点准时离开了车站。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京的列车晚点了。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车上有很多乘客。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一列长长的列车从桥边开走了。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家在站台等候，列车马上进站。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车在雪地里慢慢前进。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车到站时，我们下了车。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车上的饭菜不太贵。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在列车上看了一本书。", "target_word": "列车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列", "label": "量词"}, {"form": "趟", "label": "量词"}, {"form": "列车员", "label": "复合"}, {"form": "列車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在铁路上运行的成列客车或货车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "列车", "is_correct": true, "explanation": "正确：「列车」是铁路上运行的车，可以「开往」某地。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不能「开往」某地，「开往」要求交通工具。"}, {"text": "书包", "is_correct": false, "explanation": "语义：「书包」不是交通工具，不能「开往上海」。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「趟」用于车次、行程，不能用来量「作业」。"}], "explanations": {"列车": "正确：「列车」是铁路上运行的车，可以「开往」某地。", "天气": "语义：「天气」不能「开往」某地，「开往」要求交通工具。", "书包": "语义：「书包」不是交通工具，不能「开往上海」。", "作业": "搭配：「趟」用于车次、行程，不能用来量「作业」。"}, "sentence_index": 0, "correct_answer": "列车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游客坐列车在湖上游览。", "explanation": "这里应该用〈轮船〉，指在水上行驶。列车只在铁路上运行，不能在湖上行驶。"}, {"text": "我周末坐列车出海钓鱼。", "explanation": "这里应该用〈游艇〉，指在海上航行。列车不能出海，「出海」要用船只。"}, {"text": "这里的列车每天在天上往返。", "explanation": "这里应该用〈飞机〉，指在空中飞行的交通工具。列车只在地面铁路上运行，不能在天上往返。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列车", "is_correct": true, "explanation": "正确：「列车」能在铁路上前进，与「慢慢前进」搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己前进，与「慢慢前进」冲突。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能自己在雪地里前进。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「前进」的主语要能移动，「窗户」不能与「前进」搭配。"}], "explanations": {"列车": "正确：「列车」能在铁路上前进，与「慢慢前进」搭配。", "石头": "语义：石头不会自己前进，与「慢慢前进」冲突。", "桌子": "语义：桌子不能自己在雪地里前进。", "窗户": "搭配：「前进」的主语要能移动，「窗户」不能与「前进」搭配。"}, "sentence_index": 6, "correct_answer": "列车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车站里停着一座列车。", "explanation": "这里应该用〈列〉。列车用量词「列」，「座」用于山、桥、楼等大型固定物，不能量列车。"}, {"text": "我在站台看见一只列车。", "explanation": "这里应该用〈列〉。「只」用于动物或成对的器官，不能用来量列车。"}, {"text": "那边开来一张列车。", "explanation": "这里应该用〈列〉。「张」用于平面的东西，不能用来量列车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在车站等一个列车。", "corrected_sentence": "我们在车站等一趟列车。", "error_description": "错误形式：「一个列车」；正确形式：「一趟列车」。「个」是通用量词，列车应使用专用量词「趟」或「列」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐列车了去北京。", "corrected_sentence": "我们坐列车去北京。", "error_description": "错误形式：「坐列车了去」；正确形式：「坐列车去」。「了」表示动作已经完成，而这里只是去北京的计划，不能放在宾语「列车」之后、动词「去」之前，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
