INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "参数是一个东西的各种数字，比如多长、多重。", "primary_collocate": null, "pronunciation": "cān shù", "ipa": "tsʰan˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "买手机前，我先看了它的参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视的参数写在盒子上。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的各项参数都很不错。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书桌的参数是长一米二，宽六十厘米。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这款耳机的参数告诉我。", "target_word": "参数", "complexity_tier": "T3", "furigana": "qǐng bǎ zhè kuǎn ěrjī de cānshù gàosu wǒ", "sentence_source": "generated"}, {"text": "他不懂这些参数是什么意思。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的参数里有重量和高度。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书上有产品的所有参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你比较一下两台电脑的参数吧。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买床以前，先量好房间，再看床的参数。", "target_word": "参数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "参數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物品的尺寸重量等数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82c505de-860d-4fc2-8b67-54278872591e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93755, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。cānshù 即“参数”，指物品的规格数字，如长度、重量。"}, {"text": "残暑", "is_correct": false, "explanation": "cán（第二声）与 cān（第一声）声调不同，shǔ（第三声）与 shù（第四声）声调也不同，意思是夏末的余热。"}, {"text": "惨输", "is_correct": false, "explanation": "cǎn（第三声）与 cān（第一声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是输得很惨。"}, {"text": "餐食", "is_correct": false, "explanation": "shí（第二声）与 shù（第四声）韵母不同，意思是饭菜、食物。"}, {"text": "餐室", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同，意思是餐厅或用餐的房间。"}], "explanations": {"参数": "正确。cānshù 即“参数”，指物品的规格数字，如长度、重量。", "残暑": "cán（第二声）与 cān（第一声）声调不同，shǔ（第三声）与 shù（第四声）声调也不同，意思是夏末的余热。", "惨输": "cǎn（第三声）与 cān（第一声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是输得很惨。", "餐食": "shí（第二声）与 shù（第四声）韵母不同，意思是饭菜、食物。", "餐室": "shì（第四声）与 shù（第四声）韵母不同，意思是餐厅或用餐的房间。"}, "sentence_index": null, "correct_answer": "参数"}, "level_3": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。“参数”指手机的规格数字，可以用“看了它的”来修饰。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格指人的个性，手机没有性格，不能说“看了它的性格”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，手机没有心情，不能说“看了它的心情”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人或动物的性情，手机没有脾气，句中的“它”无法对应。"}], "explanations": {"参数": "正确。“参数”指手机的规格数字，可以用“看了它的”来修饰。", "性格": "语义：性格指人的个性，手机没有性格，不能说“看了它的性格”。", "心情": "语义：心情是人的情绪，手机没有心情，不能说“看了它的心情”。", "脾气": "语义：脾气属于人或动物的性情，手机没有脾气，句中的“它”无法对应。"}, "sentence_index": 0, "correct_answer": "参数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的参数是一米七五，体重六十公斤。", "explanation": "这里应该用〈身高〉。参数指物品的规格数值，不用于人；人的身高要说身高。"}, {"text": "这碗汤的参数很鲜。", "explanation": "这里应该用〈味道〉。参数指产品的规格数值，不能用来形容食物的味道，“鲜”说的是味道。"}, {"text": "他的参数在北京。", "explanation": "这里应该用〈地址〉。参数指产品的规格数字，不指地点；说人住在哪里要用地址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参数", "is_correct": true, "explanation": "正确。“参数”指冰箱的规格数字，其中包括重量和高度。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，不包含重量和高度，与句中的数值冲突。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身高，冰箱没有身高，不能用于冰箱。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指金额，不是重量或高度的数值，与“重量和高度”冲突。"}], "explanations": {"参数": "正确。“参数”指冰箱的规格数字，其中包括重量和高度。", "颜色": "语义：颜色指色彩，不包含重量和高度，与句中的数值冲突。", "身高": "体貌：身高指人的身高，冰箱没有身高，不能用于冰箱。", "价格": "语义：价格指金额，不是重量或高度的数值，与“重量和高度”冲突。"}, "sentence_index": 6, "correct_answer": "参数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视的参数是三千元。", "explanation": "这里应该用〈价格〉。参数指规格数值，不指价钱。"}, {"text": "这辆车的参数是白色的。", "explanation": "这里应该用〈颜色〉。参数指数字规格，不能用来说颜色。"}, {"text": "这个包的参数是耐克。", "explanation": "这里应该用〈品牌〉。参数指规格数值，不指生产厂家的品牌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视有很多把参数。", "corrected_sentence": "这台电视有很多项参数。", "error_description": "量词错误：“参数”的量词应为“项”或“个”，不能用“把”（“把”用于有把手的东西）。正确说法是“这台电视有很多项参数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床有很多块参数。", "corrected_sentence": "这张床有很多项参数。", "error_description": "量词错误：“块”用于块状的东西，不能用来数“参数”。“参数”应搭配“项”或“个”，正确说法是“这张床有很多项参数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b6d4cb-ba77-4dc5-a79a-8e3f50507272') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
