INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "指已提到的以外的；别的一个。", "primary_collocate": null, "pronunciation": "lìng yī", "ipa": "liŋ˥˩ i˥", "syllable_count": 2, "sentences": [{"text": "她在一家银行工作，也在另一家公司做事。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换另一个办法试试。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了这件事，还有另一个问题。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期很忙，我们约在另一天吧。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "另一个人也想来，可以吗？", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样说不对，我从另一个方面想想。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的另一边有一个小公园。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在另一个城市，很少回家。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不喜欢这个，可以选另一种。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们另一个机会。", "target_word": "另一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一个", "label": "量词"}, {"form": "另一种", "label": "量词"}, {"form": "另一方面", "label": "复合"}], "register": "中性", "sense_fingerprint": "指已提到的以外的别的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c64dac-31c4-43a0-9af4-743730ddc3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同一", "is_correct": false, "explanation": "语义：同一表示相同的那一家，与“另一家”指不同的公司相反。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一家”指已提到的银行以外的别的公司，与“也在”相合，符合句意。"}, {"text": "每一", "is_correct": false, "explanation": "语义：每一指全部中的每一个，与“另一家”只指一家不符。"}, {"text": "这一", "is_correct": false, "explanation": "语义：这一家指说话人指定的某一家公司，并非银行以外“另外”的一家，与句意不符。"}], "explanations": {"同一": "语义：同一表示相同的那一家，与“另一家”指不同的公司相反。", "另一": "正确：“另一家”指已提到的银行以外的别的公司，与“也在”相合，符合句意。", "每一": "语义：每一指全部中的每一个，与“另一家”只指一家不符。", "这一": "语义：这一家指说话人指定的某一家公司，并非银行以外“另外”的一家，与句意不符。"}, "sentence_index": 0, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在一家银行工作，也在另一条公司做事。", "explanation": "这里应该用〈家〉。“条”用于细长的东西，公司要用“家”。"}, {"text": "我们换另一把办法试试。", "explanation": "这里应该用〈种〉。“把”用于有柄的东西，办法要用“种”或“个”。"}, {"text": "我只有一个朋友，另一个朋友很热情。", "explanation": "这里应该用〈还有一个〉。“另一”指已提到之外的别的一个；这里前文说“只有一个朋友”，就没有别的朋友可指，两句互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任一", "is_correct": false, "explanation": "语义：任一指任选其一，与“河的一边”这种特定位置不符。"}, {"text": "同一", "is_correct": false, "explanation": "语义：同一指同一边，句中并无已提及的一边可供指称，与“河的另一边”（对岸）不符。"}, {"text": "另一", "is_correct": true, "explanation": "正确：“另一边”指河的另外一边，与“有一个小公园”相合，符合句意。"}, {"text": "前一", "is_correct": false, "explanation": "语义：前一指先前提到的那一个，与“河的另一边”的并列位置不符。"}], "explanations": {"任一": "语义：任一指任选其一，与“河的一边”这种特定位置不符。", "同一": "语义：同一指同一边，句中并无已提及的一边可供指称，与“河的另一边”（对岸）不符。", "另一": "正确：“另一边”指河的另外一边，与“有一个小公园”相合，符合句意。", "前一": "语义：前一指先前提到的那一个，与“河的另一边”的并列位置不符。"}, "sentence_index": 6, "correct_answer": "另一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师给了我们另一座机会。", "explanation": "这里应该用〈个〉。“座”用于山、桥、房屋等大型固定的东西，机会要用“个”。"}, {"text": "老师给了我们另一位机会。", "explanation": "这里应该用〈个〉。“位”用于人，“机会”要用“个”。"}, {"text": "公司只有一位老板，另一位老板在上海。", "explanation": "这里应该用〈还有一位〉。“另一”指已提到之外的别的一个，这里前文说“只有一位老板”，就没有别的老板可指，两句互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案不行，我们换另一只方案吧。", "corrected_sentence": "这个方案不行，我们换另一个方案吧。", "error_description": "错误：量词“只”。“方案”的量词应用“个”，“只”不用于方案，应写成“另一个方案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他换了另一的公司。", "corrected_sentence": "他换了另一家公司。", "error_description": "错误：“另一”后多加了“的”。“另一”后直接接量词“家”，应写成“另一家公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff0adbf3-a8dc-4e3e-bb6a-3e31a0ab0df8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
