INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个范围以外的地方或环境；外部。", "primary_collocate": null, "pronunciation": "wài jiè", "ipa": "wai˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "外界的温度会影响植物的生长。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界对这件事有很多看法。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司不愿意向外界公开消息。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物会对外界的变化做出反应。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要太在意外界的评价。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们通过网络了解外界。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，身体要适应外界的冷空气。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新计划还没有对外界说明。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界都在猜他会不会参加比赛。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验要避免外界的光线进入。", "target_word": "外界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：某个范围、群体或系统之外的环境与人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，表示某个范围之外的环境影响温度，是本句的原词。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔与植物的生长没有关系，“钢笔的温度会影响植物的生长”句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字的温度”不是常用搭配，句子不自然。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不具有温度属性，与“影响植物的生长”的语境不符。"}], "explanations": {"外界": "空格处应填“外界”，表示某个范围之外的环境影响温度，是本句的原词。", "钢笔": "语义：钢笔与植物的生长没有关系，“钢笔的温度会影响植物的生长”句意不通。", "名字": "搭配：“名字的温度”不是常用搭配，句子不自然。", "声音": "语义：声音不具有温度属性，与“影响植物的生长”的语境不符。"}, "sentence_index": 0, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的外界很英俊。", "explanation": "这里应该用“外表”。外界指周围的环境，不能用来形容人的外在形象。"}, {"text": "外界一边吃饭，一边看书。", "explanation": "这里“外界”被误当成了“人、别人”的意思。外界是环境，不能做吃饭、看书的动作，应该用“他”“我”这样的人作主语。"}, {"text": "这里有一条外界。", "explanation": "这里“外界”被误当成了“河流、道路”之类的具体事物，所以误用了量词“条”。外界是抽象的环境，不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外界", "is_correct": true, "explanation": "空格处应填“外界”，表示冬天身体要适应外面的冷空气，是本句的原词。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作的冷空气”没有意义，与句意冲突。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能产生冷空气，与“冬天身体要适应”的语境不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“适应书包的冷空气”不是常用搭配，句子不自然。"}], "explanations": {"外界": "空格处应填“外界”，表示冬天身体要适应外面的冷空气，是本句的原词。", "工作": "语义：“工作的冷空气”没有意义，与句意冲突。", "课本": "语义：课本不能产生冷空气，与“冬天身体要适应”的语境不符。", "书包": "搭配：“适应书包的冷空气”不是常用搭配，句子不自然。"}, "sentence_index": 6, "correct_answer": "外界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在外界做饭，我在旁边帮忙。", "explanation": "这里应该用“厨房”。外界指某个范围以外的环境，不能用来指做饭的具体房间。"}, {"text": "这个小组的外界很团结。", "explanation": "这里应该用“成员”。外界指环境，不能指组成小组的人。"}, {"text": "这本书的外界很漂亮。", "explanation": "这里应该用“封面”。外界指周围的环境，不能用来指书的外层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城很少受到一个外界的影响。", "corrected_sentence": "这座小城很少受到外界的影响。", "error_description": "错误：在“外界”前加了数量短语“一个”。外界是抽象概念，不能被数量词修饰，应直接说“外界的影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外界地消息传得很快。", "corrected_sentence": "外界的消息传得很快。", "error_description": "错误：外界与中心语“消息”之间的定语标记“的”写成了“地”。“地”用于状语后，修饰名词应用“的”，应说“外界的消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
