INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容是用话把一个东西是什么样子说出来。", "primary_collocate": null, "pronunciation": "xíng róng", "ipa": "ɕiŋ˧˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "请你形容一下那个人的样子。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他形容那只狗像小马一样大。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们形容一下自己的家。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把昨天看到的小偷形容了一遍。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明形容那座山高得看不到顶。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能形容一下这个蛋糕的味道吗？", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她形容那个地方像一幅画。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请他形容一下小偷的脸。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟形容月亮像一个大盘子。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈形容我小时候很爱哭。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形容了", "label": "体标（了）"}, {"form": "形容过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "形容：用话说出人或东西的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示想不起来，不能用来要求对方描述样子。"}, {"text": "形容", "is_correct": true, "explanation": "“形容”表示用话说出人的样子，与“请你形容一下那个人的样子”相符。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”需要协同的对象或行动，不能说“配合样子”。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”针对有形的物体，不能用于描述人的样子。"}], "explanations": {"忘记": "语义：“忘记”表示想不起来，不能用来要求对方描述样子。", "形容": "“形容”表示用话说出人的样子，与“请你形容一下那个人的样子”相符。", "配合": "搭配：“配合”需要协同的对象或行动，不能说“配合样子”。", "搬运": "搭配：“搬运”针对有形的物体，不能用于描述人的样子。"}, "sentence_index": 0, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心把杯子形容碎了。", "explanation": "这里应该用〈摔〉。“形容”是用语言描述样子，不能表示用力使杯子碎裂。"}, {"text": "他把杯子形容在桌子上。", "explanation": "这里应该用〈放〉。“形容”是用话描述，不能表示把东西放在某处。"}, {"text": "他形容完了一封信。", "explanation": "这里应该用〈写〉。“形容”是描述样子，不能表示写信这一动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "语义：“参观”指到某处看看，不能引出“像一幅画”的比喻。"}, {"text": "形容", "is_correct": true, "explanation": "“形容”表示用话描述事物的样子，与“她形容那个地方像一幅画”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物或故障，不能用于“那个地方”。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带地点作宾语，“唱那个地方”不成立。"}], "explanations": {"参观": "语义：“参观”指到某处看看，不能引出“像一幅画”的比喻。", "形容": "“形容”表示用话描述事物的样子，与“她形容那个地方像一幅画”相符。", "修理": "搭配：“修理”针对器物或故障，不能用于“那个地方”。", "唱": "配价：“唱”不能带地点作宾语，“唱那个地方”不成立。"}, "sentence_index": 6, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈形容了一顿晚饭。", "explanation": "这里应该用〈吃〉。“形容”表示描述样子，不能用来表示吃饭这类动作。"}, {"text": "妈妈形容我去了学校。", "explanation": "这里应该用〈告诉〉。“形容”表示描述样子，不能用来陈述去学校这类经过。"}, {"text": "妈妈形容完了一首歌。", "explanation": "这里应该用〈唱〉。“形容”是描述样子，不能表示唱歌这一动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想形容一下子那只猫的颜色。", "corrected_sentence": "他想形容一下那只猫的颜色。", "error_description": "“形容一下”是动词加补语的固定说法，表示稍作描述；“一下子”表示时间短或突然，不能放在动词和宾语之间。错误形式：形容一下子；正确形式：形容一下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经形容了过他的样子。", "corrected_sentence": "我曾经形容过他的样子。", "error_description": "“形容”的体标只能用“过”，不能同时用“了”。错误形式：形容了过；正确形式：形容过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
