INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用语言描述事物的样子或性质。", "primary_collocate": null, "pronunciation": "xíng róng", "ipa": "ɕiŋ˧˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "很难用一句话形容这里的风景。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友这样形容她：热情又大方。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种香味真是没法形容。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他形容这次考试像打仗一样紧张。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者形容那场雨大得吓人。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她形容这件衣服的颜色很特别。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用几个词形容你的好朋友。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都形容他是个老实人。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里形容那只猫很懒。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎么形容现在的心情。", "target_word": "形容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形容了", "label": "体标（了）"}, {"form": "形容过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "形容：用语言描述事物的样子或性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”靠镜头记录影像，不能用一句话来完成，句意不通。"}, {"text": "形容", "is_correct": true, "explanation": "“形容”表示用语言描述事物的样子，与“用一句话形容风景”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物或故障，不能用于“风景”。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语应是可买的东西，“风景”不能被购买。"}], "explanations": {"拍摄": "语义：“拍摄”靠镜头记录影像，不能用一句话来完成，句意不通。", "形容": "“形容”表示用语言描述事物的样子，与“用一句话形容风景”相符。", "修理": "搭配：“修理”针对器物或故障，不能用于“风景”。", "购买": "配价：“购买”的宾语应是可买的东西，“风景”不能被购买。"}, "sentence_index": 0, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他形容干净了桌子。", "explanation": "这里应该用〈擦〉。“形容”只能用语言描述，不能表示用手擦拭。"}, {"text": "他把钥匙形容在抽屉里。", "explanation": "这里应该用〈放〉。“形容”是用话描述，不能表示把东西放在某处。"}, {"text": "他把书形容进了书包。", "explanation": "这里应该用〈放〉。“形容”是用话描述，不能表示把东西装进某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取消", "is_correct": false, "explanation": "语义：“取消”表示撤销，不能用来指对朋友的描述，句意不通。"}, {"text": "形容", "is_correct": true, "explanation": "“形容”表示用话描述人的样子或性质，与“用几个词形容你的好朋友”相符。"}, {"text": "雇佣", "is_correct": false, "explanation": "配价：“雇佣”需要雇主和受雇的工作，不能用于描述朋友。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”表示说假话害人，与“用几个词”描述朋友的语境不符。"}], "explanations": {"取消": "语义：“取消”表示撤销，不能用来指对朋友的描述，句意不通。", "形容": "“形容”表示用话描述人的样子或性质，与“用几个词形容你的好朋友”相符。", "雇佣": "配价：“雇佣”需要雇主和受雇的工作，不能用于描述朋友。", "欺骗": "语义：“欺骗”表示说假话害人，与“用几个词”描述朋友的语境不符。"}, "sentence_index": 6, "correct_answer": "形容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我形容完了一碗面。", "explanation": "这里应该用〈吃〉。“形容”是描述样子，不能表示吃面这一动作。"}, {"text": "我形容完了一封信。", "explanation": "这里应该用〈写〉。“形容”是描述样子，不能表示写信这一动作。"}, {"text": "我形容了他的名字。", "explanation": "这里应该用〈忘〉。“形容”是描述样子或性质，不能表示忘记人名这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这个场景形容很生动。", "corrected_sentence": "我把这个场景形容得很生动。", "error_description": "“形容”带补语时，须用“得”连接补语。错误形式：形容很生动；正确形式：形容得很生动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
