INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一时期的后一阶段。", "primary_collocate": null, "pronunciation": "hòu qī", "ipa": "xoʊ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "电影进入后期，大家都很忙。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后期，他的体力不够了。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程后期，我们遇到了新问题。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的后期作品更成熟。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在后期投入了更多钱。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划的后期，需要大家多帮忙。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了后期，学习变得更难了。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情后期，学校又开门了。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的后期很精彩。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工程的后期很轻松。", "target_word": "后期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後期", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某个时期中靠后的一个阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。"}, {"text": "后记", "is_correct": false, "explanation": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。"}, {"text": "后勤", "is_correct": false, "explanation": "后勤（qín）与后期（qī）韵母不同（-in 与 -i），意思是后方的保障工作。"}, {"text": "后起", "is_correct": false, "explanation": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。"}, {"text": "后世", "is_correct": false, "explanation": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。"}, {"text": "后区", "is_correct": false, "explanation": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}], "explanations": {"后期": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。", "后记": "后记（jì）与后期（qī）第二音节声母不同（j 与 q），意思是书籍末尾的附记。", "后勤": "后勤（qín）与后期（qī）韵母不同（-in 与 -i），意思是后方的保障工作。", "后起": "后起（qǐ，第三声）与后期（qī，第一声）声调不同，意思是较晚出现的。", "后世": "后世（shì）与后期（qī）声母不同（sh 与 q），意思是子孙后代。", "后区": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指某一时期的后一阶段，「电影进入后期」自然，符合「大家都很忙」的语境。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜是一个时间点，不能指电影所处的阶段。"}, {"text": "年末", "is_correct": false, "explanation": "搭配：「年末」只指年份的末尾，不说「电影进入年末」。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期是停工停课的时段，电影不会「进入假期」。"}], "explanations": {"后期": "后期指某一时期的后一阶段，「电影进入后期」自然，符合「大家都很忙」的语境。", "深夜": "语义：深夜是一个时间点，不能指电影所处的阶段。", "年末": "搭配：「年末」只指年份的末尾，不说「电影进入年末」。", "假期": "语义：假期是停工停课的时段，电影不会「进入假期」。"}, "sentence_index": 0, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的座位在教室的后期。", "explanation": "这里应该用〈后面〉。后期指时间上靠后的阶段，表示空间位置要用后面。"}, {"text": "这辆车的后期坏了。", "explanation": "这里的「后期」指时间阶段，不指车的部位。车尾应说〈后部〉或〈后面〉，不能用后期。"}, {"text": "我吃了蛋糕的后期。", "explanation": "这里应该用〈后半块〉。后期只指时间阶段，不能指食物的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "后期", "is_correct": true, "explanation": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。"}, {"text": "后继", "is_correct": false, "explanation": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。"}, {"text": "后区", "is_correct": false, "explanation": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。"}, {"text": "后视", "is_correct": false, "explanation": "后视（shì）与后期（qī）声母不同（sh 与 q），意思是向后看。"}, {"text": "后事", "is_correct": false, "explanation": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。"}], "explanations": {"后期": "正确答案。后期指某一时期的后一阶段，读作 hòu qī。", "后继": "后继（jì）与后期（qī）第二音节声母不同（j 与 q），意思是接续的人。", "后区": "后区（qū）与后期（qī）韵母不同（-ü 与 -i），指彩票中的后区号码。", "后视": "后视（shì）与后期（qī）声母不同（sh 与 q），意思是向后看。", "后事": "后事（shì）与后期（qī）声母不同（sh 与 q），意思是身后的事务。"}, "sentence_index": null, "correct_answer": "后期"}, "level_3": {"options": [{"text": "后期", "is_correct": true, "explanation": "后期指某一时期的后一阶段，「到了后期」符合语境，学习变难。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭的时段，不能指学习的阶段。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：晚餐同样是一顿饭，与学习的阶段无关。"}, {"text": "难度", "is_correct": false, "explanation": "搭配：「到了」后面接时段或阶段，「难度」不能用「到了」引出时间。"}], "explanations": {"后期": "后期指某一时期的后一阶段，「到了后期」符合语境，学习变难。", "早餐": "语义：早餐是一顿饭的时段，不能指学习的阶段。", "晚餐": "语义：晚餐同样是一顿饭，与学习的阶段无关。", "难度": "搭配：「到了」后面接时段或阶段，「难度」不能用「到了」引出时间。"}, "sentence_index": 6, "correct_answer": "后期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜做了后期，味道更好了。", "explanation": "这里的「后期」是影视、摄影的后期制作义项，菜肴不说做后期；本题要的是某一时期的后一阶段。"}, {"text": "这个路口的后期经常堵车。", "explanation": "这里的「后期」指时间阶段，不指路口的某一段；路口靠后的部分应说〈后面〉或〈尽头〉。"}, {"text": "他是我们公司的后期。", "explanation": "这里应该用〈后来的人〉。后期只指时间阶段，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说进入了一条后期，节奏明显变快了。", "corrected_sentence": "这部小说进入了后期，节奏明显变快了。", "error_description": "量词错误：「后期」是时间阶段，不能用「条」（「条」用于细长的东西）。应去掉量词，或改用「段」，说「进入了一段后期」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛进入了很后期，大家都很紧张。", "corrected_sentence": "这场比赛进入了后期，大家都很紧张。", "error_description": "程度词错误：「后期」是时间阶段名词，不能用「很」修饰，应去掉「很」，说「进入了后期」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
