INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "深深地爱；对人或事物怀有强烈感情。", "primary_collocate": null, "pronunciation": "rè ài", "ipa": "ʐɤ˥˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "他热爱自己的祖国，愿意为国家工作。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师热爱学生，也热爱自己的工作。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都热爱这片土地，因为这是家乡。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生热爱自己的工作，常常忙到半夜。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生热爱人民，帮助过很多穷人。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热爱大自然，常常一个人去山里走。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷热爱这个家，把一生都给了家人。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热爱生活，所以每天都过得很开心。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人热爱孩子，村里的人都喜欢他。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士热爱和平，希望世界上不再有战争。", "target_word": "热爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热爱着", "label": "体标"}, {"form": "热爱过", "label": "体标"}, {"form": "熱愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热爱：对祖国、人民、工作、生活怀有深厚强烈的感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热爱", "is_correct": true, "explanation": "热爱：深深地爱，与“愿意为国家工作”的情感一致。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”表示非常讨厌，与“愿意为国家工作”相矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "搭配：“反对”针对做法或决定，不说反对祖国。"}, {"text": "背叛", "is_correct": false, "explanation": "语义：“背叛”指背离、出卖，与“愿意为国家工作”相矛盾。"}], "explanations": {"热爱": "热爱：深深地爱，与“愿意为国家工作”的情感一致。", "厌恶": "语义：“厌恶”表示非常讨厌，与“愿意为国家工作”相矛盾。", "反对": "搭配：“反对”针对做法或决定，不说反对祖国。", "背叛": "语义：“背叛”指背离、出卖，与“愿意为国家工作”相矛盾。"}, "sentence_index": 0, "correct_answer": "热爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈热爱这双新鞋，每天都穿。", "explanation": "这里应该用〈喜欢〉。热爱指深厚强烈的感情，多用于人、国家、事业，不用于一双鞋这类小物件。"}, {"text": "学校很热爱学生的成绩。", "explanation": "这里应该用〈重视〉。热爱的对象多是人、事业或理想，学生的成绩是要重视的事项，不说热爱。"}, {"text": "我很热爱宝贵的时间。", "explanation": "这里应该用〈珍惜〉。珍惜指爱护、不浪费时间，热爱只用于对人或事业的深厚感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热爱", "is_correct": true, "explanation": "热爱：深深地爱，与“把一生都给了家人”的深厚感情相符。"}, {"text": "厌倦", "is_correct": false, "explanation": "语义：“厌倦”表示不想再继续，与“把一生都给了家人”相矛盾。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指丢下不管，与“把一生都给了家人”相矛盾。"}, {"text": "崇拜", "is_correct": false, "explanation": "搭配：“崇拜”多用于人物或理想，不说崇拜这个家。"}], "explanations": {"热爱": "热爱：深深地爱，与“把一生都给了家人”的深厚感情相符。", "厌倦": "语义：“厌倦”表示不想再继续，与“把一生都给了家人”相矛盾。", "抛弃": "语义：“抛弃”指丢下不管，与“把一生都给了家人”相矛盾。", "崇拜": "搭配：“崇拜”多用于人物或理想，不说崇拜这个家。"}, "sentence_index": 6, "correct_answer": "热爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我热爱这场感冒。", "explanation": "这里应该用〈讨厌〉。热爱是深深喜爱，感冒令人难受，对它应表示厌恶。"}, {"text": "他热爱去年的那场洪水。", "explanation": "这里应该用〈痛恨〉。热爱是深深喜爱，洪水是灾害，人们对它应表示痛恨，而不是热爱。"}, {"text": "妈妈热爱这台坏掉的洗衣机。", "explanation": "这里应该用〈讨厌〉。热爱是深深喜爱，坏掉的家电令人烦恼，对它应表示厌烦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
