INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "直升机是一种飞机，头上有大风扇，能直直地飞上天。", "primary_collocate": null, "pronunciation": "zhí shēng jī", "ipa": "tʂʅ³⁵ ʂɤŋ⁵⁵ tɕi⁵⁵", "syllable_count": 3, "sentences": [{"text": "天上有一架直升机。", "target_word": "直升机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "直升机飞得很低。", "target_word": "直升机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们抬头看那架直升机。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机停在学校的操场上。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次坐直升机，有点儿害怕。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机不用跑道，就能飞上天。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥想学开直升机。", "target_word": "直升机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的雪很大，直升机飞不过去。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听，直升机的声音越来越大了。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我在公园看见了一架红色的直升机。", "target_word": "直升机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "武装直升机", "label": "复合"}], "register": "中性", "sense_fingerprint": "头上有大风扇、能直接飞上天的飞机（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：直升机的量词是“架”，“天上有一架直升机”自然。"}, {"text": "气球", "is_correct": false, "explanation": "搭配：气球的量词是“个”或“只”，不能说“一架气球”。"}, {"text": "云", "is_correct": false, "explanation": "搭配：云的量词是“朵”或“片”，不能说“一架云”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是飞行器，“天上有一架太阳”不通。"}], "explanations": {"直升机": "正确：直升机的量词是“架”，“天上有一架直升机”自然。", "气球": "搭配：气球的量词是“个”或“只”，不能说“一架气球”。", "云": "搭配：云的量词是“朵”或“片”，不能说“一架云”。", "太阳": "语义：太阳是天体，不是飞行器，“天上有一架太阳”不通。"}, "sentence_index": 0, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "直升机在跑道上滑行一段，才慢慢离开地面。", "explanation": "这里应该用〈飞机〉。直升机靠旋翼垂直起飞，不需要在跑道上滑行。"}, {"text": "直升机靠加热的空气升到天上。", "explanation": "这里应该用〈热气球〉。直升机靠旋翼升空，不靠加热空气的浮力。"}, {"text": "救援队开着直升机沿着铁轨慢慢开进了车站。", "explanation": "这里应该用〈火车〉。直升机在空中飞，不沿铁轨行驶，“沿铁轨开进车站”是火车的行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：“开”可以搭配直升机，“哥哥想学开直升机”自然。"}, {"text": "风筝", "is_correct": false, "explanation": "搭配：风筝要说“放”，不说“开”，“学开风筝”不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴要说“弹”，不说“开”，“学开钢琴”不通。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是建筑，不是可以被“开”去学的东西，不通。"}], "explanations": {"直升机": "正确：“开”可以搭配直升机，“哥哥想学开直升机”自然。", "风筝": "搭配：风筝要说“放”，不说“开”，“学开风筝”不通。", "钢琴": "搭配：钢琴要说“弹”，不说“开”，“学开钢琴”不通。", "大楼": "语义：大楼是建筑，不是可以被“开”去学的东西，不通。"}, "sentence_index": 6, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "直升机在马路上行驶，司机小心地踩刹车。", "explanation": "这里应该用〈汽车〉。“行驶”和“踩刹车”是地面车辆的动作，直升机在空中飞。"}, {"text": "直升机鸣着汽笛，缓缓驶出港口。", "explanation": "这里应该用〈轮船〉。“驶出港口”是船只的行动，直升机不在港口里驶出。"}, {"text": "直升机点燃尾部的火药，嗖地一下冲向太空。", "explanation": "这里应该用〈火箭〉。直升机靠旋翼升空，不靠火药喷射，“冲向太空”是火箭的飞行方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直升机直直地上飞天，很快就不见了。", "corrected_sentence": "直升机直直地飞上天，很快就不见了。", "error_description": "错误形式：“上飞天”。正确形式：“飞上天”。趋向补语“上”要紧跟动词“飞”，宾语“天”放在后面，不能把“上”放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家楼下停过一辆直升机。", "corrected_sentence": "我家楼下停过一架直升机。", "error_description": "错误形式：“一辆直升机”。正确形式：“一架直升机”。直升机的量词是“架”，“辆”只用于有轮子的车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
