INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠头顶旋转的旋翼产生升力，能垂直起降的飞行器。", "primary_collocate": null, "pronunciation": "zhí shēng jī", "ipa": "tʂʅ³⁵ ʂɤŋ⁵⁵ tɕi⁵⁵", "syllable_count": 3, "sentences": [{"text": "直升机靠头顶的旋翼产生升力。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机可以在空中停住不动。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生坐直升机赶到了山里。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机能在很小的地方起飞和降落。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防队用直升机把水运到山上灭火。", "target_word": "直升机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机不需要长长的跑道。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水太大，救援队开着直升机去救人。", "target_word": "直升机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机的旋翼转得很快，声音很大。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架直升机最多能坐六个人。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里没有路，只能用直升机运东西。", "target_word": "直升机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "武装直升机", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠旋翼产生升力、能垂直起降和空中悬停的飞行器（技术说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：直升机靠头顶的旋翼产生升力，与句中描述相合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机靠机翼产生升力，不靠旋翼，“飞机靠头顶的旋翼”不符合事实。"}, {"text": "气球", "is_correct": false, "explanation": "语义：气球靠浮力升空，不靠旋翼产生升力。"}, {"text": "滑翔机", "is_correct": false, "explanation": "搭配：“旋翼”是直升机的部件，滑翔机搭配的是机翼，不说“靠旋翼”。"}], "explanations": {"直升机": "正确：直升机靠头顶的旋翼产生升力，与句中描述相合。", "飞机": "语义：飞机靠机翼产生升力，不靠旋翼，“飞机靠头顶的旋翼”不符合事实。", "气球": "语义：气球靠浮力升空，不靠旋翼产生升力。", "滑翔机": "搭配：“旋翼”是直升机的部件，滑翔机搭配的是机翼，不说“靠旋翼”。"}, "sentence_index": 0, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "直升机的机翼很长，能借助气流飞得很远。", "explanation": "这里应该用〈飞机〉。直升机靠头顶的旋翼产生升力，不说“机翼”。"}, {"text": "直升机靠加热的空气产生浮力，慢慢升起。", "explanation": "这里应该用〈热气球〉。直升机靠旋翼产生升力，不靠浮力。"}, {"text": "救援队开着直升机驶进港口，准备出海救人。", "explanation": "这里应该用〈轮船〉。“驶进港口”是船只的行动，直升机在空中飞，不说“驶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直升机", "is_correct": true, "explanation": "正确：救援队开着直升机去救人，与“河水太大”的情境相合。"}, {"text": "大桥", "is_correct": false, "explanation": "语义：大桥是建筑，不是交通工具，不能“开着”去救人。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不能作交通工具，“开着书包”不搭配。"}, {"text": "稻田", "is_correct": false, "explanation": "语义：稻田是农田，不是交通工具，不能“开着”去救人。"}], "explanations": {"直升机": "正确：救援队开着直升机去救人，与“河水太大”的情境相合。", "大桥": "语义：大桥是建筑，不是交通工具，不能“开着”去救人。", "书包": "搭配：“书包”不能作交通工具，“开着书包”不搭配。", "稻田": "语义：稻田是农田，不是交通工具，不能“开着”去救人。"}, "sentence_index": 6, "correct_answer": "直升机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "直升机在坑坑洼洼的山路上颠簸前进。", "explanation": "这里应该用〈卡车〉。“颠簸”和“山路”是地面车辆的情境，直升机是在空中飞。"}, {"text": "直升机在湖面上慢慢划着，船夫唱着歌。", "explanation": "这里应该用〈小船〉。“划”是用桨推动船只前进，直升机不用桨划行。"}, {"text": "直升机在铁轨上飞快地跑，汽笛响个不停。", "explanation": "这里应该用〈火车〉。直升机在空中飞，不在铁轨上跑，“汽笛”是火车的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直升机在空中停的很稳，不会晃来晃去。", "corrected_sentence": "直升机在空中停得很稳，不会晃来晃去。", "error_description": "错误形式：“停的很稳”。正确形式：“停得很稳”。动词与补语之间用“得”连接，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次救援用了一辆直升机，很快找到了人。", "corrected_sentence": "这次救援用了一架直升机，很快找到了人。", "error_description": "错误形式：“一辆直升机”。正确形式：“一架直升机”。直升机的量词是“架”，“辆”只用于有轮子的车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
