INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "糖是甜甜的东西，小朋友都爱吃。", "primary_collocate": null, "pronunciation": "táng", "ipa": "tʰɑŋ³⁵", "syllable_count": 1, "sentences": [{"text": "小朋友都爱吃糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给弟弟买了一块糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口袋里有很多糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿吃了太多糖，牙疼了。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个孩子发了一颗糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种糖是水果味的。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把糖放进了嘴里。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着要糖吃。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们家里有很多糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的包里总是有一颗糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "糖果", "label": "复合"}, {"form": "颗", "label": "量词"}, {"form": "块", "label": "量词"}], "register": "口语", "sense_fingerprint": "孩子爱吃的一颗颗甜甜的糖果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95b88d0-503e-4f90-8d29-19af13d4f162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93807, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糖", "is_correct": true, "explanation": "糖（táng）指糖果，是孩子爱吃的甜食。"}, {"text": "汤", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。"}, {"text": "趟", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，意思是一趟（量词）。"}, {"text": "痰", "is_correct": false, "explanation": "tán 与 táng 韵母不同（an 与 ang），意思是痰。"}], "explanations": {"糖": "糖（táng）指糖果，是孩子爱吃的甜食。", "汤": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。", "躺": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。", "趟": "tàng（第四声）与 táng（第二声）声调不同，意思是一趟（量词）。", "痰": "tán 与 táng 韵母不同（an 与 ang），意思是痰。"}, "sentence_index": null, "correct_answer": "糖"}, "level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正确。糖果是孩子都爱吃的甜食，符合语境。"}, {"text": "肥皂", "is_correct": false, "explanation": "搭配：“吃”的宾语应是可以食用的东西，肥皂不能吃。"}, {"text": "药", "is_correct": false, "explanation": "语义：小朋友大多不爱吃药，与“都爱吃”的语境相反。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“吃”不能带钢笔这样的非食物做宾语。"}], "explanations": {"糖": "正确。糖果是孩子都爱吃的甜食，符合语境。", "肥皂": "搭配：“吃”的宾语应是可以食用的东西，肥皂不能吃。", "药": "语义：小朋友大多不爱吃药，与“都爱吃”的语境相反。", "钢笔": "搭配：“吃”不能带钢笔这样的非食物做宾语。"}, "sentence_index": 0, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给弟弟买了一件糖。", "explanation": "这里应该用〈颗〉或〈块〉。〈件〉用于衣物、事情等，糖果不能用〈件〉计量。"}, {"text": "小朋友都爱喝糖。", "explanation": "这里应该用〈饮料〉。“喝”用于饮料、汤水，糖果是固体，不能说“喝糖”。"}, {"text": "他口袋里有一只糖。", "explanation": "这里应该用〈颗〉。〈只〉用于动物或成对器物中的一个，糖果不能用〈只〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93807, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "糖", "is_correct": true, "explanation": "糖（táng）指糖果，是孩子爱吃的甜食。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 táng 韵母不同（eng 与 ang），意思是疼痛。"}, {"text": "烫", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，意思是热、烫。"}, {"text": "腾", "is_correct": false, "explanation": "téng 与 táng 韵母不同（eng 与 ang），意思是腾跃、腾出。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 táng 韵母不同（an 与 ang），意思是谈话。"}], "explanations": {"糖": "糖（táng）指糖果，是孩子爱吃的甜食。", "疼": "téng 与 táng 韵母不同（eng 与 ang），意思是疼痛。", "烫": "tàng（第四声）与 táng（第二声）声调不同，意思是热、烫。", "腾": "téng 与 táng 韵母不同（eng 与 ang），意思是腾跃、腾出。", "谈": "tán 与 táng 韵母不同（an 与 ang），意思是谈话。"}, "sentence_index": null, "correct_answer": "糖"}, "level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正确。糖果可以放进嘴里，符合语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书太大，不能放进嘴里。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能放进嘴里，与“放进嘴里”的动作冲突。"}, {"text": "袜子", "is_correct": false, "explanation": "搭配：“放进嘴里”的东西应是小而可入口的食物或糖类，袜子不能这样放。"}], "explanations": {"糖": "正确。糖果可以放进嘴里，符合语境。", "书": "语义：书太大，不能放进嘴里。", "手机": "语义：手机不能放进嘴里，与“放进嘴里”的动作冲突。", "袜子": "搭配：“放进嘴里”的东西应是小而可入口的食物或糖类，袜子不能这样放。"}, "sentence_index": 6, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶的包里总是有一条糖。", "explanation": "这里应该用〈颗〉或〈块〉。〈条〉用于细长的东西，糖果不能用〈条〉计量。"}, {"text": "奶奶的包里总是有一匹糖。", "explanation": "这里应该用〈颗〉。〈匹〉用于马、布等，糖果不能用〈匹〉计量。"}, {"text": "奶奶的包里总是有一座糖。", "explanation": "这里应该用〈颗〉。〈座〉用于山、桥、建筑等大型物体，糖果不能用〈座〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
