INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有甜味的食品，主要成分是蔗糖等。", "primary_collocate": null, "pronunciation": "táng", "ipa": "tʰɑŋ³⁵", "syllable_count": 1, "sentences": [{"text": "我喝茶的时候喜欢放一点糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕里放了太多糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一袋糖，准备做蛋糕。", "target_word": "糖", "complexity_tier": "T3", "furigana": "mā ma mǎi le yí dài táng, zhǔnbèi zuò dàngāo.", "sentence_source": "generated"}, {"text": "做红烧肉要放糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他不能吃太多糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡里的糖还没有化开。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖放在厨房的柜子里。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一勺糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮粥的时候加了一点糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯牛奶里放了一勺糖。", "target_word": "糖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "白糖", "label": "复合"}, {"form": "勺", "label": "量词"}, {"form": "袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "做饭泡茶时用的有甜味的糖类调味品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95b88d0-503e-4f90-8d29-19af13d4f162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糖", "is_correct": true, "explanation": "糖（táng）指有甜味的食品，即做饭、泡茶时用的调味糖。"}, {"text": "汤", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。"}, {"text": "烫", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，意思是热、烫。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 táng 韵母不同（an 与 ang），意思是谈话。"}], "explanations": {"糖": "糖（táng）指有甜味的食品，即做饭、泡茶时用的调味糖。", "汤": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。", "躺": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。", "烫": "tàng（第四声）与 táng（第二声）声调不同，意思是热、烫。", "谈": "tán 与 táng 韵母不同（an 与 ang），意思是谈话。"}, "sentence_index": null, "correct_answer": "糖"}, "level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正确。糖是甜味的调味料，喝茶时放一点糖符合语境。"}, {"text": "酱油", "is_correct": false, "explanation": "语义：茶里不会放酱油，与“喝茶”的语境冲突。"}, {"text": "杯子", "is_correct": false, "explanation": "搭配：“一点”修饰的是可以少量放入的物料，不能说“放一点杯子”。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不能溶解于茶水中，与“放一点”加甜味的语境不符。"}], "explanations": {"糖": "正确。糖是甜味的调味料，喝茶时放一点糖符合语境。", "酱油": "语义：茶里不会放酱油，与“喝茶”的语境冲突。", "杯子": "搭配：“一点”修饰的是可以少量放入的物料，不能说“放一点杯子”。", "面粉": "语义：面粉不能溶解于茶水中，与“放一点”加甜味的语境不符。"}, "sentence_index": 0, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只糖，准备做蛋糕。", "explanation": "这里应该用〈袋〉或〈勺〉。〈只〉用于动物和成对器物中的一个，糖不用〈只〉计量。"}, {"text": "请给我一根糖，我要放进咖啡里。", "explanation": "这里应该用〈勺〉。〈根〉用于细长条状的东西，颗粒状的糖不能用〈根〉计量。"}, {"text": "妈妈用糖把手洗干净了。", "explanation": "这里应该用〈肥皂〉。糖是调味用的食品，不能用来洗手，洗手要用〈肥皂〉或〈洗手液〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93808, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "糖", "is_correct": true, "explanation": "糖（táng）指有甜味的食品，即做饭、泡茶时用的调味糖。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 táng 韵母不同（eng 与 ang），意思是疼痛。"}, {"text": "趟", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，意思是一趟（量词）。"}, {"text": "腾", "is_correct": false, "explanation": "téng 与 táng 韵母不同（eng 与 ang），意思是腾跃、腾出。"}, {"text": "痰", "is_correct": false, "explanation": "tán 与 táng 韵母不同（an 与 ang），意思是痰。"}], "explanations": {"糖": "糖（táng）指有甜味的食品，即做饭、泡茶时用的调味糖。", "疼": "téng 与 táng 韵母不同（eng 与 ang），意思是疼痛。", "趟": "tàng（第四声）与 táng（第二声）声调不同，意思是一趟（量词）。", "腾": "téng 与 táng 韵母不同（eng 与 ang），意思是腾跃、腾出。", "痰": "tán 与 táng 韵母不同（an 与 ang），意思是痰。"}, "sentence_index": null, "correct_answer": "糖"}, "level_3": {"options": [{"text": "糖", "is_correct": true, "explanation": "正确。糖放在厨房柜子里是正常的说法，符合语境。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体积太大，放不进柜子里，与“放在厨房的柜子里”的语境冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能放进厨房的柜子里，与存放的语境不符。"}, {"text": "沙发", "is_correct": false, "explanation": "体貌：沙发体积太大，放不进厨房的柜子里。"}], "explanations": {"糖": "正确。糖放在厨房柜子里是正常的说法，符合语境。", "大象": "语义：大象体积太大，放不进柜子里，与“放在厨房的柜子里”的语境冲突。", "汽车": "语义：汽车是交通工具，不能放进厨房的柜子里，与存放的语境不符。", "沙发": "体貌：沙发体积太大，放不进厨房的柜子里。"}, "sentence_index": 6, "correct_answer": "糖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我冲牛奶时，总是放一条糖。", "explanation": "这里应该用〈勺〉或〈袋〉。〈条〉用于细长的东西，粉状的糖不能用〈条〉计量。"}, {"text": "这杯咖啡里我加了一台糖。", "explanation": "这里应该用〈勺〉。〈台〉用于机器、电器，糖不能用〈台〉计量。"}, {"text": "我把一张糖放进了牛奶里。", "explanation": "这里应该用〈勺〉或〈块〉。〈张〉用于纸、桌子等扁平的东西，糖不能用〈张〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天煮粥加了一只糖。", "corrected_sentence": "我今天煮粥加了一勺糖。", "error_description": "错误在量词：“糖”应用“勺”计量，说“一只糖”是错的。“只”用于动物或成对器物中的一个，不能用于颗粒状的糖。应说“一勺糖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给咖啡加了两根糖。", "corrected_sentence": "他给咖啡加了两勺糖。", "error_description": "错误在量词：调味用的糖应用“勺”计量，“根”用于细长条状的东西，不能说“两根糖”。应说“两勺糖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
