INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93813, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "维修是东西坏了，把它修好。", "primary_collocate": null, "pronunciation": "wéi xiū", "ipa": "weɪ˧˥ ɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "我的手机坏了，要拿去维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机坏了，师傅明天来维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会维修自行车。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视昨天维修好了。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我维修一下这把椅子。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，我们要找人维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在维修厨房的灯。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑维修过两次。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表掉在地上，师傅说可以维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱不冷了，得马上维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "维修了", "label": "体标"}, {"form": "维修过", "label": "体标"}, {"form": "维修费", "label": "复合"}, {"form": "維修", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西坏了以后把它修好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b15c9f-8226-4dee-a7e1-d0e9710ecd9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维修", "is_correct": true, "explanation": "正确。手机坏了，要拿去维修，即修理坏了的东西。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”搭配的是场所或环境，不搭配“手机”，也不是修理。"}, {"text": "购买", "is_correct": false, "explanation": "语义：手机已经坏了，“购买”是买新的，与修好它的语境不合。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指用乐器表演，手机不能被演奏，句子不成立。"}], "explanations": {"维修": "正确。手机坏了，要拿去维修，即修理坏了的东西。", "打扫": "搭配：“打扫”搭配的是场所或环境，不搭配“手机”，也不是修理。", "购买": "语义：手机已经坏了，“购买”是买新的，与修好它的语境不合。", "演奏": "语义：“演奏”指用乐器表演，手机不能被演奏，句子不成立。"}, "sentence_index": 0, "correct_answer": "维修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这篇论文维修了三遍。", "explanation": "这里应该用〈修改〉。“维修”指修好坏了的机器或设施，论文不能维修，要说修改。"}, {"text": "我们要维修教学方法。", "explanation": "这里应该用〈改进〉。“维修”只用于修好坏了的机器或设施，教学方法没有坏，要说改进。"}, {"text": "我们每天维修这个网站的内容。", "explanation": "这里应该用〈更新〉。网站内容需要更新，不是修好坏了的东西，不能说维修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维修", "is_correct": true, "explanation": "正确。爸爸正在修理厨房的灯，“维修”指修理。"}, {"text": "浇", "is_correct": false, "explanation": "配价：“浇”要求的宾语是植物或液体，“灯”不能作“浇”的宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与修理厨房的灯无关。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”指折叠，灯不能被叠，句子说不通。"}], "explanations": {"维修": "正确。爸爸正在修理厨房的灯，“维修”指修理。", "浇": "配价：“浇”要求的宾语是植物或液体，“灯”不能作“浇”的宾语。", "唱": "语义：“唱”指发出歌声，与修理厨房的灯无关。", "叠": "语义：“叠”指折叠，灯不能被叠，句子说不通。"}, "sentence_index": 6, "correct_answer": "维修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想维修我的妹妹。", "explanation": "这里应该用〈照顾〉。“维修”的对象是机器、设施等物品，不能用来指人。"}, {"text": "老师要求我们维修学习态度。", "explanation": "这里应该用〈改正〉。“维修”只用于有形的机器或设施，学习态度是抽象的，要说改正。"}, {"text": "他每天都要维修自己的口语。", "explanation": "这里应该用〈练习〉。“维修”用于让坏了的东西恢复正常，口语是技能，要说练习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把洗衣机维修。", "corrected_sentence": "工人把洗衣机维修好了。", "error_description": "把字句缺少补语：“把”字句中动词后要有结果补语或其他成分，应说“维修好了”，不能只说“维修”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在维修过客厅的灯。", "corrected_sentence": "妈妈正在维修客厅的灯。", "error_description": "时体标记冲突：“正在”表示动作进行，不能与表示完成经历的“过”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
