INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "舔是用舌头碰一碰东西。", "primary_collocate": null, "pronunciation": "tiǎn", "ipa": "tʰjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "小孩好奇地舔了一下糖果。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尝尝，舔一舔就知道是咸的。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗狗高兴地舔我的脸。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他舔了舔勺子，觉得味道很甜。", "target_word": "舔", "complexity_tier": "T3", "furigana": "tā tiǎn le tiǎn sháozi, juéde wèidao hěn tián.", "sentence_source": "generated"}, {"text": "那个盘子，小猫舔得干干净净。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩舔着棒棒糖走进了商店。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别舔墙上的东西，很脏。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我舔过这块盐，真的很咸。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎舔舔爪子，又睡着了。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他舔了舔手指，翻开下一页书。", "target_word": "舔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "舔了", "label": "体标"}, {"form": "舔着", "label": "体标"}, {"form": "舔过", "label": "体标"}, {"form": "舔舔", "label": "重叠"}, {"form": "舔一舔", "label": "重叠"}], "register": "口语", "sense_fingerprint": "动词：用舌头轻轻碰一碰东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '156c6536-9aaa-4682-9ec7-bdb78ccbc235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舔", "is_correct": true, "explanation": "舔（tiǎn，第三声）：用舌头轻轻碰一碰东西，是本题的目标词。"}, {"text": "天", "is_correct": false, "explanation": "tiān（第一声）与 tiǎn 声调不同，意思是天空。"}, {"text": "甜", "is_correct": false, "explanation": "tián（第二声）与 tiǎn 声调不同，意思是甜。"}, {"text": "点", "is_correct": false, "explanation": "diǎn 与 tiǎn 声母不同（d 与 t），意思是点。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn 与 tiǎn 声母不同（l 与 t），意思是脸。"}], "explanations": {"舔": "舔（tiǎn，第三声）：用舌头轻轻碰一碰东西，是本题的目标词。", "天": "tiān（第一声）与 tiǎn 声调不同，意思是天空。", "甜": "tián（第二声）与 tiǎn 声调不同，意思是甜。", "点": "diǎn 与 tiǎn 声母不同（d 与 t），意思是点。", "脸": "liǎn 与 tiǎn 声母不同（l 与 t），意思是脸。"}, "sentence_index": null, "correct_answer": "舔"}, "level_3": {"options": [{"text": "舔", "is_correct": true, "explanation": "空格处应填“舔”，表示小孩轻轻碰一下糖果，是本句的原词。"}, {"text": "挤", "is_correct": false, "explanation": "语义：挤是按压，与“轻轻碰一下”的动作不符。"}, {"text": "咽", "is_correct": false, "explanation": "语义：咽是吞下，句中只是“好奇地轻碰”，并没有吞咽。"}, {"text": "压", "is_correct": false, "explanation": "语义：压是用力按，与“好奇地轻碰”的动作不符。"}], "explanations": {"舔": "空格处应填“舔”，表示小孩轻轻碰一下糖果，是本句的原词。", "挤": "语义：挤是按压，与“轻轻碰一下”的动作不符。", "咽": "语义：咽是吞下，句中只是“好奇地轻碰”，并没有吞咽。", "压": "语义：压是用力按，与“好奇地轻碰”的动作不符。"}, "sentence_index": 0, "correct_answer": "舔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用湿布舔了一下窗台，把灰尘擦掉了。", "explanation": "这里应该用“擦”。“舔”只表示用舌头碰一碰东西，用湿布擦窗台要说“擦”，不能说“舔”。"}, {"text": "他用筷子舔了一下汤，觉得很烫。", "explanation": "这里“舔”被误当成了“尝”的意思，应该用“尝”。“舔”要用舌头碰一碰，用筷子尝汤要说“尝”，不能说“舔”。"}, {"text": "他舔了舔这个问题，想了很久。", "explanation": "这里“舔”被误当成了“琢磨、思考”的意思，应该用“琢磨”。“舔”只表示用舌头碰一碰东西，不能用于思考问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93817, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "舔", "is_correct": true, "explanation": "舔（tiǎn，第三声）：用舌头轻轻碰一碰东西，是本题的目标词。"}, {"text": "田", "is_correct": false, "explanation": "tián（第二声）与 tiǎn 声调不同，意思是田地。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn 与 tiǎn 声母不同（b 与 t），意思是扁平。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn 与 tiǎn 声母不同（x 与 t），意思是显示。"}], "explanations": {"舔": "舔（tiǎn，第三声）：用舌头轻轻碰一碰东西，是本题的目标词。", "田": "tián（第二声）与 tiǎn 声调不同，意思是田地。", "扁": "biǎn 与 tiǎn 声母不同（b 与 t），意思是扁平。", "显": "xiǎn 与 tiǎn 声母不同（x 与 t），意思是显示。"}, "sentence_index": null, "correct_answer": "舔"}, "level_3": {"options": [{"text": "舔", "is_correct": true, "explanation": "空格处应填“舔”，表示用舌头接触墙上的东西，是本句的原词。"}, {"text": "喝", "is_correct": false, "explanation": "语义：墙上的东西是固体，不能用“喝”，与句中的劝阻不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮需要水和加热，与墙上的东西不相合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆是拆开或拆除，与“很脏”这一劝阻理由不搭。"}], "explanations": {"舔": "空格处应填“舔”，表示用舌头接触墙上的东西，是本句的原词。", "喝": "语义：墙上的东西是固体，不能用“喝”，与句中的劝阻不符。", "煮": "语义：煮需要水和加热，与墙上的东西不相合。", "拆": "语义：拆是拆开或拆除，与“很脏”这一劝阻理由不搭。"}, "sentence_index": 6, "correct_answer": "舔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头太硬，他舔了一下，就把它舔碎了。", "explanation": "这里“舔”被误当成了“砸、敲”的意思，应该用“砸”。“舔”只表示用舌头碰一碰，无法把硬物弄碎。"}, {"text": "门很重，她用舔的力气推开了它。", "explanation": "这里“舔”被误当成了“使劲”的意思，应该用“使劲”。“舔”只表示用舌头碰一碰，不能用来形容用力推门。"}, {"text": "那台电脑舔了一下键盘，把键盘弄坏了。", "explanation": "这里“舔”被误当成了“敲、按”的意思，应该用“敲”。“舔”要用舌头碰一碰，电脑没有舌头，不能作为动作的主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子舔净干了盘子上的奶油。", "corrected_sentence": "孩子舔干净了盘子上的奶油。", "error_description": "错误：结果补语“干净”的顺序颠倒，说成了“净干”。正确：应说“舔干净”，“干”和“净”是固定组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在舔了一下勺子，才发现汤太咸。", "corrected_sentence": "他舔了一下勺子，才发现汤太咸。", "error_description": "错误：“正在舔了一下”，多加了“正在”。正确：“舔了一下”。“正在”表示动作进行中，与表示已完成的“了一下”矛盾，去掉“正在”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3f168bd-d446-4753-bd13-0a690f582ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
