INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93820, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "召唤大家去做某件事。", "primary_collocate": null, "pronunciation": "hào zhào", "ipa": "xau˥˩ ʈʂau˥˩", "syllable_count": 2, "sentences": [{"text": "老师号召大家一起打扫教室。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长号召了市民少开车，多坐地铁。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校号召同学们给山区的孩子捐书。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府号召大家节约用水。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他号召全班同学参加比赛。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司号召员工每天走一万步。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区号召居民把旧衣服捐出来。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长号召大家爱护校园里的花草。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生号召大家多运动，少吃糖。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们号召年轻人去乡下帮助老人。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "号召了", "label": "体标（了）"}, {"form": "号召过", "label": "体标（过）"}, {"form": "号召力", "label": "复合词"}], "register": "正式", "sense_fingerprint": "号召：公开呼吁、召唤众人去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号召", "is_correct": true, "explanation": "号召指公开呼吁大家一起做某事，符合「老师……大家一起打扫教室」。"}, {"text": "分开", "is_correct": false, "explanation": "语义：「分开」与「一起」意思相反，不能用来指示大家一起行动。"}, {"text": "拆散", "is_correct": false, "explanation": "搭配：「拆散」多接团体或家庭，不说「拆散大家一起打扫教室」。"}, {"text": "怠慢", "is_correct": false, "explanation": "语义：怠慢是冷落、不重视，与老师组织大家劳动不符。"}], "explanations": {"号召": "号召指公开呼吁大家一起做某事，符合「老师……大家一起打扫教室」。", "分开": "语义：「分开」与「一起」意思相反，不能用来指示大家一起行动。", "拆散": "搭配：「拆散」多接团体或家庭，不说「拆散大家一起打扫教室」。", "怠慢": "语义：怠慢是冷落、不重视，与老师组织大家劳动不符。"}, "sentence_index": 0, "correct_answer": "号召"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师号召同学们在课堂上睡觉。", "explanation": "这里应该用〈纵容〉。号召是呼吁大家去做正当的事，不能表示默许睡觉。"}, {"text": "老师号召大家迟到。", "explanation": "这里应该用〈允许〉。号召是呼吁大家去做事，不能用来表示允许迟到。"}, {"text": "天气号召大家节约用水。", "explanation": "语义：「号召」的主语要是能发出呼吁的人或组织，「天气」不能呼吁；这里应该用〈提醒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号召", "is_correct": true, "explanation": "号召指公开呼吁，「社区号召居民把旧衣服捐出来」符合语境。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：「逃避」的宾语须是责任或问题，不能接「居民把旧衣服捐出来」。"}, {"text": "抢夺", "is_correct": false, "explanation": "搭配：「抢夺」的宾语须是财物，不能接「居民把旧衣服捐出来」。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：「驱赶」只接人或动物，不能接「把旧衣服捐出来」这类要求。"}], "explanations": {"号召": "号召指公开呼吁，「社区号召居民把旧衣服捐出来」符合语境。", "逃避": "搭配：「逃避」的宾语须是责任或问题，不能接「居民把旧衣服捐出来」。", "抢夺": "搭配：「抢夺」的宾语须是财物，不能接「居民把旧衣服捐出来」。", "驱赶": "搭配：「驱赶」只接人或动物，不能接「把旧衣服捐出来」这类要求。"}, "sentence_index": 6, "correct_answer": "号召"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察号召了犯罪。", "explanation": "这里应该用〈打击〉。号召是呼吁众人去做事，不能用来表示打击犯罪。"}, {"text": "他们号召年轻人去乡下欺负老人。", "explanation": "这里应该用〈指使〉。号召是呼吁大家去做正当的事，不能表示指使别人欺负老人。"}, {"text": "他们号召年轻人对老人撒谎。", "explanation": "这里应该用〈教唆〉。号召是呼吁大家去做正当的事，不能表示教唆他人撒谎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
