INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设定是事先定好某个样子或某个办法。", "primary_collocate": null, "pronunciation": "shè dìng", "ipa": "ʂɤ˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我把手机的闹钟设定在七点。", "target_word": "设定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把投影仪的分辨率设定好了。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调的温度已经设定好了。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的世界观是谁设定的？", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先设定一个新密码。", "target_word": "设定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给这个角色设定了一段悲惨的过去。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视可以设定自动关机的时间。", "target_word": "设定", "complexity_tier": "T3", "furigana": "diànshì kěyǐ shèdìng zìdòng guānjī de shíjiān.", "sentence_source": "generated"}, {"text": "洗衣机设定好以后，按开始就行。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的人物是作者设定的。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以把语言设定成中文。", "target_word": "设定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设定了", "label": "完成体"}, {"form": "设定过", "label": "经历体"}, {"form": "設定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先定好样子或办法，如设备参数、文艺作品的人物背景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95b88d0-503e-4f90-8d29-19af13d4f162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设定", "is_correct": true, "explanation": "正确。“设定”表示预先确定闹钟的时间，符合语境。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是影音内容，不能说“播放闹钟”。"}, {"text": "删除", "is_correct": false, "explanation": "配价：“删除”不带“在+时间”的补足语，不能说“删除在七点”。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：“关闭”是停止，与“设定时间”的意思相反。"}], "explanations": {"设定": "正确。“设定”表示预先确定闹钟的时间，符合语境。", "播放": "搭配：“播放”的对象是影音内容，不能说“播放闹钟”。", "删除": "配价：“删除”不带“在+时间”的补足语，不能说“删除在七点”。", "关闭": "语义：“关闭”是停止，与“设定时间”的意思相反。"}, "sentence_index": 0, "correct_answer": "设定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥是工程师设定的。", "explanation": "这里应该用〈设计〉。设计用于桥梁、建筑等有形的物体，〈设定〉用于参数、规则和人物背景，不说“设定桥”。"}, {"text": "两国设定了新的外交关系。", "explanation": "这里应该用〈建立〉。建立用于外交关系、制度等，〈设定〉指预先确定参数或办法，不用于外交关系。"}, {"text": "工程师为这台电脑设定了新的内存。", "explanation": "这里应该用〈配置〉。配置指安装和搭配硬件，〈设定〉指设置参数，不说“设定内存”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设定", "is_correct": true, "explanation": "正确。电视可以事先设定关机的时间，符合语境。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是节目，不能说“播放时间”。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是节目等，不能观看时间。"}, {"text": "播出", "is_correct": false, "explanation": "语义：“播出”指节目播送，与设定关机时间的语境无关。"}], "explanations": {"设定": "正确。电视可以事先设定关机的时间，符合语境。", "播放": "搭配：“播放”的对象是节目，不能说“播放时间”。", "观看": "搭配：“观看”的对象是节目等，不能观看时间。", "播出": "语义：“播出”指节目播送，与设定关机时间的语境无关。"}, "sentence_index": 6, "correct_answer": "设定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师设定了我的请假申请。", "explanation": "这里应该用〈批准〉。〈批准〉用于申请、请求，〈设定〉指预先规定参数、规则或办法，不能用于申请。"}, {"text": "妈妈设定了一锅汤，大家都很饿。", "explanation": "这里应该用〈煮〉。〈煮〉用于做汤、粥等食物，〈设定〉指预先规定参数、规则或办法，不能用于做饭。"}, {"text": "他设定了一只小猫，天天养着。", "explanation": "这里应该用〈收养〉。〈收养〉用于领养动物、孩子，〈设定〉指预先确定参数、规则或办法，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把空调的温度设定二十六度。", "corrected_sentence": "我把空调的温度设定在二十六度。", "error_description": "缺少介词：“设定”后的介词“在”不能省略，应说“设定在二十六度”，不能说“设定二十六度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把照片的尺寸设定了好。", "corrected_sentence": "我已经把照片的尺寸设定好了。", "error_description": "错误在补语与“了”的顺序：“好”是结果补语，应紧跟“设定”，“了”放在句末，说“设定好了”，不能说“设定了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
