INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93827, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "种类或方面很多。", "primary_collocate": null, "pronunciation": "zhū duō", "ipa": "ʈʂu˥ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "这次旅行有诸多不便。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手开车会遇到诸多问题。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事有诸多困难。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中学到了诸多经验。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市生活有诸多好处。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划还有诸多地方要改。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，身体有诸多毛病。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们提出了诸多建议。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为诸多原因，比赛推迟了。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的菜式诸多，各具特色。", "target_word": "诸多", "complexity_tier": "T3", "furigana": "zhè jiā cān tīng de cài shì zhū duō gè jù tè sè", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "诸多：修饰名词，表示种类、方面很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美好", "is_correct": false, "explanation": "搭配：“美好”多修饰事物的好处或前景，不能修饰“不便”。"}, {"text": "诸多", "is_correct": true, "explanation": "“诸多”表示很多，修饰“不便”，与“有诸多不便”的说法相符。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容心情高兴，与“不便”的意思相反，无法修饰“不便”。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描写外貌，不能用来修饰“不便”。"}], "explanations": {"美好": "搭配：“美好”多修饰事物的好处或前景，不能修饰“不便”。", "诸多": "“诸多”表示很多，修饰“不便”，与“有诸多不便”的说法相符。", "愉快": "语义：“愉快”形容心情高兴，与“不便”的意思相反，无法修饰“不便”。", "漂亮": "体貌：“漂亮”描写外貌，不能用来修饰“不便”。"}, "sentence_index": 0, "correct_answer": "诸多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的诸多哥哥，却只有他一个。", "explanation": "这里应该用〈唯一〉。「诸多」表示很多，与「只有他一个」的限定矛盾。"}, {"text": "这个仓库只有诸多钥匙。", "explanation": "这里应该用〈一把〉。“诸多”表示很多，与“只有”限定的少量矛盾。"}, {"text": "她家里有诸多孩子，却只有她一个。", "explanation": "这里应该用〈唯一〉。「诸多」表示很多，与「只有她一个」的限定矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健康", "is_correct": false, "explanation": "搭配：“健康”表示身体状态良好，与“毛病”意思相反，不能修饰“毛病”。"}, {"text": "诸多", "is_correct": true, "explanation": "“诸多”表示很多，修饰“毛病”，句意通顺。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能用来修饰“毛病”。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容清晰程度，与“毛病”无法搭配，句子意思不通。"}], "explanations": {"健康": "搭配：“健康”表示身体状态良好，与“毛病”意思相反，不能修饰“毛病”。", "诸多": "“诸多”表示很多，修饰“毛病”，句意通顺。", "高大": "体貌：“高大”描写身材，不能用来修饰“毛病”。", "清楚": "语义：“清楚”形容清晰程度，与“毛病”无法搭配，句子意思不通。"}, "sentence_index": 6, "correct_answer": "诸多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅只有诸多名厨。", "explanation": "这里应该用〈一位〉。“诸多”表示很多，与“只有”限定的少量矛盾。"}, {"text": "他的孩子诸多，却只有一个。", "explanation": "这里应该用〈唯一〉。「诸多」表示很多，与「只有一个」的限定矛盾。"}, {"text": "只有诸多同学没交作业。", "explanation": "这里应该用〈个别〉。“诸多”表示很多，与“只有”表示少量的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份计划存在一诸多风险。", "corrected_sentence": "这份计划存在诸多风险。", "error_description": "“诸多”前面不能加数量词“一”，应直接修饰名词。错误形式：一诸多风险；正确形式：诸多风险。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板听取了很诸多意见。", "corrected_sentence": "老板听取了诸多意见。", "error_description": "“诸多”修饰名词时前面不能加程度副词“很”，应直接说“诸多意见”。错误形式：很诸多意见；正确形式：诸多意见。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
