INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "许多；众多。多用于书面语。", "primary_collocate": null, "pronunciation": "zhū duō", "ipa": "ʈʂu˥ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "会议讨论了诸多重要问题。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有诸多名胜古迹。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该产品存在诸多缺点。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小说得到了诸多读者的喜爱。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事涉及诸多方面。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写过诸多著名的作品。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，这个地区出现了诸多变化。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受天气影响，航班出现诸多延误。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究发现，睡眠对健康有诸多好处。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在管理上遇到了诸多挑战。", "target_word": "诸多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "诸多：书面语，许多、众多，多修饰抽象名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edf244f9-0608-45e4-b943-052912734b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”形容天气或温度，不能修饰“重要问题”，句意不通。"}, {"text": "诸多", "is_correct": true, "explanation": "“诸多”表示很多，修饰“重要问题”，与“讨论了诸多重要问题”相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描写外貌，无法修饰“问题”。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”描写温度或触感，不能与“问题”搭配。"}], "explanations": {"炎热": "语义：“炎热”形容天气或温度，不能修饰“重要问题”，句意不通。", "诸多": "“诸多”表示很多，修饰“重要问题”，与“讨论了诸多重要问题”相符。", "漂亮": "体貌：“漂亮”描写外貌，无法修饰“问题”。", "冰凉": "搭配：“冰凉”描写温度或触感，不能与“问题”搭配。"}, "sentence_index": 0, "correct_answer": "诸多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的小说是他诸多的作品，却只有这一部。", "explanation": "这里应该用〈唯一〉。「诸多」表示很多，与「只有这一部」的限定矛盾。"}, {"text": "他的小说有诸多读者，但只有一位喜欢。", "explanation": "这里应该用〈个别〉。“诸多”表示很多，与“只有一位”表示少量的意思矛盾。"}, {"text": "他的小说获得的诸多读者，只有我一个人。", "explanation": "这里应该用〈个别〉。“诸多”表示很多，与“只有我一个人”表示少量的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”靠镜头记录影像，不能与“变化”搭配，句意不通。"}, {"text": "诸多", "is_correct": true, "explanation": "“诸多”表示很多，修饰“变化”，句子通顺。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语应是可买的东西，“变化”不能被购买。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物或故障，不能用于“变化”。"}], "explanations": {"拍摄": "语义：“拍摄”靠镜头记录影像，不能与“变化”搭配，句意不通。", "诸多": "“诸多”表示很多，修饰“变化”，句子通顺。", "购买": "配价：“购买”的宾语应是可买的东西，“变化”不能被购买。", "修理": "搭配：“修理”针对器物或故障，不能用于“变化”。"}, "sentence_index": 6, "correct_answer": "诸多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司在管理上只遇到了诸多挑战。", "explanation": "这里应该用〈个别〉。「诸多」表示很多，与「只」表示少量的意思矛盾。"}, {"text": "公司的诸多挑战，是唯一的。", "explanation": "这里应该用〈唯一〉。“诸多”表示很多，与“唯一的”矛盾。"}, {"text": "公司在管理上遇到的诸多挑战，只有一个。", "explanation": "这里应该用〈个别〉。“诸多”表示很多，与“只有一个”表示少量的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革引起了一诸多争议。", "corrected_sentence": "这次改革引起了诸多争议。", "error_description": "“诸多”前面不能加数量词“一”，应直接修饰名词。错误形式：一诸多争议；正确形式：诸多争议。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市建设中出现了很诸多问题。", "corrected_sentence": "城市建设中出现了诸多问题。", "error_description": "“诸多”修饰名词时前面不能加程度副词“很”，应直接说“诸多问题”。错误形式：很诸多问题；正确形式：诸多问题。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c0cce87-87cf-494d-9230-03fdda719d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
