INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "账户是存放你的钱的地方，记着你有多少钱。", "primary_collocate": null, "pronunciation": "zhàng hù", "ipa": "ʈʂɑŋ⁵¹ xu⁵¹", "syllable_count": 2, "sentences": [{"text": "我在银行开了一个账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的账户里只有一百块钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把钱存到我的账户里。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个月往我的账户打钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了账户的密码，进不去。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个账户上还有很多钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个银行账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看账户里还有多少钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的账户今天没有收到钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给弟弟开了一个新账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "银行账户", "label": "复合"}, {"form": "賬戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "存钱并记录余额的户头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95b88d0-503e-4f90-8d29-19af13d4f162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“开了一个账户”是在银行开设存钱户头，与句意相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是结算单据，与银行开户的语境不符；且账单多用量词“张”，不说“开了一个账单”。"}, {"text": "密码", "is_correct": false, "explanation": "搭配：密码要“设置”，不能用“开”来搭配，“开一个密码”不成立。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐的场所，与在银行办理存钱的情境不符。"}], "explanations": {"账户": "正确。“开了一个账户”是在银行开设存钱户头，与句意相符。", "账单": "语义：“账单”是结算单据，与银行开户的语境不符；且账单多用量词“张”，不说“开了一个账单”。", "密码": "搭配：密码要“设置”，不能用“开”来搭配，“开一个密码”不成立。", "食堂": "语义：食堂是用餐的场所，与在银行办理存钱的情境不符。"}, "sentence_index": 0, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的账户是三百块。", "explanation": "这里应该用〈账单〉。账户是存钱的户头，不能用来表示每月应付的金额；应说“这个月的账单是三百块”。"}, {"text": "我的账户放在抽屉里。", "explanation": "这里应该用〈存折〉。账户是银行里记账的户头，看不见摸不着，放不进抽屉；存折是纸质的，应说“我的存折放在抽屉里”。"}, {"text": "他是这个家的账户。", "explanation": "这里应该用〈户主〉。账户是资金往来的户头，不指人；应说“他是这个家的户主”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“他有两个银行账户”指他在两家银行或两处开设的户头，与句意相符。"}, {"text": "行长", "is_correct": false, "explanation": "语义：“行长”指人，“他有两个银行行长”在逻辑上不成立。"}, {"text": "大厅", "is_correct": false, "explanation": "语义：“大厅”是建筑中的空间，不能说一个人拥有两个银行大厅。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“银行”修饰的是账户、存款一类，不能修饰“工资”，“银行工资”不成立。"}], "explanations": {"账户": "正确。“他有两个银行账户”指他在两家银行或两处开设的户头，与句意相符。", "行长": "语义：“行长”指人，“他有两个银行行长”在逻辑上不成立。", "大厅": "语义：“大厅”是建筑中的空间，不能说一个人拥有两个银行大厅。", "工资": "搭配：“银行”修饰的是账户、存款一类，不能修饰“工资”，“银行工资”不成立。"}, "sentence_index": 6, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给姐姐开了一张账户。", "explanation": "这里应该用〈个〉，而不是〈张〉。“张”多用于纸、卡片等平面物，账户是抽象的户头，量词用“个”。"}, {"text": "他给公司开了一台账户。", "explanation": "这里应该用〈个〉，而不是〈台〉。“台”用于机器、设备，账户是抽象的户头，量词用“个”。"}, {"text": "他在这本账户上写下了每天的心情。", "explanation": "这里应该用〈日记〉。账户是资金往来的户头，不能用来写心情；应说“他在这本日记上写下了每天的心情。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在银行办了一张账户。", "corrected_sentence": "他在银行办了一个账户。", "error_description": "量词错误：账户的量词应为“个”，“张”多用于纸张、卡片。正确说法是“他在银行办了一个账户。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给女儿修了一个新账户。", "corrected_sentence": "妈妈给女儿开了一个新账户。", "error_description": "搭配错误：“修”用于机器、房屋、道路等有形物，不能修账户；“账户”应与“开”搭配，说“开一个账户”。正确说法是“妈妈给女儿开了一个新账户。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
