INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通报是把事情告诉大家，让大家都知道。", "primary_collocate": null, "pronunciation": "tōng bào", "ipa": "tʰʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老师通报了明天考试的时间。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长通报了学校的新规定。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物业通报了停水的时间。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长向大家通报比赛成绩。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这个好消息通报给大家。", "target_word": "通报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司通报了新产品的情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里通报了河水上涨的消息。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理要在会上通报这件事。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上向大家通报过自己的计划。", "target_word": "通报", "complexity_tier": "T3", "furigana": "tā zài huì shàng xiàng dà jiā tōng bào guò zì jǐ de jì huà", "sentence_source": "generated"}, {"text": "厂长通报了这个月的生产情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通报了", "label": "完成体"}, {"form": "通报过", "label": "经历体"}, {"form": "通報", "label": "繁体"}], "register": "正式", "sense_fingerprint": "把事情告诉大家，让大家都知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95b88d0-503e-4f90-8d29-19af13d4f162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，不能与“考试的时间”组合。"}, {"text": "通报", "is_correct": true, "explanation": "正确：通报表示把考试时间告诉大家，符合语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不说修理“时间”。"}, {"text": "研磨", "is_correct": false, "explanation": "搭配：“研磨”针对物料，不能用于“时间”。"}], "explanations": {"吃": "语义：“吃”是进食，不能与“考试的时间”组合。", "通报": "正确：通报表示把考试时间告诉大家，符合语境。", "修理": "搭配：“修理”针对器物，不说修理“时间”。", "研磨": "搭配：“研磨”针对物料，不能用于“时间”。"}, "sentence_index": 0, "correct_answer": "通报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长向大家通报了一匹马。", "explanation": "这里应该用〈骑〉。通报的对象是情况或信息，马不能作为通报的内容，骑马要用“骑”。"}, {"text": "我给朋友通报了一个笑话。", "explanation": "这里应该用〈讲〉。通报是正式传达情况，讲笑话要用“讲”。"}, {"text": "他通报了一首歌。", "explanation": "这里应该用〈唱〉。通报的对象是情况或信息，唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能接“消息”。"}, {"text": "通报", "is_correct": true, "explanation": "正确：通报表示把河水上涨的消息告诉大家，符合语境。"}, {"text": "承受", "is_correct": false, "explanation": "语义：“承受”指承担压力或打击，与传达消息的语境不符。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：“叹息”是不及物动作，后面不能直接接“消息”作宾语。"}], "explanations": {"喝": "搭配：“喝”的对象是饮品，不能接“消息”。", "通报": "正确：通报表示把河水上涨的消息告诉大家，符合语境。", "承受": "语义：“承受”指承担压力或打击，与传达消息的语境不符。", "叹息": "配价：“叹息”是不及物动作，后面不能直接接“消息”作宾语。"}, "sentence_index": 6, "correct_answer": "通报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厂长通报了一篇文章。", "explanation": "这里应该用〈写〉。通报的对象是情况或信息，写文章要用“写”。"}, {"text": "这家商店通报了一本书。", "explanation": "这里应该用〈卖〉。通报不能用于买卖商品，卖书要用“卖”。"}, {"text": "妈妈通报了一碗饭。", "explanation": "这里应该用〈盛〉。通报不能用于饭，盛饭要用“盛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天班长向大家通报了比赛成绩。", "corrected_sentence": "明天班长向大家通报比赛成绩。", "error_description": "“了”误用：“明天”表示将来，动作尚未发生，不能用“了”。应去掉“了”，说“通报比赛成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂长通报了过这个月的生产情况。", "corrected_sentence": "厂长通报过这个月的生产情况。", "error_description": "“了过”重复：“过”已表示经历，不能再加“了”。应去掉“了”，说“通报过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0b6e73a-753a-4d47-a281-95cf70b7c2ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
