INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法上表示动作发生在过去的时态。", "primary_collocate": null, "pronunciation": "guò qù shí", "ipa": "kwo˥˩ tɕʰy˥˩ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "动词的过去时表示动作已经发生。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动词的过去时怎么变？", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语的过去时和现在时不一样。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语法课上，我们学了过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去时的动词常常要变形。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的动词没有过去时的变化。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把句子改成过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不规则动词的过去时最难记。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题考的是过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会过去时以后，我能写更长的句子。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般过去时", "label": "复合"}, {"form": "过去完成时", "label": "复合"}, {"form": "過去時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "语法术语，表示动作发生在过去的时态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b15c9f-8226-4dee-a7e1-d0e9710ecd9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过去时", "is_correct": true, "explanation": "正确。“动词的过去时”指表示动作已经发生的时态。"}, {"text": "现在时", "is_correct": false, "explanation": "语义：“现在时”表示当下，与“动作已经发生”不符。"}, {"text": "将来时", "is_correct": false, "explanation": "语义：“将来时”表示尚未发生的动作，与“已经发生”相反。"}, {"text": "进行时", "is_correct": false, "explanation": "体貌：“进行时”表示动作正在进行，与“已经发生”的完成义不符。"}], "explanations": {"过去时": "正确。“动词的过去时”指表示动作已经发生的时态。", "现在时": "语义：“现在时”表示当下，与“动作已经发生”不符。", "将来时": "语义：“将来时”表示尚未发生的动作，与“已经发生”相反。", "进行时": "体貌：“进行时”表示动作正在进行，与“已经发生”的完成义不符。"}, "sentence_index": 0, "correct_answer": "过去时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子说的是现在的情况，要用过去时。", "explanation": "这里应该用〈现在时〉。说现在的情况要用现在时，过去时只用于过去的事。"}, {"text": "明天的计划，英语要用过去时来说。", "explanation": "这里应该用〈将来时〉。明天的计划还没有发生，要用将来时来说。"}, {"text": "正在做的事情，要用过去时。", "explanation": "这里应该用〈进行时〉。正在做的事用进行时；过去时只表示已经发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过去时", "is_correct": true, "explanation": "正确。“改成过去时”是把句子变成表示过去动作的时态。"}, {"text": "书", "is_correct": false, "explanation": "语义：句子不能改成“书”，二者不是同类。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是实体物件，与句子的语法形式无关。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“改成”后接颜色表示变色，句子不能变成颜色。"}], "explanations": {"过去时": "正确。“改成过去时”是把句子变成表示过去动作的时态。", "书": "语义：句子不能改成“书”，二者不是同类。", "桌子": "语义：“桌子”是实体物件，与句子的语法形式无关。", "红色": "搭配：“改成”后接颜色表示变色，句子不能变成颜色。"}, "sentence_index": 6, "correct_answer": "过去时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书讲的是中国的过去时。", "explanation": "这里应该用〈历史〉。“过去时”是语法术语，指动词的时态，不指历史。讲中国的过去，要说“历史”。"}, {"text": "明天以前做完的事，要用过去时。", "explanation": "这里应该用〈将来完成时〉。明天以前完成的事要用将来完成时，过去时不表示将来的完成。"}, {"text": "经常发生的事，要用过去时。", "explanation": "这里应该用〈一般现在时〉。经常发生的事要用一般现在时，过去时不用于经常性的现在动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只过去时要求动词变形。", "corrected_sentence": "这种过去时要求动词变形。", "error_description": "量词错误：“过去时”是语法术语，应说“这种过去时”；“只”用于动物或成对的东西，不用于时态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于喝完了过去时。", "corrected_sentence": "我们终于学会了过去时。", "error_description": "搭配错误：“喝”的对象是饮品，不能说“喝完了过去时”，应说“学会了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
