INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93839, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选出是从很多个里面挑一个出来。", "primary_collocate": null, "pronunciation": "xuǎn chū", "ipa": "ɕɥan˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他从十个杯子里选出一个红的。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请从四个答案中选出一个。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子从很多玩具里选出了一个小熊。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家从三个人里选出了一位队长。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在一百张照片中选出一张最美的。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能从这些花里选出一朵吗？", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师从全班同学中选出一个代表。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从一排帽子里选出了一顶黑的。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要从五个名字里选出一个。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟从糖果盒里选出了一颗最大的糖。", "target_word": "选出", "complexity_tier": "T3", "furigana": "Dìdi cóng tángguǒ hé lǐ xuǎn chū le yì kē zuì dà de táng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "选出了", "label": "完成体"}, {"form": "选出过", "label": "经历体"}, {"form": "选出来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "从许多选项中只挑出一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93839, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确答案：选出（xuǎn chū），意思是从许多中挑出一个。"}, {"text": "显出", "is_correct": false, "explanation": "xiǎn（第三声）与 xuǎn（第三声）韵母不同（ian 与 uan），意思是显露出来，不是挑选。"}, {"text": "选区", "is_correct": false, "explanation": "第二音节 qū 与 chū 声母不同（q 与 ch），第一音节相同，意思是选举的区域。"}, {"text": "献出", "is_correct": false, "explanation": "xiàn（第四声）与 xuǎn（第三声）韵母和声调都不同，意思是贡献、交出。"}], "explanations": {"选出": "正确答案：选出（xuǎn chū），意思是从许多中挑出一个。", "显出": "xiǎn（第三声）与 xuǎn（第三声）韵母不同（ian 与 uan），意思是显露出来，不是挑选。", "选区": "第二音节 qū 与 chū 声母不同（q 与 ch），第一音节相同，意思是选举的区域。", "献出": "xiàn（第四声）与 xuǎn（第三声）韵母和声调都不同，意思是贡献、交出。"}, "sentence_index": null, "correct_answer": "选出"}, "level_3": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确：“选出”表示从十个杯子中挑出一个，与“一个红的”相呼应。"}, {"text": "倒出", "is_correct": false, "explanation": "语义：“倒出”是把液体或东西倒出来，与“挑出一个红的”的意思不合。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是食物，不能说吃掉一个杯子。"}, {"text": "出现", "is_correct": false, "explanation": "配价：“出现”不能带“一个红的”作宾语，句子读不通。"}], "explanations": {"选出": "正确：“选出”表示从十个杯子中挑出一个，与“一个红的”相呼应。", "倒出": "语义：“倒出”是把液体或东西倒出来，与“挑出一个红的”的意思不合。", "吃掉": "搭配：“吃掉”的宾语应是食物，不能说吃掉一个杯子。", "出现": "配价：“出现”不能带“一个红的”作宾语，句子读不通。"}, "sentence_index": 0, "correct_answer": "选出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面对争论，他选出了沉默。", "explanation": "这里应该用〈选择〉。选出要从一群具体的人或物中挑出，不能用于“沉默”这类抽象的态度。"}, {"text": "老师选出他的答案是对的。", "explanation": "这里应该用〈认定〉。认定是作出判断，选出只能用于从若干对象中挑出，不能用于判断答案对错。"}, {"text": "我选出了去外地读书。", "explanation": "这里应该用〈决定〉。选出用于从一群对象中挑出，不用于决定自己要做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确：“选出”表示从全班同学中挑出一个代表，与“从全班同学中”相呼应。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是迎接，句子读成欢迎一个代表，与“从全班同学中挑选”的意思不合。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“一个代表”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语应是可洗的东西，不能说洗一个代表。"}], "explanations": {"选出": "正确：“选出”表示从全班同学中挑出一个代表，与“从全班同学中”相呼应。", "欢迎": "语义：“欢迎”是迎接，句子读成欢迎一个代表，与“从全班同学中挑选”的意思不合。", "哭": "配价：“哭”是不及物动词，不能带“一个代表”作宾语。", "洗": "搭配：“洗”的宾语应是可洗的东西，不能说洗一个代表。"}, "sentence_index": 6, "correct_answer": "选出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈选出了衣服上的线头。", "explanation": "这里应该用〈挑出〉。挑出线头是常见说法，选出强调从一群对象中挑定，不用于清理衣服上的线头。"}, {"text": "老师选出了这篇作文的分数。", "explanation": "这里应该用〈评定〉。评定是给出评价，选出用于从若干对象中挑出，不能用于给分数。"}, {"text": "医生选出了病人的病情。", "explanation": "这里应该用〈判定〉。判定是下结论，选出不能用于对病情作判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从这些书里选出去了一本。", "corrected_sentence": "他从这些书里选出来了一本。", "error_description": "错误在“选出去”。“选出”后的趋向补语应为“来”，表示把挑中的拿出来；正确为“他从这些书里选出来了一本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹从一盒巧克力里选出着一块最好吃的。", "corrected_sentence": "妹妹从一盒巧克力里选出了一块最好吃的。", "error_description": "错误在“选出着”。“着”表示持续的状态，而“选出”是一次完成的动作，应用“了”；正确为“妹妹从一盒巧克力里选出了一块最好吃的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
