INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "颁布是官方把一条新的规定告诉大家。", "primary_collocate": null, "pronunciation": "bān bù", "ipa": "pan˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "政府颁布了新的交通规定。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校颁布了新的安全规定。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府颁布新规定，禁止在公园里抽烟。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育部今天颁布了新的考试规定。", "target_word": "颁布", "complexity_tier": "T3", "furigana": "jiào yù bù jīn tiān bān bù le xīn de kǎo shì guī dìng.", "sentence_source": "generated"}, {"text": "国家颁布了保护环境的新规定。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定是去年颁布的。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定颁布以后，大家都要遵守。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府颁布过很多保护老人的规定。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里颁布了新的垃圾分类办法。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为什么要颁布这个新规定？", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颁布了", "label": "完成体"}, {"form": "颁布过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "官方向公众正式宣布新规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b15c9f-8226-4dee-a7e1-d0e9710ecd9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁布", "is_correct": true, "explanation": "正确。“颁布”指官方正式公布新规定，与“交通规定”相合。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于道路、房屋，不说“修建规定”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物，与“新的交通规定”不相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃规定”。"}], "explanations": {"颁布": "正确。“颁布”指官方正式公布新规定，与“交通规定”相合。", "修建": "搭配：“修建”用于道路、房屋，不说“修建规定”。", "拆除": "语义：“拆除”指拆掉建筑物，与“新的交通规定”不相合。", "吃": "搭配：“吃”的对象是食物，不能说“吃规定”。"}, "sentence_index": 0, "correct_answer": "颁布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校颁布了毕业证书。", "explanation": "这里应该用〈颁发〉。颁布用于法律、法令、规定，证书、奖状要用颁发。"}, {"text": "公司颁布了招聘启事。", "explanation": "这里应该用〈发布〉。颁布只用于官方发布的法令、规定，公司的启事要用发布。"}, {"text": "老师颁布了考试成绩。", "explanation": "这里应该用〈宣布〉。颁布针对法律法令，考试成绩要用宣布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颁布", "is_correct": true, "explanation": "正确。新规定公布以后，大家都要遵守，符合“颁布”的意思。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：“撤销”是取消，与“大家都要遵守”相反。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火、灯，不用于规定。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉，规定被删除后不再需要遵守，与句意冲突。"}], "explanations": {"颁布": "正确。新规定公布以后，大家都要遵守，符合“颁布”的意思。", "撤销": "语义：“撤销”是取消，与“大家都要遵守”相反。", "熄灭": "搭配：“熄灭”用于火、灯，不用于规定。", "删除": "语义：“删除”是去掉，规定被删除后不再需要遵守，与句意冲突。"}, "sentence_index": 6, "correct_answer": "颁布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导颁布了开会的时间。", "explanation": "这里应该用〈通知〉。开会时间是告诉大家的事，颁布只用于法律、法令等规定。"}, {"text": "招生办颁布了录取名单。", "explanation": "这里应该用〈公布〉。录取名单是公开告知的信息，颁布只用于法律、法令等。"}, {"text": "他颁布了一份邀请。", "explanation": "这里应该用〈发出〉。邀请是个人发出的，不是官方颁布的法令，要用发出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府去年颁布着新的安全规定。", "corrected_sentence": "政府去年颁布了新的安全规定。", "error_description": "体标错误：“颁布”表示一次完成的动作，应说“颁布了”；“着”表示持续状态，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项新规是上个月颁布了。", "corrected_sentence": "这项新规是上个月颁布的。", "error_description": "句式错误：“是……的”句式强调时间时，动词后要用“的”，不用“了”，应说“颁布的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
