INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93848, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开发布（法律、命令、条例等）。", "primary_collocate": null, "pronunciation": "bān bù", "ipa": "pan˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "国家颁布了新的法律。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律是去年颁布的。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府颁布命令，要求大家留在家里。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家颁布条例，保护野生动物。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新条例颁布后，工厂不能再乱排污水。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席颁布了这项法令。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府颁布过一部保护儿童的法律。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律由国家颁布，全国都要遵守。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府颁布的法令，每个人都要遵守。", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部法律什么时候颁布的？", "target_word": "颁布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颁布了", "label": "完成体"}, {"form": "颁布过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "公开发布法律、命令、条例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b15c9f-8226-4dee-a7e1-d0e9710ecd9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁布", "is_correct": true, "explanation": "正确。“颁布”指公开发布法律、法令，与“新的法律”相合。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于道路、房屋，不说“修建法律”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物，与“新的法律”不相合。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火、灯，不用于法律。"}], "explanations": {"颁布": "正确。“颁布”指公开发布法律、法令，与“新的法律”相合。", "修建": "搭配：“修建”用于道路、房屋，不说“修建法律”。", "拆除": "语义：“拆除”指拆掉建筑物，与“新的法律”不相合。", "熄灭": "搭配：“熄灭”用于火、灯，不用于法律。"}, "sentence_index": 0, "correct_answer": "颁布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动会颁布了金牌。", "explanation": "这里应该用〈颁发〉。金牌是奖项，颁发用于奖章、奖状等，颁布只用于法律、法令、规定。"}, {"text": "市长颁布了放假的消息。", "explanation": "这里应该用〈宣布〉。放假消息不是法令，要用宣布。"}, {"text": "电视台颁布了播出时间。", "explanation": "这里应该用〈公布〉。播出时间是公开告知的信息，不是法令，要用公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颁布", "is_correct": true, "explanation": "正确。“颁布”指政府公开发布法律，与“保护儿童的法律”相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱过一部法律”。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物，不能用于法律。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”是制作影视作品，与“法律”不相合。"}], "explanations": {"颁布": "正确。“颁布”指政府公开发布法律，与“保护儿童的法律”相合。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱过一部法律”。", "种植": "搭配：“种植”用于植物，不能用于法律。", "拍摄": "语义：“拍摄”是制作影视作品，与“法律”不相合。"}, "sentence_index": 6, "correct_answer": "颁布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校颁布了博士学位。", "explanation": "这里应该用〈授予〉。学位是授予个人的，颁布只用于法律、法令。"}, {"text": "老师颁布了考试的地点。", "explanation": "这里应该用〈通知〉。考试地点是告知大家的事，颁布只用于法律、法令。"}, {"text": "他颁布了一封信。", "explanation": "这里应该用〈寄出〉。信件是个人寄出的，不是官方颁布的法令，要用寄出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
