INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "吃的和喝的东西；也指吃喝的习惯。", "primary_collocate": null, "pronunciation": "yǐn shí", "ipa": "in˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他的饮食很规律，每天三顿饭都按时吃。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不健康的饮食会让人越来越胖。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她改变了饮食，现在不吃甜的东西了。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饮食不规律的人，容易得胃病。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方人和北方人的饮食不一样，北方人爱吃面。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上吃很多，这样的饮食对身体不好。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减肥，她少吃肉，饮食变得很清淡。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外住过，饮食已经西化了。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我多吃菜少吃肉，我就改了饮食。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的饮食要定时定量，别吃得太饱。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食", "label": "繁体"}, {"form": "饮食习惯", "label": "复合"}], "register": "中性", "sense_fingerprint": "吃喝的习惯和方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93850, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食：吃的和喝的东西，也指吃喝的习惯。"}, {"text": "殷实", "is_correct": false, "explanation": "yīn（第一声）与 yǐn（第三声）声调不同，殷实是家境富裕的意思。"}, {"text": "隐私", "is_correct": false, "explanation": "声母 s 与 sh 不同，声调也不同（sī 第一声，shí 第二声）；隐私指不愿公开的个人事情。"}, {"text": "隐士", "is_correct": false, "explanation": "yǐn 相同，shì（第四声）与 shí（第二声）声调不同；隐士是隐居的人。"}], "explanations": {"饮食": "饮食：吃的和喝的东西，也指吃喝的习惯。", "殷实": "yīn（第一声）与 yǐn（第三声）声调不同，殷实是家境富裕的意思。", "隐私": "声母 s 与 sh 不同，声调也不同（sī 第一声，shí 第二声）；隐私指不愿公开的个人事情。", "隐士": "yǐn 相同，shì（第四声）与 shí（第二声）声调不同；隐士是隐居的人。"}, "sentence_index": null, "correct_answer": "饮食"}, "level_3": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食指吃喝的习惯，“每天三顿饭都按时吃”正是说饮食规律。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“规律”用于作息、习惯，不能用来形容体重。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与三顿饭的吃法无关，不能说“很规律”。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：票价不能用“很规律”来形容。"}], "explanations": {"饮食": "饮食指吃喝的习惯，“每天三顿饭都按时吃”正是说饮食规律。", "体重": "搭配：“规律”用于作息、习惯，不能用来形容体重。", "天气": "语义：天气与三顿饭的吃法无关，不能说“很规律”。", "票价": "搭配：票价不能用“很规律”来形容。"}, "sentence_index": 0, "correct_answer": "饮食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经养成了早睡的饮食。", "explanation": "这里应该用〈习惯〉。饮食只指吃喝方面的东西或习惯，“早睡”是作息习惯，不能说“早睡的饮食”，要说“早睡的习惯”。"}, {"text": "这家饭店的饮食很热情。", "explanation": "这里应该用〈服务〉。饮食指吃喝的东西，不能用“热情”形容；形容待人的态度要用“服务”。"}, {"text": "他们在饮食吃饭。", "explanation": "这里应该用〈食堂〉。饮食不是地方，不能说“在饮食吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食指吃喝的习惯，“少吃肉，饮食变得很清淡”说的是吃喝习惯的改变。"}, {"text": "作息", "is_correct": false, "explanation": "语义：作息指作息时间和规律，不能“变得很清淡”。"}, {"text": "体型", "is_correct": false, "explanation": "语义：体型不能“清淡”，与“少吃肉”无关。"}, {"text": "态度", "is_correct": false, "explanation": "搭配：“清淡”不用于形容态度。"}], "explanations": {"饮食": "饮食指吃喝的习惯，“少吃肉，饮食变得很清淡”说的是吃喝习惯的改变。", "作息": "语义：作息指作息时间和规律，不能“变得很清淡”。", "体型": "语义：体型不能“清淡”，与“少吃肉”无关。", "态度": "搭配：“清淡”不用于形容态度。"}, "sentence_index": 6, "correct_answer": "饮食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用饮食写了一封信。", "explanation": "这里应该用〈钢笔〉。饮食指吃喝的东西，不能当书写工具，写字要用“钢笔”。"}, {"text": "他的饮食很大，每顿都吃很多。", "explanation": "这里应该用〈饭量〉。饮食不能说“大”或“小”，形容食量要用“饭量”。"}, {"text": "他的饮食是爬山。", "explanation": "这里应该用〈嗜好〉。饮食指吃喝，不能说“是爬山”；表示喜爱的活动要用“嗜好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只规律的饮食，每天三顿饭都按时吃。", "corrected_sentence": "他有一种规律的饮食，每天三顿饭都按时吃。", "error_description": "量词错误：“饮食”指吃喝习惯时应搭配量词“种”，不能用“只”（“只”用于动物或单个的小东西）。正确说法是“有一种规律的饮食”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个民族有一只独特的饮食。", "corrected_sentence": "这个民族有一种独特的饮食。", "error_description": "“饮食”是抽象的、不能按只计数的东西，前面应该用量词“种”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
