INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一起；共同。", "primary_collocate": null, "pronunciation": "yí dào", "ipa": "i˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "大家一道想办法，把问题解决了。", "target_word": "一道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国一道努力，保护环境。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生和家人一道照顾着病人。", "target_word": "一道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一道努力，一定能成功。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校和家长一道帮助这个孩子。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们一道修好了这条路。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居们一道出钱，修了小区的门。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的同事一道完成了这个计划。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个村子一道种树，山变绿了。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和同学们一道准备着晚会。", "target_word": "一道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：多方共同做一件事，强调合作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一道", "is_correct": true, "explanation": "正确。“一道想办法”表示大家共同努力，符合句意。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人做，与“大家”矛盾。"}, {"text": "偏偏", "is_correct": false, "explanation": "搭配：“偏偏”表示故意或出乎意料，不与“想办法解决问题”这种合作行为搭配。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳，与“解决了问题”的结果相矛盾。"}], "explanations": {"一道": "正确。“一道想办法”表示大家共同努力，符合句意。", "独自": "语义：“独自”指一个人做，与“大家”矛盾。", "偏偏": "搭配：“偏偏”表示故意或出乎意料，不与“想办法解决问题”这种合作行为搭配。", "白白": "语义：“白白”表示徒劳，与“解决了问题”的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "一道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人一道努力，一定能成功。", "explanation": "这里把“一道”用成了“单独”的意思，但“一道”表示与别人共同努力。"}, {"text": "我一道吃饭，身边一个人也没有。", "explanation": "这里把“一道”用成了“单独”的意思，但“一道”需要与别人一起吃饭。"}, {"text": "我独自一道完成了这个计划。", "explanation": "这里把“一道”用成了“独自”的意思，但“一道”表示与别人共同完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一道", "is_correct": true, "explanation": "正确。“一道出钱”表示邻居们共同出资，符合句意。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人亲身去做，与“邻居们”集体出钱不符。"}, {"text": "单独", "is_correct": false, "explanation": "语义：“单独”表示只有一个人，与“邻居们”集体出钱矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”表示突然发生，不能与“出钱”这种共同行为搭配。"}], "explanations": {"一道": "正确。“一道出钱”表示邻居们共同出资，符合句意。", "亲自": "语义：“亲自”强调本人亲身去做，与“邻居们”集体出钱不符。", "单独": "语义：“单独”表示只有一个人，与“邻居们”集体出钱矛盾。", "猛然": "搭配：“猛然”表示突然发生，不能与“出钱”这种共同行为搭配。"}, "sentence_index": 6, "correct_answer": "一道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家一道先后走进了会场。", "explanation": "这里把“一道”用成了“不同时间”的意思，但“一道”指在同一时间共同行动。"}, {"text": "我们一道各走各的路，谁也不理谁。", "explanation": "这里把“一道”用成了“各自分开”的意思，但“一道”指和别人共同行动。"}, {"text": "他一道在不同的房间里准备晚会。", "explanation": "这里把“一道”用成了“分开、各在一处”的意思，但“一道”指和别人共同行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们一道了打扫教室。", "corrected_sentence": "同学们一道打扫教室。", "error_description": "错误在“一道”之后多了“了”。副词“一道”后面不能直接加“了”，正确形式是“一道打扫”，“了”不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一道的出发去郊游。", "corrected_sentence": "大家一道出发去郊游。", "error_description": "错误在“一道”之后多了“的”。副词“一道”不能直接加“的”修饰动词，正确形式是“一道出发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
