INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世上是在这个世界上。", "primary_collocate": null, "pronunciation": "shì shàng", "ipa": "ʂɻ̩˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "世上没有不会累的人。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上最好的老师是时间。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个世上有很多好人。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上的路都是人走出来的。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得世上只有妈妈最爱他。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上没有两片一样的叶子。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是世上我最想见的人。", "target_word": "世上", "complexity_tier": "T3", "furigana": "shì shàng", "sentence_source": "generated"}, {"text": "世上的事很多，我们不可能都知道。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说，世上最远的路是回家的路。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个世上，每个人都有自己的路。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世上：这个世界上，泛指所有地方和所有人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世上", "is_correct": true, "explanation": "正确答案：世上（shì shàng），指这个世界上。"}, {"text": "史上", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。"}, {"text": "纸上", "is_correct": false, "explanation": "zhǐ 与 shì 声母不同（zh/sh），声调也不同，意思是写在纸上。"}, {"text": "至上", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。"}, {"text": "市长", "is_correct": false, "explanation": "zhǎng（第三声）与 shàng（第四声）声母不同（zh/sh），声调也不同，“市长”指城市的行政首长。"}, {"text": "市场", "is_correct": false, "explanation": "chǎng（第三声）与 shàng（第四声）声母不同（ch/sh），声调也不同，“市场”指买卖交易的场所。"}], "explanations": {"世上": "正确答案：世上（shì shàng），指这个世界上。", "史上": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。", "纸上": "zhǐ 与 shì 声母不同（zh/sh），声调也不同，意思是写在纸上。", "至上": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。", "市长": "zhǎng（第三声）与 shàng（第四声）声母不同（zh/sh），声调也不同，“市长”指城市的行政首长。", "市场": "chǎng（第三声）与 shàng（第四声）声母不同（ch/sh），声调也不同，“市场”指买卖交易的场所。"}, "sentence_index": null, "correct_answer": "世上"}, "level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指整个人世间，与“没有不会累的人”的泛指语境相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”指具体的屋子，不能指整个人世，“房间没有不会累的人”说不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校”指特定的教育场所，与句中泛指一切人的语境冲突。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是具体场所，不能与“没有不会累的人”这种针对人的泛指判断搭配。"}], "explanations": {"世上": "“世上”指整个人世间，与“没有不会累的人”的泛指语境相符。", "房间": "语义：“房间”指具体的屋子，不能指整个人世，“房间没有不会累的人”说不通。", "学校": "语义：“学校”指特定的教育场所，与句中泛指一切人的语境冲突。", "厨房": "搭配：“厨房”是具体场所，不能与“没有不会累的人”这种针对人的泛指判断搭配。"}, "sentence_index": 0, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打下了世上，当上了皇帝。", "explanation": "这里应该用〈天下〉。“天下”可指国家政权，如“打天下”；“世上”只指人类生活的世界，不能指政权。"}, {"text": "我把钥匙放在世上的抽屉里。", "explanation": "这里应该用〈桌上〉这类方位词。“世上”是泛指人类生活世界的抽象说法，不能当作表示具体存放位置的方位词。"}, {"text": "他在体育世上很有名。", "explanation": "这里应该用〈世界〉。“体育世界”可以指体育领域；“世上”指整个人类社会，不能用来指某个行业或领域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指人世间，“你是世上我最想见的人”表示在整个世界范围内的唯一性，符合语境。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是具体场所，不能作“你是……我最想见的人”中表示范围的成分，句子说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”指特定的医疗机构，不能充当这里表示范围的成分，句子不成立。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“草地”是自然场所，不能与“你是……的人”这种对人的判断搭配。"}], "explanations": {"世上": "“世上”指人世间，“你是世上我最想见的人”表示在整个世界范围内的唯一性，符合语境。", "公园": "语义：“公园”是具体场所，不能作“你是……我最想见的人”中表示范围的成分，句子说不通。", "医院": "语义：“医院”指特定的医疗机构，不能充当这里表示范围的成分，句子不成立。", "草地": "搭配：“草地”是自然场所，不能与“你是……的人”这种对人的判断搭配。"}, "sentence_index": 6, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司的世上有很多员工。", "explanation": "这里应该用〈里〉，说“我们公司里有很多员工”。“世上”指整个人类世界，不能当作一家公司这样的范围来限定。"}, {"text": "这所学校的世上有一百多名老师。", "explanation": "这里应该用〈校园里〉。“世上”指整个人类世界，是泛指的说法，不能当作某所学校这样的局部范围来限定。"}, {"text": "这条老街充满了世上烟火气。", "explanation": "这里应该用〈人间烟火〉。“人间烟火”是固定说法，指人世间的生活气息；“世上”不能替代“人间”组成这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世上里没有完美的人。", "corrected_sentence": "世上没有完美的人。", "error_description": "“世上”本身已经表示“这个世界上”的范围，后面不能再加方位词“里”，应说“世上没有完美的人”；“世上里”属于重复表示处所，错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世上是很多值得学习的人。", "corrected_sentence": "世上有很多值得学习的人。", "error_description": "表示存在时，“世上”后应用动词“有”，不能用“是”；“世上是很多……的人”说法不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
