INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世间；世界上。", "primary_collocate": null, "pronunciation": "shì shàng", "ipa": "ʂɻ̩˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "世上无难事，只怕有心人。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上的钱，你赚不完。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看看世上所有的海。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上的好东西太多了，我买不完。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上最大的鸟是什么？", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷说，世上的人都要吃饭。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上有一种爱，叫作妈妈的爱。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走遍了世上很多国家。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上只有一个你。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上没有水，人就活不了。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世上：世间，人世，指人们生活的整个世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世上", "is_correct": true, "explanation": "正确答案：世上（shì shàng），指这个世界上。"}, {"text": "史上", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。"}, {"text": "纸上", "is_correct": false, "explanation": "zhǐ 与 shì 声母不同（zh/sh），声调也不同，意思是写在纸上。"}, {"text": "至上", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。"}, {"text": "市长", "is_correct": false, "explanation": "zhǎng（第三声）与 shàng（第四声）声母不同（zh/sh），声调也不同，“市长”指城市的行政首长。"}, {"text": "市场", "is_correct": false, "explanation": "chǎng（第三声）与 shàng（第四声）声母不同（ch/sh），声调也不同，“市场”指买卖交易的场所。"}], "explanations": {"世上": "正确答案：世上（shì shàng），指这个世界上。", "史上": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。", "纸上": "zhǐ 与 shì 声母不同（zh/sh），声调也不同，意思是写在纸上。", "至上": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。", "市长": "zhǎng（第三声）与 shàng（第四声）声母不同（zh/sh），声调也不同，“市长”指城市的行政首长。", "市场": "chǎng（第三声）与 shàng（第四声）声母不同（ch/sh），声调也不同，“市场”指买卖交易的场所。"}, "sentence_index": null, "correct_answer": "世上"}, "level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指人世间，与“无难事，只怕有心人”这一泛指哲理的语境相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是具体的上课场所，句中说的是普遍道理，“教室无难事”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是具体场所，不能作为“无难事，只怕有心人”这一泛指判断的主语。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“操场”是运动场所，不能与“无难事”这种对事情的泛指判断搭配。"}], "explanations": {"世上": "“世上”指人世间，与“无难事，只怕有心人”这一泛指哲理的语境相符。", "教室": "语义：“教室”是具体的上课场所，句中说的是普遍道理，“教室无难事”说不通。", "厨房": "语义：“厨房”是具体场所，不能作为“无难事，只怕有心人”这一泛指判断的主语。", "操场": "搭配：“操场”是运动场所，不能与“无难事”这种对事情的泛指判断搭配。"}, "sentence_index": 0, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杭州被誉为世上天堂。", "explanation": "这里应该用〈人间天堂〉。“人间天堂”是固定说法，比喻风景优美的地方；“世上”不能替代“人间”组成这个词。"}, {"text": "我的自行车就停在世上的门口。", "explanation": "这里应该用〈门边〉之类的方位词。“世上”是泛指人类社会的说法，不能当作具体地点的方位词。"}, {"text": "他夺得了世上，成了这个国家的新主人。", "explanation": "这里应该用〈天下〉。“天下”可指国家的统治权，“世上”不能表示政权，“夺得了世上”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指人世间，“世上有一种爱”指世间存在这样的爱，符合语境。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是具体场所，不能作为“有一种爱”的存在范围，句子说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”指医疗机构，“医院有一种爱”与句子的泛指语境不符。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”作主语与“有一种爱”搭配不当，场所不能被说成“有爱”。"}], "explanations": {"世上": "“世上”指人世间，“世上有一种爱”指世间存在这样的爱，符合语境。", "公园": "语义：“公园”是具体场所，不能作为“有一种爱”的存在范围，句子说不通。", "医院": "语义：“医院”指医疗机构，“医院有一种爱”与句子的泛指语境不符。", "车站": "搭配：“车站”作主语与“有一种爱”搭配不当，场所不能被说成“有爱”。"}, "sentence_index": 6, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班的世上最会画画的同学。", "explanation": "这里应该用〈全班〉。“世上”指整个人类世界，不能与“我们班”这样的小范围并列限定，应去掉“世上”，说全班最会画画的同学。"}, {"text": "他在音乐世上很有名。", "explanation": "“世上”不能指某个行业的圈子，说音乐领域的名声要用〈音乐界〉。"}, {"text": "这个国家的世上只有一座大城市。", "explanation": "这里应该用〈国内〉。“世上”指整个人类世界，不能当作一个国家的范围来限定，国家范围要说〈国内〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想世上找到一个真心朋友。", "corrected_sentence": "我想在世上找到一个真心朋友。", "error_description": "“世上”是表示地点的成分，前面须加介词“在”，说“在世上找到”；漏掉“在”成“想世上找到”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世上里没有免费的午餐。", "corrected_sentence": "世上没有免费的午餐。", "error_description": "“世上”本身已表示“这个世界上”的范围，后面不能再加方位词“里”，应说“世上没有免费的午餐”；“世上里”属于重复表示处所，错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "人均是把总数分给每一个人，每人得到的数。", "primary_collocate": null, "pronunciation": "rén jūn", "ipa": "ɻən˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这笔钱分下来，人均五百元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班一共买了六十本书，人均两本。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动的费用，人均一百块。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司去年发的奖金，人均三千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小区的停车位太少，人均不到一个。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们六个人，人均两千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果一共二十斤，人均四斤。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的消费，人均八十元左右。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地一共十亩，人均才一亩多。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里的零食，人均能分到三包。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：把总数分给每个人，每人得到的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确答案。人均：把总数分给每个人，每人得到的数量。"}, {"text": "人群", "is_correct": false, "explanation": "rén 相同，但 qún 与 jūn 声母不同（q 与 j），声调也不同（第二声）；意思是人群。"}, {"text": "新军", "is_correct": false, "explanation": "xīn（第一声）与 rén（第二声）声母不同（x 与 r），声调也不同；意思是新组建的军队。"}, {"text": "民军", "is_correct": false, "explanation": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。"}, {"text": "人居", "is_correct": false, "explanation": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}], "explanations": {"人均": "正确答案。人均：把总数分给每个人，每人得到的数量。", "人群": "rén 相同，但 qún 与 jūn 声母不同（q 与 j），声调也不同（第二声）；意思是人群。", "新军": "xīn（第一声）与 rén（第二声）声母不同（x 与 r），声调也不同；意思是新组建的军队。", "民军": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。", "人居": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}, "sentence_index": null, "correct_answer": "人均"}, "level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“五百元”，表示每人分得的数额，与“分下来”的语境一致。"}, {"text": "篇均", "is_correct": false, "explanation": "语义：“篇均”按篇数平均，钱款不以“篇”计，句中说不通。"}, {"text": "件均", "is_correct": false, "explanation": "量词：“件”用于计量物品，不能用来计量钱款，句中说不通。"}, {"text": "亩均", "is_correct": false, "explanation": "语义：“亩均”按土地面积计算，句中的对象是钱，不是土地。"}], "explanations": {"人均": "正确。此处人均修饰“五百元”，表示每人分得的数额，与“分下来”的语境一致。", "篇均": "语义：“篇均”按篇数平均，钱款不以“篇”计，句中说不通。", "件均": "量词：“件”用于计量物品，不能用来计量钱款，句中说不通。", "亩均": "语义：“亩均”按土地面积计算，句中的对象是钱，不是土地。"}, "sentence_index": 0, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的年降雨量人均一千毫米。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，降雨量不能按人均，要说“平均一千毫米”。"}, {"text": "这台机器的人均寿命是十年。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，机器的寿命不能按人均，要说“平均寿命”。"}, {"text": "这个学校的班级人均规模是三十人。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，班级规模按班级算，不能说人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均表示平均到每人的数量，与“一共二十斤”的总量相对应。"}, {"text": "艘均", "is_correct": false, "explanation": "量词：“艘”用于船只，水果不能用“艘”计量，句中说不通。"}, {"text": "台均", "is_correct": false, "explanation": "搭配：“台”多用于机器、设备，不能用于水果，不能说台均。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，水果不能按“页”平均，句中说不通。"}], "explanations": {"人均": "正确。此处人均表示平均到每人的数量，与“一共二十斤”的总量相对应。", "艘均": "量词：“艘”用于船只，水果不能用“艘”计量，句中说不通。", "台均": "搭配：“台”多用于机器、设备，不能用于水果，不能说台均。", "页均": "量词：“页”用于计量纸张，水果不能按“页”平均，句中说不通。"}, "sentence_index": 6, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱零食只给了我一个人，人均能分到三包。", "explanation": "这里应该用〈独得〉。“人均”要求平均到两人以上，只给一个人时要说“全部归我”，不能用“人均”。"}, {"text": "班里的零食，人均能装三包。", "explanation": "这里应该用〈每箱〉。“人均”只按人算，不能说一个人能装多少包。"}, {"text": "这座山的人均海拔很高。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，山的海拔不能按人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔补贴分下来，人均了五百元。", "corrected_sentence": "这笔补贴分下来，人均五百元。", "error_description": "错误在“人均”之后多了“了”。“人均”是修饰语，不能带“了”，正确形式是“人均五百元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次团建的费用，很人均两百元。", "corrected_sentence": "这次团建的费用，人均两百元。", "error_description": "错误在“人均”前多了“很”。“人均”是非程度形容词，不能受程度副词“很”修饰，正确形式是“人均两百元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
