INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平均到每个人的；按人口平均计算的。", "primary_collocate": null, "pronunciation": "rén jūn", "ipa": "ɻən˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这个国家的人均收入越来越高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的人均住房面积是多少？", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的人均寿命已经超过七十岁了。", "target_word": "人均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市人均耕地很少。", "target_word": "人均", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人均用水量每年都在下降。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们国家的人均消费水平不高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人均收入比去年多了两千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人均绿地面积大的城市，空气一般比较好。", "target_word": "人均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸说，今年人均消费增加了。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区人均粮食产量很高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：修饰名词，按人口平均计算的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确答案。人均：按人口平均计算的。"}, {"text": "人群", "is_correct": false, "explanation": "rén 相同，qún 与 jūn 声母不同（q 与 j），声调也不同（第二声）；意思是人群。"}, {"text": "新军", "is_correct": false, "explanation": "xīn（第一声）与 rén（第二声）声母不同（x 与 r），声调也不同；意思是新组建的军队。"}, {"text": "民军", "is_correct": false, "explanation": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。"}, {"text": "人居", "is_correct": false, "explanation": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}], "explanations": {"人均": "正确答案。人均：按人口平均计算的。", "人群": "rén 相同，qún 与 jūn 声母不同（q 与 j），声调也不同（第二声）；意思是人群。", "新军": "xīn（第一声）与 rén（第二声）声母不同（x 与 r），声调也不同；意思是新组建的军队。", "民军": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。", "人居": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}, "sentence_index": null, "correct_answer": "人均"}, "level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“收入”，表示按人口平均计算的收入。"}, {"text": "台均", "is_correct": false, "explanation": "搭配：“台”是机器、设备的量词，不能用来修饰“收入”。"}, {"text": "件均", "is_correct": false, "explanation": "搭配：“件”用于计量物品，不能用于说明一个国家的收入。"}, {"text": "亩均", "is_correct": false, "explanation": "语义：“亩均”按土地面积计算，句中的“收入”与土地无关。"}], "explanations": {"人均": "正确。此处人均修饰“收入”，表示按人口平均计算的收入。", "台均": "搭配：“台”是机器、设备的量词，不能用来修饰“收入”。", "件均": "搭配：“件”用于计量物品，不能用于说明一个国家的收入。", "亩均": "语义：“亩均”按土地面积计算，句中的“收入”与土地无关。"}, "sentence_index": 0, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的人均温度很高。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，温度不能按人均，要说“平均温度”。"}, {"text": "这台电脑的人均内存很大。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，单台电脑的内存不能按人均。"}, {"text": "这个城市的人均人口很少。", "explanation": "这里应该用〈总数〉。“人均”是平均数，不能修饰“人口”这种总数，要说“这个城市的人口很少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“收入”，表示平均到每人的收入。"}, {"text": "篇均", "is_correct": false, "explanation": "语义：“篇均”按篇数平均，收入不以“篇”计，句中说不通。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，不能用来计量收入，句中说不通。"}, {"text": "班均", "is_correct": false, "explanation": "语义：“班均”指按班级平均，句中是地区的收入，不是班级的。"}], "explanations": {"人均": "正确。此处人均修饰“收入”，表示平均到每人的收入。", "篇均": "语义：“篇均”按篇数平均，收入不以“篇”计，句中说不通。", "页均": "量词：“页”用于计量纸张，不能用来计量收入，句中说不通。", "班均": "语义：“班均”指按班级平均，句中是地区的收入，不是班级的。"}, "sentence_index": 6, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的人均速度是每小时六十公里。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，车速不能按人均，要说“平均速度”。"}, {"text": "这条河的人均长度很长。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，河的长度不能按人均。"}, {"text": "这块地的人均亩产很高。", "explanation": "这里应该用〈每亩〉。“人均”只按人口计算，亩产是按土地算的，不能用人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的人均了用电量逐年下降。", "corrected_sentence": "这个城市的人均用电量逐年下降。", "error_description": "错误在“人均”之后多了“了”。“人均”修饰“用电量”，中间不能加“了”，正确形式是“人均用电量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个省的很人均粮食产量逐年增加。", "corrected_sentence": "这个省的人均粮食产量逐年增加。", "error_description": "错误在“人均”前多了“很”。“人均”是非程度形容词，不能受程度副词“很”修饰，正确形式是“人均粮食产量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
