INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传媒是把消息告诉很多人的东西，比如电视和报纸。", "primary_collocate": null, "pronunciation": "chuán méi", "ipa": "ʈʂʰwan˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "电视和报纸都是传媒。", "target_word": "传媒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "传媒能让很多人知道这件事。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的传媒比以前快多了。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有传媒的时候，人们靠信件知道消息。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "传媒每天都告诉我们新消息。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸、电视这些传媒，我爷爷都喜欢。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多老人觉得，传媒就是电视和报纸。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了传媒，小镇的人也能知道大城市的事。", "target_word": "传媒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传媒报道了这件事，大家才知道。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想当记者，所以对传媒很感兴趣。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传媒界", "label": "复合词"}, {"form": "传媒公司", "label": "复合词"}], "register": "书面", "sense_fingerprint": "电视、报纸等把消息告诉大家的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传媒", "is_correct": true, "explanation": "正确：“传媒”指电视、报纸等传播消息的工具，与“电视和报纸”同类。"}, {"text": "食品", "is_correct": false, "explanation": "语义：“食品”指吃的东西，与“电视和报纸”不属于同一类事物。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”指看病的地方，与“电视和报纸”不是一类事物。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：“典籍”是文言色彩很浓的书面词，指古代书籍，与此口语语境不符。"}], "explanations": {"传媒": "正确：“传媒”指电视、报纸等传播消息的工具，与“电视和报纸”同类。", "食品": "语义：“食品”指吃的东西，与“电视和报纸”不属于同一类事物。", "医院": "语义：“医院”指看病的地方，与“电视和报纸”不是一类事物。", "典籍": "语域：“典籍”是文言色彩很浓的书面词，指古代书籍，与此口语语境不符。"}, "sentence_index": 0, "correct_answer": "传媒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我收到了一个传媒。", "explanation": "这里应该用〈通知〉。收到的可以是通知、消息，而“传媒”是传播消息的工具或机构，不能“收到”。"}, {"text": "我家里有一只传媒。", "explanation": "这里应该用〈个〉。“传媒”指抽象的媒介或机构，不能用“只”计量，应换用“个”。"}, {"text": "我的爸爸是一位好传媒。", "explanation": "“传媒”指报刊、电视等工具或机构，不指人。这里指人应该用〈记者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传媒", "is_correct": true, "explanation": "正确：“传媒”指报刊、电视等传播消息的工具，与“就是电视和报纸”的说法相符。"}, {"text": "文物", "is_correct": false, "explanation": "语义：“文物”指古代遗留的器物，与“电视和报纸”不是一类事物。"}, {"text": "药品", "is_correct": false, "explanation": "语义：“药品”指治病的东西，与“就是电视和报纸”的定义不符。"}, {"text": "宗庙", "is_correct": false, "explanation": "语域：“宗庙”是文言词，指祭祀祖先的地方，与口语语境不符。"}], "explanations": {"传媒": "正确：“传媒”指报刊、电视等传播消息的工具，与“就是电视和报纸”的说法相符。", "文物": "语义：“文物”指古代遗留的器物，与“电视和报纸”不是一类事物。", "药品": "语义：“药品”指治病的东西，与“就是电视和报纸”的定义不符。", "宗庙": "语域：“宗庙”是文言词，指祭祀祖先的地方，与口语语境不符。"}, "sentence_index": 6, "correct_answer": "传媒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做了一次传媒。", "explanation": "这里应该用〈调查〉。“做”可接调查、实验；“传媒”是工具或机构，不能用来“做一次”。"}, {"text": "他买了一台传媒。", "explanation": "这里应该用〈家〉。“传媒”指机构时用“家”计量；“台”用于机器，不用于“传媒”。"}, {"text": "他找到了一份传媒。", "explanation": "这里应该用〈工作〉。“找到”可接工作、职位；“传媒”是工具或机构，不能“找到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
