INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传播信息的媒介，如报刊、广播、电视、网络。", "primary_collocate": null, "pronunciation": "chuán méi", "ipa": "ʈʂʰwan˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "报刊、广播和网络都是传媒。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "传媒对社会的影响越来越大。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "传媒要对读者负责，不能乱说。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络这种新传媒，改变了人们读新闻的方式。", "target_word": "传媒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传媒的报道要真实，不能骗人。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授研究传媒已经二十年了。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在传媒的帮助下，这个小村子出名了。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "传媒常常影响人们对一件事的看法。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们通过传媒，把好消息告诉了全国人民。", "target_word": "传媒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传媒说的话，我们不能全信。", "target_word": "传媒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传媒界", "label": "复合词"}, {"form": "传媒公司", "label": "复合词"}], "register": "书面", "sense_fingerprint": "报刊、广播、电视、网络等传播信息的媒介及其社会作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传媒", "is_correct": true, "explanation": "正确：“传媒”指传播信息的媒介，报刊、广播和网络都属于此类。"}, {"text": "农场", "is_correct": false, "explanation": "语义：“农场”指种植养殖的地方，与“报刊、广播和网络”不属于同一类。"}, {"text": "药房", "is_correct": false, "explanation": "语义：“药房”指卖药的地方，与“报刊、广播和网络”不属于同一类。"}, {"text": "典章", "is_correct": false, "explanation": "语域：“典章”是文言词，指制度和法典，与此语境不符，也不指传播媒介。"}], "explanations": {"传媒": "正确：“传媒”指传播信息的媒介，报刊、广播和网络都属于此类。", "农场": "语义：“农场”指种植养殖的地方，与“报刊、广播和网络”不属于同一类。", "药房": "语义：“药房”指卖药的地方，与“报刊、广播和网络”不属于同一类。", "典章": "语域：“典章”是文言词，指制度和法典，与此语境不符，也不指传播媒介。"}, "sentence_index": 0, "correct_answer": "传媒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台传媒。", "explanation": "这里应该用〈种〉。“传媒”指抽象的媒介，用“种”计量；“台”用于机器，不用于“传媒”。"}, {"text": "我妈妈每天用传媒做饭。", "explanation": "这里应该用〈厨具〉。“传媒”是传播信息的媒介，不能用来做饭，应换成厨具。"}, {"text": "我们每天吃传媒。", "explanation": "这里应该用〈饭〉。“吃”的宾语应是食物，“传媒”是传播信息的媒介，不能吃；应说“吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传媒", "is_correct": true, "explanation": "正确：“传媒”指传播信息的媒介，与“在……的帮助下”搭配通顺，符合语境。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是穿在脚上的日用品，不能帮助村子出名，与此语境不符。"}, {"text": "凶器", "is_correct": false, "explanation": "语义：“凶器”指伤人的器具，与村子出名的语境完全相反。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：“棉被”是盖在身上的寝具，与村子出名的语境完全不符。"}], "explanations": {"传媒": "正确：“传媒”指传播信息的媒介，与“在……的帮助下”搭配通顺，符合语境。", "拖鞋": "语义：“拖鞋”是穿在脚上的日用品，不能帮助村子出名，与此语境不符。", "凶器": "语义：“凶器”指伤人的器具，与村子出名的语境完全相反。", "棉被": "语义：“棉被”是盖在身上的寝具，与村子出名的语境完全不符。"}, "sentence_index": 6, "correct_answer": "传媒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打了一个传媒。", "explanation": "这里应该用〈电话〉。“打”可接电话；“传媒”是工具或机构，不能用“打”。"}, {"text": "他买了一只传媒。", "explanation": "这里应该用〈种〉。“只”用于动物或成对的物件，“传媒”是抽象的媒介，应用“种”计量。"}, {"text": "他是我们学校的传媒。", "explanation": "“传媒”指工具或机构，不指人。这里指人应该用〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网络是一只新传媒。", "corrected_sentence": "网络是一种新传媒。", "error_description": "错误：量词“只”不能用于“传媒”，应为“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在传媒地报道下，大家都知道了这件事。", "corrected_sentence": "在传媒的报道下，大家都知道了这件事。", "error_description": "错误：修饰名词“报道”时用了结构助词“地”，应为“的”。“地”用于修饰动词、形容词，“的”用于修饰名词，所以“传媒”后应为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
