INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公安是抓坏人、保护大家平安的人，也指他们的机关。", "primary_collocate": null, "pronunciation": "gōng ān", "ipa": "kʊŋ˥ an˥", "syllable_count": 2, "sentences": [{"text": "公安来了，坏人跑了。", "target_word": "公安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一名公安。", "target_word": "公安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公安在路口帮我们找孩子。", "target_word": "公安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸在公安工作。", "target_word": "公安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公安抓住了那个小偷。", "target_word": "公安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你打电话给公安。", "target_word": "公安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公安叔叔教我们过马路。", "target_word": "公安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想长大以后当公安。", "target_word": "公安", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公安说，这条路今天不能走。", "target_word": "公安", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天有人向公安说了这件事。", "target_word": "公安", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公安局", "label": "复合"}, {"form": "公安人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "公安：抓坏人、保护平安的人，也指其机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公安", "is_correct": true, "explanation": "“公安”指公安机关或公安人员，能够来抓坏人，与句意相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”是医疗机构，不能来抓坏人，“医院来了，坏人跑了”不合逻辑。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”不负责抓捕坏人，“厨师来了，坏人跑了”与常理不符。"}, {"text": "邮局", "is_correct": false, "explanation": "搭配：“邮局”是寄信取件的场所，不能作“来了”的主语去处理坏人，搭配不当。"}], "explanations": {"公安": "“公安”指公安机关或公安人员，能够来抓坏人，与句意相符。", "医院": "语义：“医院”是医疗机构，不能来抓坏人，“医院来了，坏人跑了”不合逻辑。", "厨师": "语义：“厨师”不负责抓捕坏人，“厨师来了，坏人跑了”与常理不符。", "邮局": "搭配：“邮局”是寄信取件的场所，不能作“来了”的主语去处理坏人，搭配不当。"}, "sentence_index": 0, "correct_answer": "公安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们周末去公安散步。", "explanation": "这里应该用〈公园〉。“公安”指公安机关或公安人员，不是游玩散步的场所。"}, {"text": "我今天在公安买了一瓶水。", "explanation": "这里应该用〈超市〉。“公安”指公安机关或公安人员，不是卖东西的地方，不能在这里买水。"}, {"text": "公安判了这个案子，犯人被判了三年。", "explanation": "这里应该用〈法院〉。“公安”负责侦查和维护治安，不负责审判定罪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公安", "is_correct": true, "explanation": "“公安叔叔”指公安人员，教孩子过马路符合其职责，与句意相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“医生”的职业与教孩子过马路无关，“医生叔叔教我们过马路”不合常理。"}, {"text": "花农", "is_correct": false, "explanation": "搭配：“花农”指种花的人，与“教我们过马路”这类交通安全内容搭配不当。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：“理发师”以理发为业，不负责教孩子交通安全，句子不合常理。"}], "explanations": {"公安": "“公安叔叔”指公安人员，教孩子过马路符合其职责，与句意相符。", "医生": "语义：“医生”的职业与教孩子过马路无关，“医生叔叔教我们过马路”不合常理。", "花农": "搭配：“花农”指种花的人，与“教我们过马路”这类交通安全内容搭配不当。", "理发师": "语义：“理发师”以理发为业，不负责教孩子交通安全，句子不合常理。"}, "sentence_index": 6, "correct_answer": "公安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向公安咨询了贷款的事。", "explanation": "这里应该用〈银行〉。“公安”不办理贷款，咨询贷款要找银行。"}, {"text": "他肚子疼，去公安看病了。", "explanation": "这里应该用〈医院〉。“公安”是公安机关，不是医疗机构，看病要去医院。"}, {"text": "我的鞋子坏了，我去公安修鞋。", "explanation": "这里应该用〈鞋店〉。“公安”不是修鞋的场所，修鞋应去鞋店或修鞋摊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想请一只公安帮忙。", "corrected_sentence": "我想请一名公安帮忙。", "error_description": "“公安”指人，量词应用“名”，应说“一名公安”；“一只”是动物量词，不能用于人，错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小偷被公安的抓住了。", "corrected_sentence": "小偷被公安抓住了。", "error_description": "“公安”作“被”字句的施事，后面应直接接动词“抓住”，不能加“的”；“被公安的抓住了”结构错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
