INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "助理是帮别人做事的人。", "primary_collocate": null, "pronunciation": "zhù lǐ", "ipa": "tʂu⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "我是经理的助理。", "target_word": "助理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的助理很年轻。", "target_word": "助理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "助理帮老板订了机票。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想找一个会说英语的助理。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的助理今天请假了。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师有两位助理。", "target_word": "助理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "助理每天早上八点来上班。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小店需要一个助理。", "target_word": "助理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他做了三年助理，学到了很多东西。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很忙，助理替他接了电话。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "私人助理", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮别人做事的人（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”（zhù lǐ）是帮别人做事的人，即正确答案。"}, {"text": "数理", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），意思是数学和物理。"}, {"text": "主力", "is_correct": false, "explanation": "zhǔ 与 zhù 声调不同，lì 与 lǐ 声调也不同，意思是主要的力量。"}, {"text": "助力", "is_correct": false, "explanation": "lì 与 lǐ 声调不同，意思是帮助的力量。"}], "explanations": {"助理": "“助理”（zhù lǐ）是帮别人做事的人，即正确答案。", "数理": "shù 与 zhù 声母不同（sh 与 zh），意思是数学和物理。", "主力": "zhǔ 与 zhù 声调不同，lì 与 lǐ 声调也不同，意思是主要的力量。", "助力": "lì 与 lǐ 声调不同，意思是帮助的力量。"}, "sentence_index": null, "correct_answer": "助理"}, "level_3": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”指帮别人做事的人，放在“我是经理的”之后正合适。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地点，不能作为人的身份，“经理的厨房”不通。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：“戒指”是首饰，不能作为人的身份，“我是经理的戒指”不通。"}, {"text": "出租车", "is_correct": false, "explanation": "搭配：“出租车”一般不能说“某人的出租车”来表示职务身份，句子不通。"}], "explanations": {"助理": "“助理”指帮别人做事的人，放在“我是经理的”之后正合适。", "厨房": "语义：“厨房”是地点，不能作为人的身份，“经理的厨房”不通。", "戒指": "语义：“戒指”是首饰，不能作为人的身份，“我是经理的戒指”不通。", "出租车": "搭配：“出租车”一般不能说“某人的出租车”来表示职务身份，句子不通。"}, "sentence_index": 0, "correct_answer": "助理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位助理冲进火场救出了三个人。", "explanation": "这里应该用〈消防员〉。“助理”指协助别人办事的人，不指冲进火场救人的人。"}, {"text": "这位助理画了很多名画。", "explanation": "这里应该用〈画家〉。“助理”指协助别人办事的人，不指从事绘画创作的人。"}, {"text": "他是公司的助理，负责决定公司的方向。", "explanation": "这里应该用〈老板〉。助理只协助负责人办事，不能决定公司的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”是人，可以每天来上班，符合句子语境。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不会每天早上来上班，句子说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能“来上班”。"}, {"text": "水壶", "is_correct": false, "explanation": "搭配：“来上班”的主语应是人，“水壶”不能与“上班”搭配。"}], "explanations": {"助理": "“助理”是人，可以每天来上班，符合句子语境。", "钢琴": "语义：“钢琴”是乐器，不会每天早上来上班，句子说不通。", "花园": "语义：“花园”是地方，不能“来上班”。", "水壶": "搭配：“来上班”的主语应是人，“水壶”不能与“上班”搭配。"}, "sentence_index": 6, "correct_answer": "助理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位助理在路口指挥交通。", "explanation": "这里应该用〈警察〉。“助理”指协助别人办事的人，不指指挥交通的人。"}, {"text": "这位助理给病人做了手术。", "explanation": "这里应该用〈医生〉。“助理”指协助别人办事的人，不指给病人做手术的人。"}, {"text": "这位助理设计了这座大桥。", "explanation": "这里应该用〈工程师〉。“助理”指协助别人办事的人，不指设计大桥的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只助理工作很认真。", "corrected_sentence": "这位助理工作很认真。", "error_description": "错误：量词“只”用于动物，修饰人应用“位”或“个”。正确：“这位助理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是部长的一只助理。", "corrected_sentence": "他是部长的一位助理。", "error_description": "错误：量词“只”用于动物，指人应用“位”或“个”。正确：“一位助理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
