INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助主要负责人办事的人。", "primary_collocate": null, "pronunciation": "zhù lǐ", "ipa": "tʂu⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "总经理的助理正在开会。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长的助理给大家发了通知。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是校长的助理，每天都很忙。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "助理把会议时间告诉了大家。", "target_word": "助理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院长不在，请跟他的助理联系。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位助理负责安排老板的工作。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先当助理，后来才成了经理。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理出差时，助理要处理文件。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "董事长的助理每天提前到公司。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的助理跟着部长去开会了。", "target_word": "助理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "行政助理", "label": "复合"}], "register": "中性", "sense_fingerprint": "协助领导或主要负责人办事的人（工作场合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c11b62-a391-4e78-aa2c-8e0c8aef0aa1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”（zhù lǐ）是协助主要负责人办事的人，即正确答案。"}, {"text": "数理", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），意思是数学和物理。"}, {"text": "主力", "is_correct": false, "explanation": "zhǔ 与 zhù 声调不同，lì 与 lǐ 声调也不同，意思是主要的力量。"}, {"text": "助力", "is_correct": false, "explanation": "lì 与 lǐ 声调不同，意思是帮助的力量。"}], "explanations": {"助理": "“助理”（zhù lǐ）是协助主要负责人办事的人，即正确答案。", "数理": "shù 与 zhù 声母不同（sh 与 zh），意思是数学和物理。", "主力": "zhǔ 与 zhù 声调不同，lì 与 lǐ 声调也不同，意思是主要的力量。", "助力": "lì 与 lǐ 声调不同，意思是帮助的力量。"}, "sentence_index": null, "correct_answer": "助理"}, "level_3": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”指协助负责人办事的人，放在“总经理的”之后正合适。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”不能参加会议，“正在开会”的主语应是人。"}, {"text": "水壶", "is_correct": false, "explanation": "搭配：“正在开会”的主语应是人，“水壶”不能与之搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能“正在开会”，句子说不通。"}], "explanations": {"助理": "“助理”指协助负责人办事的人，放在“总经理的”之后正合适。", "手表": "语义：“手表”不能参加会议，“正在开会”的主语应是人。", "水壶": "搭配：“正在开会”的主语应是人，“水壶”不能与之搭配。", "花园": "语义：“花园”是地方，不能“正在开会”，句子说不通。"}, "sentence_index": 0, "correct_answer": "助理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位助理下令关闭了工厂。", "explanation": "这里应该用〈厂长〉。“助理”只协助负责人办事，不能自己下令关闭工厂。"}, {"text": "这位助理在法庭上亲自给被告定罪。", "explanation": "这里应该用〈法官〉。“助理”指协助别人办事的人，不能在法庭上给被告定罪。"}, {"text": "这位助理治好了很多病人。", "explanation": "这里应该用〈医生〉。“助理”指协助别人办事的人，不指治病的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助理", "is_correct": true, "explanation": "“助理”是人，可以先当助理再当经理，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“当”后接职业或身份，“钥匙”不能作为身份，“先当钥匙”不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能“当”了再成为经理，句子无意义。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能作为人的身份，句子说不通。"}], "explanations": {"助理": "“助理”是人，可以先当助理再当经理，符合句意。", "钥匙": "搭配：“当”后接职业或身份，“钥匙”不能作为身份，“先当钥匙”不通。", "桌子": "语义：“桌子”是家具，不能“当”了再成为经理，句子无意义。", "窗户": "语义：“窗户”不能作为人的身份，句子说不通。"}, "sentence_index": 6, "correct_answer": "助理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位助理指挥了全船的人。", "explanation": "这里应该用〈船长〉。“助理”只协助别人办事，不能指挥全船的人。"}, {"text": "这位助理驾驶着这艘远洋货轮。", "explanation": "这里应该用〈驾驶员〉。“助理”指协助别人办事的人，不指驾驶船只的人。"}, {"text": "这位助理在奥运会上夺得了金牌。", "explanation": "这里应该用〈运动员〉。“助理”指协助别人办事的人，不指参赛夺冠的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院长的那只助理很忙。", "corrected_sentence": "院长的那位助理很忙。", "error_description": "错误：“那只”中的“只”用于动物，指人应用“位”。正确：“那位助理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是老板的一只助理。", "corrected_sentence": "他是老板的一位助理。", "error_description": "错误：量词“只”用于动物，指人应用“位”或“个”。正确：“一位助理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8403cf0-dd32-4cb1-89b8-d7147bef6020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
