INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93889, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "胜是比赛时比别人强，赢了。", "primary_collocate": null, "pronunciation": "shèng", "ipa": "ʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这场足球比赛，我们队胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红队以三比一胜了蓝队。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结果出来了，谁胜了？", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这盘棋，爷爷胜了我。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上次他输了，这次他胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的比赛，我们队以二比一胜了对方。", "target_word": "胜", "complexity_tier": "T3", "furigana": "zuótiān de bǐsài, wǒmen duì yǐ èr bǐ yī shèng le duìfāng.", "sentence_source": "generated"}, {"text": "两个队踢了很久，最后蓝队胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟跑得很快，这次胜了哥哥。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打了一场球，我们以五分胜了对方。", "target_word": "胜", "complexity_tier": "T3", "furigana": "tāmen dǎ le yì chǎng qiú, wǒmen yǐ wǔ fēn shèng le duìfāng.", "sentence_source": "generated"}, {"text": "比赛还没结束，谁胜谁负还不知道。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "胜了", "label": "完成体"}, {"form": "勝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：比赛中比对方强，赢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确答案。胜：比赛时比别人强，赢了。"}, {"text": "声", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是声音。"}, {"text": "省", "is_correct": false, "explanation": "声调不同：shěng（第三声）与 shèng（第四声）不同，意思是省份。"}, {"text": "绳", "is_correct": false, "explanation": "声调不同：shéng（第二声）与 shèng（第四声）不同，意思是绳子。"}, {"text": "升", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是升降、容量单位。"}], "explanations": {"胜": "正确答案。胜：比赛时比别人强，赢了。", "声": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是声音。", "省": "声调不同：shěng（第三声）与 shèng（第四声）不同，意思是省份。", "绳": "声调不同：shéng（第二声）与 shèng（第四声）不同，意思是绳子。", "升": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是升降、容量单位。"}, "sentence_index": null, "correct_answer": "胜"}, "level_3": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确。“我们队胜了”表示在足球比赛中赢了。"}, {"text": "唱", "is_correct": false, "explanation": "语义：足球比赛的结果不能用“唱”来表示，句中的语境是比赛。"}, {"text": "游", "is_correct": false, "explanation": "语义：足球比赛中没有“游”的动作，这个词与比赛语境冲突。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用来说比赛的结果，与“我们队”和比赛无法搭配。"}], "explanations": {"胜": "正确。“我们队胜了”表示在足球比赛中赢了。", "唱": "语义：足球比赛的结果不能用“唱”来表示，句中的语境是比赛。", "游": "语义：足球比赛中没有“游”的动作，这个词与比赛语境冲突。", "吃": "搭配：“吃”不能用来说比赛的结果，与“我们队”和比赛无法搭配。"}, "sentence_index": 0, "correct_answer": "胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他胜了这次面试。", "explanation": "这里应该用〈通过〉。“胜”用于比赛、争斗等对抗情境，面试没有对手，要说“通过面试”。"}, {"text": "我们队胜了那场音乐会。", "explanation": "这里应该用〈赢〉。“胜”的宾语是对手，不能接“音乐会”，音乐会没有对手。"}, {"text": "我们胜了一份合同。", "explanation": "这里应该用〈签下〉。“胜”用于比赛、争斗等对抗情境，不能用于签合同，要说“签下合同”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93889, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确答案。胜：比赛时比别人强，赢了。"}, {"text": "生", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是出生、生活。"}, {"text": "笙", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是一种吹奏乐器。"}, {"text": "牲", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是牲畜。"}, {"text": "甥", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是外甥。"}], "explanations": {"胜": "正确答案。胜：比赛时比别人强，赢了。", "生": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是出生、生活。", "笙": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是一种吹奏乐器。", "牲": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是牲畜。", "甥": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是外甥。"}, "sentence_index": null, "correct_answer": "胜"}, "level_3": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确。“最后蓝队胜了”表示比赛中蓝队赢了。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与比赛的结果不相关，句子说的是比赛结束后的胜负。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”与比赛的结果不相关，句中没有绘画的语境。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡”不能用来说比赛的结果，与“最后蓝队”搭配不当。"}], "explanations": {"胜": "正确。“最后蓝队胜了”表示比赛中蓝队赢了。", "喝": "语义：“喝”与比赛的结果不相关，句子说的是比赛结束后的胜负。", "画": "语义：“画”与比赛的结果不相关，句中没有绘画的语境。", "睡": "搭配：“睡”不能用来说比赛的结果，与“最后蓝队”搭配不当。"}, "sentence_index": 6, "correct_answer": "胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他胜了这场电影。", "explanation": "这里应该用〈看〉。“胜”用于比赛、争斗等对抗情境，看电影不是对抗，不能用“胜”。"}, {"text": "他打牌胜了一百块钱。", "explanation": "这里应该用〈赢〉。“胜”的宾语是对手，不能接“一百块钱”；要说“赢了一百块钱”。"}, {"text": "我们队胜了好成绩。", "explanation": "这里应该用〈取得〉。“胜”只表示赢过对手，不能接“成绩”；要说“取得好成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
