INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在比赛或争斗中取得胜利。", "primary_collocate": null, "pronunciation": "shèng", "ipa": "ʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "打了三年官司，他终于胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场战斗，我们胜了，敌人败了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两只公鸡打架，小的那只胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在选举中，老张胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "辩论赛上，对方胜，我们败。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司争了很久，最后小公司胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摔跤比赛，穿红衣服的人胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场争斗，最后是谁胜了？", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打赌，结果我胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争打了十年，最后正义胜了。", "target_word": "胜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "胜了", "label": "完成体"}, {"form": "勝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：在比赛、争斗、官司中取得胜利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9817eddc-23bc-408e-991b-9208b428aded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确答案。胜：在比赛、争斗、官司中取得胜利。"}, {"text": "声", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是声音。"}, {"text": "省", "is_correct": false, "explanation": "声调不同：shěng（第三声）与 shèng（第四声）不同，意思是省份。"}, {"text": "绳", "is_correct": false, "explanation": "声调不同：shéng（第二声）与 shèng（第四声）不同，意思是绳子。"}, {"text": "升", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是升降、容量单位。"}], "explanations": {"胜": "正确答案。胜：在比赛、争斗、官司中取得胜利。", "声": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是声音。", "省": "声调不同：shěng（第三声）与 shèng（第四声）不同，意思是省份。", "绳": "声调不同：shéng（第二声）与 shèng（第四声）不同，意思是绳子。", "升": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是升降、容量单位。"}, "sentence_index": null, "correct_answer": "胜"}, "level_3": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确。“他终于胜了”表示打了很久的官司后他赢了。"}, {"text": "唱", "is_correct": false, "explanation": "语义：官司的结果不能用“唱”来表示，句中的语境是打官司。"}, {"text": "游", "is_correct": false, "explanation": "语义：打官司的过程中没有“游”的含义，与句中语境冲突。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”需要宾语，“他终于修了”不成句，与打官司也无关。"}], "explanations": {"胜": "正确。“他终于胜了”表示打了很久的官司后他赢了。", "唱": "语义：官司的结果不能用“唱”来表示，句中的语境是打官司。", "游": "语义：打官司的过程中没有“游”的含义，与句中语境冲突。", "修": "搭配：“修”需要宾语，“他终于修了”不成句，与打官司也无关。"}, "sentence_index": 0, "correct_answer": "胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他胜了奖金。", "explanation": "这里应该用〈获得〉。“胜”的宾语是对手，不能接“奖金”；要说“获得奖金”。"}, {"text": "他胜了大家的心。", "explanation": "这里应该用〈赢得〉。“胜”只用于比赛、争斗，不能接“大家的心”；要说“赢得大家的心”。"}, {"text": "他胜了这顿饭。", "explanation": "这里应该用〈吃〉。“胜”只用于比赛、争斗等对抗情境，吃饭不是对抗，不能用“胜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确答案。胜：在比赛、争斗、官司中取得胜利。"}, {"text": "生", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是出生、生活。"}, {"text": "笙", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是一种吹奏乐器。"}, {"text": "牲", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是牲畜。"}, {"text": "甥", "is_correct": false, "explanation": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是外甥。"}], "explanations": {"胜": "正确答案。胜：在比赛、争斗、官司中取得胜利。", "生": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是出生、生活。", "笙": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是一种吹奏乐器。", "牲": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是牲畜。", "甥": "声调不同：shēng（第一声）与 shèng（第四声）不同，意思是外甥。"}, "sentence_index": null, "correct_answer": "胜"}, "level_3": {"options": [{"text": "胜", "is_correct": true, "explanation": "正确。“穿红衣服的人胜了”表示在摔跤比赛中取得了胜利。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与摔跤比赛的结果无关，句中没有饮用的语境。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”与摔跤比赛的结果无关，句中没有绘画的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用来表示比赛的结果，与“穿红衣服的人”搭配不当。"}], "explanations": {"胜": "正确。“穿红衣服的人胜了”表示在摔跤比赛中取得了胜利。", "喝": "语义：“喝”与摔跤比赛的结果无关，句中没有饮用的语境。", "画": "语义：“画”与摔跤比赛的结果无关，句中没有绘画的语境。", "吃": "搭配：“吃”不能用来表示比赛的结果，与“穿红衣服的人”搭配不当。"}, "sentence_index": 6, "correct_answer": "胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他胜了荣誉。", "explanation": "这里应该用〈取得〉。“胜”的宾语是对手，不能接“荣誉”；要说“取得荣誉”。"}, {"text": "他胜了这份工作。", "explanation": "这里应该用〈胜任〉。“胜”表示取胜，不能接“工作”；要说“胜任这份工作”。"}, {"text": "他胜了一场考试。", "explanation": "这里应该用〈通过〉。“胜”只用于比赛、争斗、官司等对抗情境，考试没有对手，要说“通过考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场官司，原告被胜了。", "corrected_sentence": "这场官司，原告胜了。", "error_description": "错误形式是“被胜了”，正确形式是“胜了”。“胜”是不及物的取胜义动词，不能用“被”构成被动句，应直接说“原告胜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场官司，原告没胜了。", "corrected_sentence": "这场官司，原告没胜。", "error_description": "错误形式是“没胜了”，正确形式是“没胜”。否定句中“没”后面不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7832cc5f-560e-4b99-b395-5b636dfc5de3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
